// Phase 3 — test seam for the Trading-API network call.
// Overridable in unit tests; defaults to the real Phase-1 fn.
export const __ebayTrading = {
  reviseInventoryStatus: ebayReviseInventoryStatus,
  reviseInventoryStatusBatch: ebayReviseInventoryStatusBatch,
}

// RT.2 — per-item revise pacing. eBay hard-caps ~250 revises per listing per
// CALENDAR DAY (each ReviseInventoryStatus CALL counts once, hence the ≤4-SKU
// batching). The debounce spaces successive revises of one ItemID; a debounced
// row re-arms via the deferral disposition WITHOUT consuming retry budget, and
// coalescing usually replaces it with a fresher row before it re-fires.
const EBAY_REVISE_MIN_INTERVAL_MS = Number(process.env.NEXUS_EBAY_REVISE_MIN_INTERVAL_MS ?? 15_000);
const EBAY_REVISE_DAILY_WARN = Number(process.env.NEXUS_EBAY_REVISE_DAILY_WARN ?? 150);
const _reviseDayCounts = new Map<string, { day: string; count: number }>();

/** Count a Trading revise call for an item; returns today's total (UTC day). */
export function countEbayReviseCall(itemId: string, now: number = Date.now()): number {
  const day = new Date(now).toISOString().slice(0, 10);
  const cur = _reviseDayCounts.get(itemId);
  if (!cur || cur.day !== day) {
    _reviseDayCounts.set(itemId, { day, count: 1 });
    return 1;
  }
  cur.count += 1;
  return cur.count;
}

// Advertising mutations (bids/budgets/state) ride the same OutboundSyncQueue
// table but are owned exclusively by the dedicated ads-sync worker
// (ads-sync.worker.ts → dispatchToAmazon, gated by checkAdsWriteGate). This
// generic listings processor must NOT pick them up — routing an AD_BID_UPDATE
// through syncToAmazon (the listings PATCH path) fails it at the listings
// publish gate and starves the real ads dispatcher. Exclude them from both the
// pending and retry selections.
const AD_SYNC_TYPES = [
  "AD_BID_UPDATE",
  "AD_BUDGET_UPDATE",
  "AD_ENTITY_STATE_UPDATE",
  "AD_BIDDING_STRATEGY_UPDATE",
] as const;

// ── RT.0 — failure disposition (cron drain path) ────────────────────────────
// The old handleSyncFailure burned the 3-attempt budget in 2s/4s/8s — inside a
// single 10-minute circuit-open episode every attempt fails and the row goes
// terminally FAILED (invisible: no isDead). New semantics:
//   • circuit-open / rate-limited failures are DEFERRALS: retryCount is NOT
//     consumed, the row re-arms after the episode should have passed.
//   • genuinely retryable failures back off 30s / 2m / 10m (+ jitter ≤20%).
//   • non-retryable (validation-class) failures are terminal immediately.
//   • every terminal row is dead-lettered (isDead + diedAt + SYNC_DEAD event)
//     for parity with the BullMQ worker path (P3.2).

const RETRY_BACKOFF_MS = [30_000, 120_000, 600_000] as const;
const CIRCUIT_DEFER_MS = 5 * 60_000;
const RATE_LIMIT_DEFER_MS = 60_000;
// AS.1 — auth-class outages (revoked token / missing authorization role) are
// account-level episodes: no retry can succeed until the credential is fixed,
// so burning the 3-attempt budget just converts the whole queue into
// MAX_RETRIES_EXCEEDED dead-letters (812 measured during the 2026-07-20 403
// incident). Defer longer than a circuit episode; the latency-watchdog
// tripwire (CHANNEL_AUTH_FAILURE) owns making the outage visible.
const AUTH_DEFER_MS = 15 * 60_000;
// Matches the P0b-era honest client messages ("HTTP 403 — Unauthorized:
// Access to requested resource is denied.") and LWA refresh failures.
// Deliberately narrow: eBay transient 401s ("Invalid access token") keep
// their existing transient/circuit classification and self-heal via token
// refresh.
const AUTH_CLASS_RE = /Unauthorized|invalid_grant|Access to requested resource is denied/i;

export function withJitter(ms: number): number {
  return Math.round(ms * (1 + Math.random() * 0.2));
}

export type FailureDisposition =
  | { kind: "deferral"; nextRetryAt: Date; errorCode: "CIRCUIT_OPEN_DEFERRED" | "AUTH_REQUIRED" }
  | { kind: "terminal"; errorCode: string }
  | { kind: "retry"; nextRetryAt: Date; errorCode: "RETRY_SCHEDULED" };

export function computeFailureDisposition(
  queueItem: { retryCount: number; maxRetries?: number | null },
  errorMessage: string,
  opts?: { errorCode?: string; retryable?: boolean },
  now: number = Date.now(),
): FailureDisposition {
  const isCircuitOpen =
    opts?.errorCode === "EBAY_CIRCUIT_OPEN" || /circuit open/i.test(errorMessage);
  const isRateLimited =
    opts?.errorCode === "EBAY_RATE_LIMITED" || /rate limit/i.test(errorMessage);
  // RT.2 — a debounced revise is episode-style too: re-arm shortly, no budget.
  // SC.5-fix — ALSO match the message: any path that drops the errorCode
  // (measured 2026-07-20: 20 debounce dead-letters) must still defer.
  const isDebounced =
    opts?.errorCode === "EBAY_REVISE_DEBOUNCED" || /debounced:/i.test(errorMessage);
  if (isCircuitOpen || isRateLimited || isDebounced) {
    const defer = isCircuitOpen ? CIRCUIT_DEFER_MS : RATE_LIMIT_DEFER_MS;
    return {
      kind: "deferral",
      nextRetryAt: new Date(now + withJitter(defer)),
      errorCode: "CIRCUIT_OPEN_DEFERRED",
    };
  }
  if (opts?.errorCode === "AUTH_REQUIRED" || AUTH_CLASS_RE.test(errorMessage)) {
    return {
      kind: "deferral",
      nextRetryAt: new Date(now + withJitter(AUTH_DEFER_MS)),
      errorCode: "AUTH_REQUIRED",
    };
  }
  if (opts?.retryable === false) {
    return { kind: "terminal", errorCode: opts?.errorCode ?? "NON_RETRYABLE" };
  }
  const newRetryCount = queueItem.retryCount + 1;
  const maxRetries = queueItem.maxRetries || 3;
  if (newRetryCount >= maxRetries) {
    return { kind: "terminal", errorCode: "MAX_RETRIES_EXCEEDED" };
  }
  const backoff =
    RETRY_BACKOFF_MS[Math.min(newRetryCount - 1, RETRY_BACKOFF_MS.length - 1)];
  return {
    kind: "retry",
    nextRetryAt: new Date(now + withJitter(backoff)),
    errorCode: "RETRY_SCHEDULED",
  };
}

// ── RT.0 — eBay "listing ended" auto-heal ───────────────────────────────────
// Trading-API failures arrive as Ack=Failure with an error code in the thrown
// message, e.g.: `eBay ReviseInventoryStatus Failure: Non puoi modificare
// un'inserzione scaduta "256552369326". (code 21916750)`. A dead listing is a
// PER-LISTING terminal condition: pushing at it can never succeed, and letting
// it record circuit outcomes froze the whole marketplace lane for ~10 minutes
// per episode (measured incident, 2026-07-19). Fail-closed: only the codes
// below auto-end a membership; everything else keeps the existing behavior.
const EBAY_ENDED_LISTING_CODES = new Set(
  (process.env.NEXUS_EBAY_ENDED_CODES ?? "21916750")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean),
);

export function matchEbayEndedListingCode(message: string): string | null {
  for (const m of message.matchAll(/\(code (\d+)\)/g)) {
    if (EBAY_ENDED_LISTING_CODES.has(m[1])) return m[1];
  }
  return null;
}

// ── eBay payload helpers (Phase 0.1) ───────────────────────────────────────
// On eBay, price lives on the OFFER and quantity on the inventory_item — two
// different endpoints — and createOrReplaceInventoryItem REPLACES the whole
// item, so we GET-merge-PUT to avoid wiping listing content. The prior single
// inventory_item PUT put price on the item, used the wrong qty key, and
// hardcoded USD, so master price/stock changes silently never reached eBay.

export function ebayCurrencyForMarket(marketplaceId: string | undefined): string {
  return marketplaceId === "EBAY_GB" ? "GBP" : "EUR";
}

/** eBay Inventory API requires BOTH language headers set to the marketplace
 *  locale, plus the marketplace id, on every call (error 25709 otherwise). */
export function ebayInventoryHeaders(token: string, marketplaceId: string): Record<string, string> {
  const mp2 = (marketplaceId ?? "EBAY_IT").replace(/^EBAY_/, "");
  const lang = toListingLanguage(mp2);
  return {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
    Accept: "application/json",
    "Content-Language": lang,
    "Accept-Language": lang,
    "X-EBAY-C-MARKETPLACE-ID": marketplaceId ?? "EBAY_IT",
  };
}

/** Merge quantity/content into an existing inventory_item so the createOrReplace
 *  PUT doesn't drop the rest of the listing. */
export function mergeEbayInventoryItem(
  existing: Record<string, any>,
  payload: { quantity?: number; title?: string; description?: string; images?: string[]; mappingAspects?: Record<string, string[] | null> },
): Record<string, any> {
  const merged: Record<string, any> = { ...existing };
  if (payload.quantity !== undefined) {
    merged.availability = {
      ...(existing.availability ?? {}),
      shipToLocationAvailability: { quantity: payload.quantity },
    };
  }
  if (payload.title || payload.description || (payload.images && payload.images.length > 0)) {
    merged.product = { ...(existing.product ?? {}) };
    if (payload.title) merged.product.title = payload.title;
    if (payload.description) merged.product.description = payload.description;
    if (payload.images && payload.images.length > 0) merged.product.imageUrls = payload.images;
  }
  if (payload.mappingAspects) {
    merged.product = { ...(merged.product ?? {}) };
    const aspects = { ...(merged.product.aspects ?? {}) };
    for (const [name, value] of Object.entries(payload.mappingAspects)) {
      if (value === null) delete aspects[name];
      else aspects[name] = value;
    }
    merged.product.aspects = aspects;
  }
  return merged;
}

/** Update an existing offer's price, preserving its other fields. */
export function buildEbayOfferUpdate(
  existingOffer: Record<string, any>,
  price: number,
  currency: string,
): Record<string, any> {
  return {
    ...existingOffer,
    pricingSummary: { price: { value: price.toFixed(2), currency } },
  };
}

// Amazon EU marketplace IDs (Phase 0.2). The price PATCH was hardcoded to the
// US marketplace (ATVPDKIKX0DER) for an Amazon-IT seller; resolve the listing's
// real marketplace, defaulting to IT (the primary market) — never US.
const AMAZON_MARKETPLACE_IDS: Record<string, string> = {
  IT: "APJ6JRA9NG5V4", DE: "A1PA6795UKMFR9", FR: "A13V1IB3VIYZZH", ES: "A1RKKUPIHCS9HS",
  NL: "A1805IZSGTT6HS", SE: "A2NODRKZP88ZB9", PL: "A1C3SOZRARQ6R3", BE: "AMEN7PMS3EDWL",
  IE: "A28R8C7NBKEWEA", UK: "A1F83G8C2ARO7P", GB: "A1F83G8C2ARO7P", US: "ATVPDKIKX0DER",
};

export function resolveAmazonMarketplaceId(mp: string | undefined): string {
  if (!mp) return AMAZON_MARKETPLACE_IDS.IT;
  if (/^A[A-Z0-9]{9,}$/.test(mp)) return mp; // already a full Amazon marketplace id
  return AMAZON_MARKETPLACE_IDS[mp.toUpperCase()] ?? AMAZON_MARKETPLACE_IDS.IT;
}

/**
 * A4.0 — build a CORRECT Amazon Listings Items PATCH body. The old
 * constructAmazonPayload emitted non-schema attribute names (`title`, `price`,
 * `fulfillmentAvailability`) inside a bare `{attributes}` object — Amazon's PATCH
 * needs `{ productType, patches: [{op,path:/attributes/<name>,value}] }` with the
 * real schema names (item_name / product_description / bullet_point /
 * purchasable_offer / fulfillment_availability) and value shapes. Mirrors the
 * proven buildJsonFeedBody attribute shapes; same serializer semantics everywhere.
 */
export async function buildAmazonListingPatch(
  payload: SyncPayload,
  marketplaceCode: string,
  productType: string,
  fulfillmentMethod?: string | null,
): Promise<Record<string, any>> {
  const rawCode = (marketplaceCode || "IT").toUpperCase();
  const code = Object.entries(AMAZON_MARKETPLACE_IDS).find(([, id]) => id === rawCode)?.[0] ?? rawCode;
  const marketplaceId = resolveAmazonMarketplaceId(code);
  const hasContent = !!(payload.title || payload.description || payload.bulletPoints?.length);
  const languages = hasContent ? await marketLanguages('AMAZON', code) : [];
  const language = payload.language ?? languages[0];
  if (hasContent) assertInformationLocale('AMAZON', language, languages);
  const language_tag = hasContent ? languageTag(language, code) : undefined;
  const currency = code === "UK" || code === "GB" ? "GBP" : "EUR";
  const isFba = String(fulfillmentMethod ?? "").toUpperCase() === "FBA";
  const attrs: Record<string, any> = {};

  if (payload.title) {
    attrs.item_name = [{ value: String(payload.title), marketplace_id: marketplaceId, language_tag }];
  }
  if (payload.description) {
    attrs.product_description = [{ value: String(payload.description), marketplace_id: marketplaceId, language_tag }];
  }
  const bullets = (payload as any).bulletPoints;
  if (Array.isArray(bullets) && bullets.length > 0) {
    attrs.bullet_point = bullets.filter(Boolean).map((b: any) => ({ value: String(b), marketplace_id: marketplaceId, language_tag }));
  }
  if (payload.price !== undefined) {
    attrs.purchasable_offer = [{ currency, our_price: [{ schedule: [{ value_with_tax: payload.price }] }], marketplace_id: marketplaceId }];
  }
  // B2 — FBA stock is owned by Amazon. Pushing a merchant fulfillment_availability
  // (DEFAULT channel) for an FBA SKU flips the offer to FBM and overwrites Amazon's
  // managed quantity. So only emit a merchant quantity for FBM (or unknown — the
  // common, safe default). For FBA we leave fulfillment untouched (handled upstream).
  if (payload.quantity !== undefined && !isFba) {
    // P0b — canonical schema shape: fulfillment_availability entries carry
    // fulfillment_channel_code + quantity ONLY (channel-scoped, not
    // marketplace-scoped; the marketplace comes from the ?marketplaceIds
    // query param). The stray marketplace_id predates the incident.
    attrs.fulfillment_availability = [{ fulfillment_channel_code: "DEFAULT", quantity: payload.quantity }];
  }

  return {
    productType,
    patches: [...Object.entries(attrs).map(([k, v]) => ({ op: "replace", path: `/attributes/${k}`, value: v })), ...(payload.source === 'FM_CATALOG_CASCADE' ? payload.mappingAttributePatches ?? [] : [])],
  };
}

/**
 * B2 / FBA-flip fix — is this Amazon listing FBA (Amazon-fulfilled)? Returns true
 * (⇒ caller must NOT push a merchant DEFAULT quantity) on ANY FBA signal:
 *   • the listing's explicit FBA method, or a persisted AMAZON_* channel code;
 *   • Product.fulfillmentMethod === 'FBA' — STANDALONE, no longer gated on the
 *     listing method being null. A stale/wrong listing 'FBM' must not authorize a
 *     flip: that gate is exactly what let real FBA offers get flipped to FBM;
 *   • positive FBA evidence the caller resolved (FBA stock on hand / active FBA offer).
 * Fail-closed: when fulfillment is ambiguous we treat it as FBA and SKIP the qty
 * push. Cost = a missed merchant-qty sync for a genuinely-FBM listing of an
 * FBA-default product (benign, recoverable); avoided cost = flipping an FBA offer to
 * "Venduto e spedito da …" (catastrophic). Pure + testable.
 */
export function isFbaListing(
  listing: { fulfillmentMethod?: string | null; platformAttributes?: any } | null | undefined,
  product: { fulfillmentMethod?: string | null } | null | undefined,
  evidence?: { fbaStockQty?: number | null; hasActiveFbaOffer?: boolean | null },
): boolean {
  const faChannel = String(
    (listing?.platformAttributes as any)?.fulfillment_availability?.[0]?.fulfillment_channel_code ?? "",
  ).toUpperCase();
  return (
    listing?.fulfillmentMethod === "FBA" ||
    faChannel.startsWith("AMAZON") ||
    String(product?.fulfillmentMethod ?? "").toUpperCase() === "FBA" ||
    (evidence?.fbaStockQty != null && evidence.fbaStockQty > 0) ||
    evidence?.hasActiveFbaOffer === true
  );
}

/**
 * B3 — map a master CONTENT_UPDATE payload to a Shopify Admin API product
 * update body. Title is pushed only when non-empty (Shopify rejects an empty
 * product title); description → body_html (an explicit '' clears the body).
 * Returns null when there's no Shopify-supported field to push (e.g. a
 * bullets-only change) OR the product id is unusable — caller skips the PUT.
 * Pure + testable. (bulletPoints → body_html merge = follow-up B3.1.)
 */
export function buildShopifyProductUpdate(
  shopifyProductId: string | number | null | undefined,
  payload: { title?: string | null; description?: string | null },
): { product: Record<string, unknown> } | null {
  const numId = typeof shopifyProductId === "string" ? parseInt(shopifyProductId, 10) : shopifyProductId;
  if (!numId || Number.isNaN(numId)) return null;
  const product: Record<string, unknown> = { id: numId };
  let has = false;
  if (payload.title != null && String(payload.title).trim() !== "") {
    product.title = String(payload.title);
    has = true;
  }
  if (payload.description !== undefined) {
    product.body_html = payload.description == null ? "" : String(payload.description);
    has = true;
  }
  return has ? { product } : null;
}

/**
 * Phase 1 — at dispatch time, the freshest committed quantity is the current
 * ChannelListing.quantity (the cascade always updates it transactionally to the
 * latest value). Pushing that instead of the payload snapshot prevents a stale
 * in-flight job from overwriting a newer value (last-writer-wins). `0` is a real
 * value (out of stock) and must not be treated as falsy.
 */
export function resolveDispatchQuantity(
  currentListingQty: number | null | undefined,
  payloadQty: number | null | undefined,
): number | undefined {
  if (typeof currentListingQty === 'number') return currentListingQty
  return payloadQty ?? undefined
}

/**
 * Phase 2 — hard oversell guard. Clamp a requested dispatch quantity to what
 * the backing pool can actually ship. `clamped` flags an overshoot so the
 * caller can emit a sync.oversell.clamped event (never silent). Pure.
 */
export function applyOversellClamp(
  requested: number,
  available: number,
): { quantity: number; clamped: boolean } {
  if (requested > available) return { quantity: available, clamped: true }
  return { quantity: requested, clamped: false }
}

// ── Data Structures ──────────────────────────────────────────────────────

interface SyncPayload {
  price?: number;
  quantity?: number;
  categoryAttributes?: Record<string, any>;
  title?: string;
  description?: string;
  images?: string[];
  [key: string]: any;
}

interface QueueResult {
  success: boolean;
  queueId?: string;
  message: string;
}

interface SyncResult {
  success: boolean;
  queueId: string;
  channel: string;
  status: string;
  message: string;
  error?: string;
  /** Stable error classifier (e.g. EBAY_VALIDATION, EBAY_TRANSIENT). Copied
   *  by the BullMQ worker onto OutboundSyncQueue.errorCode so the operator
   *  sees the real cause instead of the downstream circuit-open message. */
  errorCode?: string;
  retryable?: boolean;
  /** PD.3 — true when the "success" was a dry-run/sandbox no-op (nothing actually
   *  published). The worker marks these SKIPPED, not SUCCESS, so the grid doesn't
   *  show false green. */
  dryRun?: boolean;
}

interface ProcessingStats {
  processed: number;
  succeeded: number;
  failed: number;
  skipped: number;
  errors: Array<{ queueId: string; error: string }>;
}

// ── Outbound Sync Service ────────────────────────────────────────────────

/**
 * Classify an eBay API failure by HTTP status so the operator sees a stable
 * code on the queue row rather than the downstream "circuit open" message.
 *
 * 400/404/409/422 = the listing or payload is wrong; retrying won't help and
 * must NOT back off the whole marketplace (EBAY_VALIDATION).
 * Everything else (401/403/429/5xx, network/null) is transient/connection-level:
 * retry + trip the circuit (EBAY_TRANSIENT).
 *
 * retryable / tripsCircuit are wired into the circuit-breaker in Task 3;
 * only `code` is consumed in Task 2.
 */
export function classifyEbayFailure(httpStatus: number | null): {
  code: 'EBAY_VALIDATION' | 'EBAY_TRANSIENT';
  retryable: boolean;
  tripsCircuit: boolean;
} {
  const listingFatal = httpStatus != null && [400, 404, 409, 422].includes(httpStatus);
  return listingFatal
    ? { code: 'EBAY_VALIDATION', retryable: false, tripsCircuit: false }
    : { code: 'EBAY_TRANSIENT', retryable: true, tripsCircuit: true };
}

/**
 * Task 3 — pure decision helper for `ebayFail`.
 *
 * Determines, for a given failure, whether the marketplace circuit breaker
 * should be tripped and whether the queue row should be retried.
 *
 * Kill-switch: `NEXUS_EBAY_FAILURE_ISOLATION`
 *   - default (absent or any value ≠ '0'): isolation ON — validation errors
 *     do NOT trip the circuit and are marked non-retryable (terminal FAILED).
 *   - '0': isolation OFF — preserve pre-Task-3 behavior (always record toward
 *     the circuit; retryable left for the worker's default true logic).
 *
 * Exported so it can be unit-tested as a pure function without mocking.
 */
export function ebayFailureDecision(
  httpStatus: number | null | undefined,
  isolationEnabled: boolean,
): { record: boolean; retryable: boolean; code: 'EBAY_VALIDATION' | 'EBAY_TRANSIENT' } {
  const c = classifyEbayFailure(httpStatus ?? null);
  if (!isolationEnabled) {
    // Kill-switch '0': always record toward circuit, retryable stays true
    return { record: true, retryable: true, code: c.code };
  }
  return { record: c.tripsCircuit, retryable: c.retryable, code: c.code };
}

/**
 * PD-Q — bound a promise so one hung downstream call (SP-API / Redis) can never
 * wedge the sync loop. On timeout it rejects; the caller's per-item catch marks
 * the row FAILED-retryable and moves on.
 */
export function withTimeout<T>(p: Promise<T>, ms: number, label: string): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((_, reject) =>
      setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms),
    ),
  ]);
}

/** Per-item dispatch ceiling for the backstop loop (env-overridable). */
const DISPATCH_TIMEOUT_MS = Math.max(5_000, Number(process.env.NEXUS_SYNC_DISPATCH_TIMEOUT_MS ?? '45000') || 45_000);

export class OutboundSyncService {
  private stats = {
    queued: 0,
    processed: 0,
    succeeded: 0,
    failed: 0,
  };

  /**
   * Queue a product update for outbound sync to a specific channel
   */
  async queueProductUpdate(
    productId: string,
    targetChannel: "AMAZON" | "EBAY" | "SHOPIFY" | "WOOCOMMERCE",
    syncType: "PRICE_UPDATE" | "QUANTITY_UPDATE" | "ATTRIBUTE_UPDATE" | "FULL_SYNC",
    payload: SyncPayload
  ): Promise<QueueResult> {
    try {
      // Verify product exists
      const product = await prisma.product.findUnique({
        where: { id: productId },
      });

      if (!product) {
        return {
          success: false,
          message: `Product ${productId} not found`,
        };
      }

      // Create queue entry
      const queueEntry = await prisma.outboundSyncQueue.create({
        data: {
          productId,
          targetChannel,
          syncStatus: "PENDING",
          syncType,
          payload,
          retryCount: 0,
          maxRetries: 3,
          externalListingId: this.getExternalListingId(product, targetChannel),
        },
      });

      // RT.2 — instant lane (covers every queueProductUpdate caller at once);
      // dynamic import avoids a static cycle, addJobSafely never hangs.
      void import("./outbound-enqueue.js")
        .then(({ fireOutboundJobs }) =>
          fireOutboundJobs(
            [{ id: queueEntry.id, productId, syncType, holdUntil: null }],
            { source: "QUEUE_PRODUCT_UPDATE" },
          ),
        )
        .catch(() => {});

      this.stats.queued++;

      return {
        success: true,
        queueId: queueEntry.id,
        message: `Product queued for ${targetChannel} sync`,
      };
    } catch (error) {
      console.error("Error queuing product update:", error);
      return {
        success: false,
        message: `Failed to queue product: ${error instanceof Error ? error.message : "Unknown error"}`,
      };
    }
  }

  /** A2.1 — route one queue item to the right channel sync method. */
  private async dispatchSync(item: any): Promise<SyncResult> {
    if (item.payload?.source === 'FM_CATALOG_CASCADE') {
      const { prepareMappingDispatch } = await import('./pim/mapping/prepare-dispatch.js');
      item = await prepareMappingDispatch(item);
    }
    switch (item.targetChannel) {
      case "AMAZON": return this.syncToAmazon(item);
      case "EBAY": return this.syncToEbay(item);
      case "SHOPIFY": return this.syncToShopify(item);
      case "WOOCOMMERCE": return this.syncToWoocommerce(item);
      default: throw new Error(`Unknown channel: ${item.targetChannel}`);
    }
  }

  /**
   * A2.1 — process exactly ONE queue row (the row a BullMQ job owns) instead of
   * draining the whole table. Guards (PENDING / not CANCELLED / past holdUntil),
   * marks IN_PROGRESS, dispatches, and returns the result. The caller owns the
   * final status write (the BullMQ worker's per-job update), so this never
   * touches any other row.
   */
  async processSingle(queueId: string): Promise<SyncResult> {
    const item = await prisma.outboundSyncQueue.findUnique({
      where: { id: queueId },
      include: { product: true },
    });
    if (!item) {
      return { success: false, queueId, channel: "UNKNOWN", status: "FAILED", message: `Queue row ${queueId} not found`, error: "queue-row-not-found" };
    }
    if ((item.syncStatus as any) === "CANCELLED") {
      return { success: false, queueId, channel: item.targetChannel, status: "SKIPPED", message: "Cancelled during grace period", error: "cancelled" };
    }
    if (item.syncStatus !== "PENDING") {
      return { success: false, queueId, channel: item.targetChannel, status: "SKIPPED", message: `Not PENDING (${item.syncStatus})`, error: "not-pending" };
    }
    if (item.holdUntil && item.holdUntil > new Date()) {
      return { success: false, queueId, channel: item.targetChannel, status: "SKIPPED", message: "Still within grace window", error: "held" };
    }
    // P7 B2 — respect the offerActive suppress flag. OPT-IN (default OFF): only
    // when NEXUS_RESPECT_OFFER_ACTIVE=1 do we skip pushing to a suppressed offer.
    // Default-off so existing offerActive=false rows are unaffected until enabled.
    if (process.env.NEXUS_RESPECT_OFFER_ACTIVE === '1' && item.channelListingId) {
      const cl = await prisma.channelListing.findUnique({
        where: { id: item.channelListingId },
        select: { offerActive: true },
      }).catch(() => null)
      if (cl && cl.offerActive === false) {
        return { success: false, queueId, channel: item.targetChannel, status: "SKIPPED", message: "Offer suppressed (offerActive=false)", error: "offer-suppressed" }
      }
    }
    // AS.5 — atomic claim (compare-and-swap on status). The 60s cron backstop
    // and this BullMQ path can race the same row: buildBullMQSkip is TOCTOU
    // and fails open on Redis timeouts. Whoever loses the CAS walks away
    // instead of double-dispatching a duplicate marketplace write.
    const claimed = await prisma.outboundSyncQueue.updateMany({
      where: { id: item.id, syncStatus: "PENDING" },
      data: { syncStatus: "IN_PROGRESS" },
    });
    if (claimed.count === 0) {
      return { success: false, queueId, channel: item.targetChannel, status: "SKIPPED", message: "Lost dispatch claim (already being processed)", error: "claim-lost" };
    }
    try {
      return await withTimeout(this.dispatchSync(item), DISPATCH_TIMEOUT_MS, `dispatchSync(${item.targetChannel}/${item.id})`);
    } catch (err) {
      // dispatch threw (e.g. unknown channel) — don't leave the row stuck IN_PROGRESS.
      await prisma.outboundSyncQueue.update({ where: { id: item.id }, data: { syncStatus: "PENDING" } }).catch(() => {});
      throw err;
    }
  }

  /**
   * Process all pending syncs in the queue.
   * A2.3 — `opts.skip` lets the cron act as a BACKSTOP when BullMQ is enabled: it
   * skips rows that already have a live BullMQ job, so the cron only sweeps
   * orphans (rows written without a job, or jobs that died).
   */
  async processPendingSyncs(opts?: { skip?: (queueId: string) => Promise<boolean> }): Promise<ProcessingStats> {
    const stats: ProcessingStats = {
      processed: 0,
      succeeded: 0,
      failed: 0,
      skipped: 0,
      errors: [],
    };

    try {
      // Get all pending syncs that have either passed their grace
      // window or never had one. TECH_DEBT #49 — without the holdUntil
      // filter, any caller that wrote an OutboundSyncQueue row without
      // ALSO adding a BullMQ job (legacy paths, raw imports, manual
      // SQL) bypassed the 5-minute undo window because BullMQ's job
      // delay was the only thing deferring processing. This filter
      // mirrors outbound-sync-phase9.service.ts:332's getReadyItems().
      const now = new Date();
      const pendingItems = await prisma.outboundSyncQueue.findMany({
        where: {
          syncStatus: "PENDING",
          syncType: { notIn: [...AD_SYNC_TYPES] },
          OR: [{ holdUntil: null }, { holdUntil: { lte: now } }],
        },
        include: {
          product: true,
        },
        orderBy: {
          createdAt: "asc",
        },
      });

      console.log(`Processing ${pendingItems.length} pending syncs`);

      for (const item of pendingItems) {
        if (opts?.skip && (await opts.skip(item.id))) {
          stats.skipped++;
          continue;
        }
        try {
          // AS.5 — atomic claim (see processSingle): only proceed if this
          // loop wins the PENDING→IN_PROGRESS compare-and-swap.
          const claimed = await prisma.outboundSyncQueue.updateMany({
            where: { id: item.id, syncStatus: "PENDING" },
            data: { syncStatus: "IN_PROGRESS" },
          });
          if (claimed.count === 0) {
            stats.skipped++;
            continue;
          }

          // PD-Q — a hung SP-API/Redis call must not deadlock the whole loop.
          const result = await withTimeout(
            this.dispatchSync(item),
            DISPATCH_TIMEOUT_MS,
            `dispatchSync(${item.targetChannel}/${item.id})`,
          );

          if (result.success) {
            // Mark as successful
            await prisma.outboundSyncQueue.update({
              where: { id: item.id },
              data: {
                // PD.3 — a dry-run/sandbox no-op must not show as green SUCCESS.
                syncStatus: result.dryRun ? "SKIPPED" : "SUCCESS",
                syncedAt: new Date(),
              },
            });
            stats.succeeded++;
          } else {
            // Handle retry logic
            await this.handleSyncFailure(item, result.error || "Unknown error", {
              errorCode: result.errorCode,
              retryable: result.retryable,
            });
            stats.failed++;
            stats.errors.push({
              queueId: item.id,
              error: result.error || "Unknown error",
            });
          }

          stats.processed++;
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : "Unknown error";
          await this.handleSyncFailure(item, errorMessage);
          stats.failed++;
          stats.errors.push({
            queueId: item.id,
            error: errorMessage,
          });
          stats.processed++;
        }
      }

      // Get retry items
      const retryItems = await prisma.outboundSyncQueue.findMany({
        where: {
          syncStatus: "FAILED",
          syncType: { notIn: [...AD_SYNC_TYPES] },
          nextRetryAt: {
            lte: new Date(),
          },
          retryCount: {
            lt: 3,
          },
        },
        include: {
          product: true,
        },
      });

      console.log(`Processing ${retryItems.length} retry items`);

      for (const item of retryItems) {
        if (opts?.skip && (await opts.skip(item.id))) {
          stats.skipped++;
          continue;
        }
        try {
          // AS.5 — atomic claim from FAILED (retry lane); mirrors the
          // PENDING-lane compare-and-swap above.
          const claimed = await prisma.outboundSyncQueue.updateMany({
            where: { id: item.id, syncStatus: "FAILED" },
            data: { syncStatus: "IN_PROGRESS" },
          });
          if (claimed.count === 0) {
            stats.skipped++;
            continue;
          }

          // PD-Q — a hung SP-API/Redis call must not deadlock the whole loop.
          const result = await withTimeout(
            this.dispatchSync(item),
            DISPATCH_TIMEOUT_MS,
            `dispatchSync(${item.targetChannel}/${item.id})`,
          );

          if (result.success) {
            await prisma.outboundSyncQueue.update({
              where: { id: item.id },
              data: {
                // PD.3 — a dry-run/sandbox no-op must not show as green SUCCESS.
                syncStatus: result.dryRun ? "SKIPPED" : "SUCCESS",
                syncedAt: new Date(),
              },
            });
            stats.succeeded++;
          } else {
            await this.handleSyncFailure(item, result.error || "Unknown error", {
              errorCode: result.errorCode,
              retryable: result.retryable,
            });
            stats.failed++;
            stats.errors.push({
              queueId: item.id,
              error: result.error || "Unknown error",
            });
          }

          stats.processed++;
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : "Unknown error";
          await this.handleSyncFailure(item, errorMessage);
          stats.failed++;
          stats.errors.push({
            queueId: item.id,
            error: errorMessage,
          });
          stats.processed++;
        }
      }

      return stats;
    } catch (error) {
      console.error("Error processing pending syncs:", error);
      throw error;
    }
  }

  /**
   * Sync product to Amazon using SP-API.
   * PATCH /listings/2021-08-01/items/{sellerId}/{sku}
   *
   * C.8 — replaced the Math.random demo simulator with a real PATCH
   * call routed through amazonSpApiClient.submitListingPayload, gated
   * by the same NEXUS_ENABLE_AMAZON_PUBLISH flag + AMAZON_PUBLISH_MODE
   * resolver as the wizard publish path (C.6). Default state: gated
   * outcome, queue row fails honestly. Set the flag + mode on Railway
   * to enable real updates.
   */
  private async syncToAmazon(queueItem: any): Promise<SyncResult> {
    const { product, payload, id: queueId } = queueItem;
    const sku = product?.sku ?? queueItem.externalListingId ?? "(unknown sku)";
    const marketplaceId =
      payload?.marketplaceId ?? process.env.AMAZON_DEFAULT_MARKETPLACE ?? "IT";
    const sellerId =
      (await getAmazonSellerId());

    // A4.0 — resolve the Amazon product type (required by the Listings PATCH) and
    // build the CORRECT patch body (schema attribute names + value shapes),
    // replacing the malformed constructAmazonPayload.
    let productType = String((payload as any).productType ?? '').toUpperCase();
    // B2 — load the listing ONCE for both productType and fulfillment method.
    let cl: any = null;
    if (queueItem.channelListingId) {
      cl = await prisma.channelListing
        .findUnique({
          where: { id: queueItem.channelListingId },
          select: { platformAttributes: true, fulfillmentMethod: true, quantity: true, stockBuffer: true, marketplace: true, syncPaused: true, offerClosedAt: true },
        })
        .catch(() => null);
    }
    // SC.1 — a paused listing (or a policy-paused channel-market) sends
    // NOTHING until resumed. Dispatch re-checks at send time so a pause set
    // after enqueue still holds.
    if (cl?.syncPaused) {
      return { success: false, queueId, channel: "AMAZON", status: "SKIPPED", message: "Listing sync is PAUSED (Sync Control)", error: "sync-paused" };
    }
    // SCT.6 — a CLOSED market offer receives NO pushes of any kind. Reopen is
    // the only way back; a stray queue row must never resurrect the offer.
    if ((cl as { offerClosedAt?: Date | null } | null)?.offerClosedAt) {
      return { success: false, queueId, channel: "AMAZON", status: "SKIPPED", message: "Market offer is CLOSED (Sync Control) — no pushes until Reopen", error: "market-offer-closed" };
    }
    try {
      const scp = policyFor(await loadChannelPolicies(), 'AMAZON', cl?.marketplace ?? marketplaceId);
      if (scp?.pushesPaused) {
        return { success: false, queueId, channel: "AMAZON", status: "SKIPPED", message: "Channel-market pushes PAUSED (Sync Control policy)", error: "sync-paused-policy" };
      }
    } catch { /* fail-open: policy unreadable = not paused */ }
    if (!productType) productType = String((cl?.platformAttributes as any)?.productType ?? '').toUpperCase();
    if (!productType) productType = String((product as any)?.productType ?? '').toUpperCase();

    // B2 / FBA-flip fix — FBA SKUs must not receive a merchant quantity push (it
    // flips the offer to FBM). The listing's own fulfillmentMethod marker proved
    // unreliable (stale 'FBM' on real FBA listings), so for a quantity push we also
    // resolve positive FBA evidence — FBA stock on hand + an active FBA offer — and
    // fail closed. buildAmazonListingPatch then drops the qty attribute for FBA.
    let fbaStockQty: number | null = null;
    let hasActiveFbaOffer = false;
    if (payload.quantity !== undefined && product?.id) {
      const [fbaAgg, fbaOffer] = await Promise.all([
        prisma.stockLevel
          .aggregate({
            where: { productId: product.id, location: { code: "AMAZON-EU-FBA" } },
            _sum: { quantity: true },
          })
          .catch(() => null),
        queueItem.channelListingId
          ? prisma.offer
              .findFirst({
                where: { channelListingId: queueItem.channelListingId, fulfillmentMethod: "FBA", isActive: true },
                select: { id: true },
              })
              .catch(() => null)
          : Promise.resolve(null),
      ]);
      fbaStockQty = fbaAgg?._sum.quantity ?? null;
      hasActiveFbaOffer = !!fbaOffer;
    }
    const isFba = isFbaListing(cl, product, { fbaStockQty, hasActiveFbaOffer });
    // P1 — push the CURRENT listing quantity (the latest committed value), not
    // the stale enqueue-time snapshot. FBA listings still drop the qty patch
    // below regardless of value. Kill-switch: NEXUS_SYNC_ORDERING_V2=0.
    if (process.env.NEXUS_SYNC_ORDERING_V2 !== '0' && cl && payload.quantity !== undefined) {
      payload.quantity = resolveDispatchQuantity(cl.quantity, payload.quantity);
    }
    // P2 — hard oversell guard for Amazon-FBM. FBA is never clamped (Amazon
    // owns the qty; buildAmazonListingPatch drops the patch for FBA anyway).
    // Kill-switch: NEXUS_OVERSELL_CLAMP=0.
    if (
      process.env.NEXUS_OVERSELL_CLAMP !== '0' &&
      !isFba &&
      payload.quantity !== undefined &&
      product?.id
    ) {
      const whRows = await prisma.stockLevel.findMany({
        where: { productId: product.id, location: { type: 'WAREHOUSE' } },
        select: { available: true },
      })
      const warehouseAvailable = whRows.reduce((s, r) => s + (r.available ?? 0), 0)
      const { available } = computeAvailableToPublish({
        fulfillmentMethod: 'FBM',
        warehouseAvailable,
        fbaSellable: 0,
        stockBuffer: cl?.stockBuffer ?? 0,
      })
      const requested = payload.quantity
      const { quantity, clamped } = applyOversellClamp(requested, available)
      if (clamped) {
        payload.quantity = quantity
        try {
          publishOrderEvent({
            type: 'sync.oversell.clamped',
            sku,
            channel: 'AMAZON',
            marketplace: marketplaceId,
            requested,
            clampedTo: quantity,
            available,
            ts: Date.now(),
          })
        } catch { /* observability must never break the sync */ }
      }
    }
    // SCT.4 — Amazon EU SHARED-QUANTITY belt (kill-switch: NEXUS_EU_SHARED_QTY_GUARD=0).
    // Amazon keeps ONE merchant quantity per SKU across EU marketplaces (proved
    // 2026-07-26: 302 market-scoped Zero&Pins blanked the whole IT storefront).
    // If this SKU's sibling EU rows disagree on the shared number, pushing ANY
    // side would silently overwrite the other market's intent — refuse, log a
    // conflict, and let the operator align the modes instead.
    if (
      process.env.NEXUS_EU_SHARED_QTY_GUARD !== '0' &&
      !isFba &&
      payload.quantity !== undefined &&
      product?.id &&
      AMAZON_EU_SHARED_MARKETS.has(String(cl?.marketplace ?? '').toUpperCase())
    ) {
      try {
        const siblings = await prisma.channelListing.findMany({
          where: {
            productId: product.id,
            channel: 'AMAZON',
            isPublished: true,
            listingStatus: { notIn: ['ENDED', 'REMOVED'] },
          },
          select: {
            marketplace: true, followMasterQuantity: true, quantityOverride: true,
            quantity: true, syncPaused: true, fulfillmentMethod: true,
          },
        })
        const euRows = siblings.map((sib) => ({
          marketplace: sib.marketplace,
          followMasterQuantity: sib.followMasterQuantity,
          quantityOverride: sib.quantityOverride,
          quantity: sib.quantity,
          syncPaused: sib.syncPaused,
          isFba: sib.fulfillmentMethod === 'FBA',
        }))
        const verdict = detectEuIntentConflict(euRows)
        if (verdict.conflict) {
          const message = `EU shared-quantity conflict for ${sku}: ${verdict.detail}. Push refused so no market's intent is silently overwritten. ${EU_GUARD_REMEDY}`
          try {
            const { syncHealthService } = await import('./sync-health.service.js')
            await syncHealthService.logConflict({
              channel: 'AMAZON',
              conflictType: 'EU_SHARED_QTY_CONFLICT',
              message,
              productId: product.id,
              localData: { rows: euRows },
              remoteData: { attemptedQuantity: payload.quantity, marketplace: cl?.marketplace ?? marketplaceId },
            })
          } catch { /* observability best-effort */ }
          return { success: false, queueId, channel: "AMAZON", status: "SKIPPED", message, error: "eu-shared-qty-conflict" };
        }
      } catch (guardErr) {
        // Guard infrastructure failing must not stop legitimate pushes — but say so.
        logger.warn('[outbound-sync] EU shared-qty guard check failed (push allowed)', {
          sku, error: guardErr instanceof Error ? guardErr.message : String(guardErr),
        })
      }
    }
    const amazonPayload = await buildAmazonListingPatch(payload, marketplaceId, productType, isFba ? "FBA" : "FBM");

    // B2 — an FBA quantity-only update yields zero patches (we never touch Amazon's
    // FBA stock). Don't submit an empty patch — return a terminal, no-retry skip.
    if (!Array.isArray(amazonPayload.patches) || amazonPayload.patches.length === 0) {
      return {
        success: true,
        queueId,
        channel: "AMAZON",
        status: "SKIPPED",
        message: isFba
          ? "Skipped — FBA quantity is managed by Amazon (no merchant-qty push)"
          : "Skipped — empty patch (nothing to push)",
      };
    }

    // A1.3 — delegate the gate→circuit→rate-limit→dry-run→audit chain to the
    // shared ListingPublishService; inject Amazon's gate functions + the actual
    // SP-API call. (Behavior-preserving extraction of the former inline chain.)
    const r = await listingPublishService.publish({
      channel: "AMAZON",
      marketplaceId,
      sku,
      productId: product?.id ?? null,
      digest: digestPayload(amazonPayload),
      gate: {
        getMode: getAmazonPublishMode,
        checkCircuit: checkAmazonCircuit,
        acquireToken: acquireAmazonPublishToken,
        recordOutcome: recordAmazonOutcome,
      },
      resolveSeller: async () =>
        sellerId
          ? { id: sellerId }
          : { error: "AMAZON_SELLER_ID is not configured. Set the env var before enabling outbound sync." },
      execute: async ({ sellerId: sid }) => {
        if (payload.source === 'FM_CATALOG_CASCADE') {
          const check = await amazonSpApiClient.validateListing({ sellerId: sid, sku, marketplaceId: resolveAmazonMarketplaceId(marketplaceId), productType, patches: amazonPayload.patches });
          if (!check.available || !check.ok) return { ok: false, error: !check.available ? 'Amazon validation is unavailable; no mapping update was submitted.' : `Amazon validation failed: ${check.errors}` };
        }
        const res = await amazonSpApiClient.submitListingPayload({
          sellerId: sid,
          sku,
          payload: amazonPayload,
          // P0b — REQUIRED patchListingsItem query param; per-market row targets its own market.
          marketplaceId: resolveAmazonMarketplaceId(marketplaceId),
        });
        return { ok: res.success, error: res.error };
      },
    });

    return {
      success: r.success,
      queueId,
      channel: "AMAZON",
      status: r.status,
      message: r.message,
      error: r.error,
      dryRun: r.mode !== "live", // PD.3 — a non-live "success" published nothing.
    };
  }

  /**
   * Sync product to eBay using Inventory API.
   * PUT /sell/inventory/v1/inventory_item/{sku}
   *
   * C.8 — replaced the Math.random demo simulator with a real PUT
   * call gated by NEXUS_ENABLE_EBAY_PUBLISH + EBAY_PUBLISH_MODE
   * (same flags as the wizard publish path, C.7).
   */
  private async syncToEbay(queueItem: any): Promise<SyncResult> {
    // Phase 3 — shared-SKU Trading-API quantity fan-out. These rows have no
    // ChannelListing and must use ReviseInventoryStatus (multi-listing shared
    // SKU), NOT the Inventory-API GET-merge-PUT path below.
    if (queueItem?.payload?.pushVia === 'TRADING') {
      return this.syncSharedTradingQuantity(queueItem);
    }

    const { product, payload, id: queueId } = queueItem;
    const sku = product?.sku ?? queueItem.externalListingId ?? "(unknown sku)";
    const marketplaceId = payload?.marketplaceId ?? "EBAY_IT";

    // FCF.2 / 1.4 — defensive pool cap (defence-in-depth). The cascade now
    // queues reserved-adjusted available, but a stale/pre-fix or manually
    // inserted queue row could carry a quantity above what the warehouse can
    // ship. Clamp FBM eBay quantity to the own-warehouse pool (available −
    // buffer) so the auto-sync path can never oversell — same pool maths as the
    // flat-file manual push (capToFbm). Only triggers on overshoot; FBA-backed
    // (MCF) eBay listings draw the Amazon pool, so they're left to the MCF path.
    if (payload.quantity !== undefined && product?.id) {
      const [whRows, cl] = await Promise.all([
        prisma.stockLevel.findMany({
          where: { productId: product.id, location: { type: "WAREHOUSE" } },
          select: { available: true },
        }),
        queueItem.channelListingId
          ? prisma.channelListing.findUnique({
              where: { id: queueItem.channelListingId },
              select: { stockBuffer: true, fulfillmentMethod: true, quantity: true, marketplace: true, syncPaused: true },
            })
          : Promise.resolve(null),
      ]);
      // SC.1 — pause guard (listing + channel-market policy), re-checked at
      // dispatch time like the Amazon lane.
      if ((cl as { syncPaused?: boolean } | null)?.syncPaused) {
        return { success: false, queueId, channel: "EBAY", status: "SKIPPED", message: "Listing sync is PAUSED (Sync Control)", error: "sync-paused" };
      }
      try {
        const scp = policyFor(await loadChannelPolicies(), 'EBAY', (cl as { marketplace?: string } | null)?.marketplace ?? 'IT');
        if (scp?.pushesPaused) {
          return { success: false, queueId, channel: "EBAY", status: "SKIPPED", message: "Channel-market pushes PAUSED (Sync Control policy)", error: "sync-paused-policy" };
        }
      } catch { /* fail-open */ }
      // P1 — base the eBay push on the CURRENT listing quantity, then apply the
      // warehouse cap below. Kill-switch: NEXUS_SYNC_ORDERING_V2=0.
      if (process.env.NEXUS_SYNC_ORDERING_V2 !== '0' && cl && payload.quantity !== undefined) {
        payload.quantity = resolveDispatchQuantity(cl.quantity, payload.quantity);
      }
      if (cl?.fulfillmentMethod !== "FBA") {
        const warehouseAvailable = whRows.reduce((s, r) => s + r.available, 0);
        const cap = computeAvailableToPublish({
          fulfillmentMethod: "FBM",
          warehouseAvailable,
          fbaSellable: 0,
          stockBuffer: cl?.stockBuffer ?? 0,
        }).available;
        const requested = payload.quantity
        const { quantity: clampedQty, clamped } = applyOversellClamp(requested, cap)
        if (clamped) {
          console.warn(
            `[EBAY] capping ${sku} quantity ${requested} -> ${clampedQty} (warehouse available ${warehouseAvailable}, buffer ${cl?.stockBuffer ?? 0})`,
          );
          payload.quantity = clampedQty;
          try {
            publishOrderEvent({
              type: 'sync.oversell.clamped',
              sku,
              channel: 'EBAY',
              marketplace: marketplaceId,
              requested,
              clampedTo: clampedQty,
              available: cap,
              ts: Date.now(),
            })
          } catch { /* observability must never break the sync */ }
        }
      }
    }

    const digest = digestPayload({
      price: payload.price,
      quantity: payload.quantity,
      content: !!(payload.title || payload.description || (payload.images && payload.images.length > 0)),
    });

    const fail = (
      outcome: "gated" | "rate-limited" | "circuit-open" | "failed" | "timeout",
      mode: "gated" | "dry-run" | "sandbox" | "live",
      sellerId: string,
      message: string,
      durationMs?: number,
    ): SyncResult => {
      writeAttemptLog({
        channel: "EBAY",
        marketplace: marketplaceId,
        sellerId,
        sku,
        productId: product?.id ?? null,
        mode,
        outcome,
        payloadDigest: digest,
        errorMessage: message,
        durationMs: durationMs ?? null,
      });
      return {
        success: false,
        queueId,
        channel: "EBAY",
        status: "FAILED",
        message: `Failed to sync to eBay`,
        error: message,
      };
    };

    // 1. Feature flag
    const mode = getEbayPublishMode();
    if (mode === "gated") {
      return fail(
        "gated",
        "gated",
        marketplaceId, // pre-connection-lookup placeholder
        "NEXUS_ENABLE_EBAY_PUBLISH=false — set true to enable eBay outbound sync.",
      );
    }

    // 2. Connection lookup (post-gate so a gated attempt is side-effect-free)
    // MAP.3 — DECLARED. 🔴 MAP.6/7: an outbound push SHOULD derive its account
    // from the listing it is pushing; that needs the product→account intent this
    // programme calls labels.
    const connection = await tryResolveConnection(payload?.source === 'FM_CATALOG_CASCADE' && payload.channelConnectionId ? { accountId: payload.channelConnectionId } : { channel: "EBAY", primary: true });
    if (!connection) {
      return fail(
        "failed",
        mode,
        "(no-connection)",
        "No active eBay connection — link an eBay account in Settings first.",
      );
    }

    // 3. Circuit breaker
    const circuit = checkEbayCircuit(connection.id, marketplaceId);
    if (!circuit.ok) {
      return fail(
        "circuit-open",
        mode,
        connection.id,
        circuit.error ?? "Circuit open",
      );
    }

    // 4. Rate limiter
    const t0 = Date.now();
    const acquired = await acquireEbayPublishToken(connection.id, marketplaceId);
    if (!acquired.ok) {
      return fail(
        "rate-limited",
        mode,
        connection.id,
        acquired.error ?? "Rate limited",
        Date.now() - t0,
      );
    }

    // 5. Dry-run short-circuit
    if (mode === "dry-run") {
      console.log(`[EBAY] Dry-run sync for ${sku}:`, { price: payload.price, quantity: payload.quantity });
      recordEbayOutcome(connection.id, marketplaceId, true);
      writeAttemptLog({
        channel: "EBAY",
        marketplace: marketplaceId,
        sellerId: connection.id,
        sku,
        productId: product?.id ?? null,
        mode: "dry-run",
        outcome: "success",
        payloadDigest: digest,
        durationMs: Date.now() - t0,
      });
      return {
        success: true,
        queueId,
        channel: "EBAY",
        status: "SUCCESS",
        message: `Product ${sku} dry-run synced to eBay`,
      };
    }

    // 6. Auth (token fetch has a side effect — lastUsedAt update — so
    // it lives after the dry-run short-circuit)
    let token: string;
    try {
      token = await ebayAuthService.getValidToken(connection.id);
    } catch (err) {
      const message = `Could not obtain eBay token: ${
        err instanceof Error ? err.message : String(err)
      }`;
      recordEbayOutcome(connection.id, marketplaceId, false);
      return fail("failed", mode, connection.id, message, Date.now() - t0);
    }

    // 7. Apply the update. Quantity/content → inventory_item (GET-merge-PUT so
    // the full-replace never wipes existing content); price → the OFFER
    // (different endpoint). Either or both may run depending on the payload.
    const apiBase = getEbayApiBaseForMode(mode);
    const currency = ebayCurrencyForMarket(marketplaceId);
    const headers = ebayInventoryHeaders(token, marketplaceId);

    // Task 3: gate the new per-listing isolation behind an env flag (default ON).
    // Set NEXUS_EBAY_FAILURE_ISOLATION=0 to fall back to pre-Task-3 behavior.
    const failureIsolationEnabled = process.env.NEXUS_EBAY_FAILURE_ISOLATION !== '0';

    const ebayFail = (
      message: string,
      outcome: "failed" | "timeout" = "failed",
      httpStatus?: number | null,
    ): SyncResult => {
      const decision = ebayFailureDecision(httpStatus, failureIsolationEnabled);
      // Only record toward the marketplace circuit breaker when the failure is
      // transient/connection-level (EBAY_TRANSIENT). A per-listing validation
      // error (EBAY_VALIDATION) must NOT trip the whole marketplace circuit.
      if (decision.record) {
        recordEbayOutcome(connection.id, marketplaceId, false);
      }
      writeAttemptLog({
        channel: "EBAY",
        marketplace: marketplaceId,
        sellerId: connection.id,
        sku,
        productId: product?.id ?? null,
        mode,
        outcome,
        payloadDigest: digest,
        errorMessage: message.slice(0, 500),
        durationMs: Date.now() - t0,
      });
      return {
        success: false,
        queueId,
        channel: "EBAY",
        status: "FAILED",
        message: `Failed to sync to eBay`,
        error: message,
        errorCode: decision.code,
        // When isolation is ON, propagate retryable so the worker routes EBAY_VALIDATION
        // to terminal FAILED (retryable:false) instead of re-queuing forever.
        // When isolation is OFF (kill-switch), leave retryable unset to preserve
        // pre-Task-3 byte-compat (worker defaults to retryable=true).
        ...(failureIsolationEnabled ? { retryable: decision.retryable } : {}),
      };
    };

    try {
      // 7a. Quantity (+ any content) → inventory_item.
      const touchesItem =
        payload.quantity !== undefined || !!payload.mappingAspects ||
        !!payload.title ||
        !!payload.description ||
        !!(payload.images && payload.images.length > 0);
      // ── THE IMAGE REVERTER, FOUND 2026-07-26 ─────────────────────────────
      // A QUANTITY-ONLY sync used GET-merge-PUT: it round-tripped the ENTIRE
      // inventory_item through eBay's EVENTUALLY-CONSISTENT read to change one
      // number. When it ran seconds after an image publish (which it always
      // did — the publish itself triggers the stock fan-out), the GET returned
      // the PRE-publish item (old Amazon-CDN images) and the PUT wrote that
      // stale snapshot back, silently reinstating the old images. Every image
      // publish scheduled its own destruction; the operator watched curated
      // photos "revert" within minutes, with zero errors anywhere.
      //
      // Quantity-only updates now use eBay's DEDICATED endpoint,
      // bulk_update_price_quantity: it changes quantity (and the offer floor)
      // WITHOUT replacing the item — no GET, no merge, no stale replay. A
      // quantity sync is now STRUCTURALLY INCAPABLE of touching images. The
      // offer's availableQuantity rides the same call, which retires the 25004
      // parked-offer deadlock for this path too.
      const contentTouched =
        !!payload.mappingAspects || !!payload.title || !!payload.description || !!(payload.images && payload.images.length > 0);
      if (payload.quantity !== undefined && !contentTouched) {
        // Offer id (read of the OFFER, never the item — zero image risk).
        let offerId: string | null = null;
        try {
          const bySku = await fetch(
            `${apiBase}/sell/inventory/v1/offer?sku=${encodeURIComponent(sku)}&marketplace_id=${marketplaceId}`,
            { headers },
          );
          if (bySku.ok) offerId = ((await bySku.json().catch(() => ({}))) as { offers?: Array<{ offerId?: string }> }).offers?.[0]?.offerId ?? null;
        } catch { /* unpublished listing — item-level quantity alone is fine */ }
        const bulkBody = {
          requests: [{
            sku,
            shipToLocationAvailability: { quantity: payload.quantity },
            ...(offerId ? { offers: [{ offerId, availableQuantity: payload.quantity }] } : {}),
          }],
        };
        const bulkRes = await fetch(`${apiBase}/sell/inventory/v1/bulk_update_price_quantity`, {
          method: "POST", headers, body: JSON.stringify(bulkBody),
        });
        const bulkJson = bulkRes.ok
          ? ((await bulkRes.json().catch(() => ({}))) as { responses?: Array<{ statusCode?: number; errors?: Array<{ message?: string }> }> })
          : null;
        const rowStatus = bulkJson?.responses?.[0]?.statusCode ?? (bulkRes.ok ? 200 : bulkRes.status);
        if (!bulkRes.ok || rowStatus >= 300) {
          const detail = bulkJson?.responses?.[0]?.errors?.map((e) => e.message).join(" | ")
            ?? (await bulkRes.text().catch(() => "")).slice(0, 300);
          return ebayFail(`bulk_update_price_quantity ${rowStatus}: ${detail}`, "failed", rowStatus);
        }
        // fall through to 7b (price/offer handling) below — item untouched.
      } else if (touchesItem) {
        const itemUrl = `${apiBase}/sell/inventory/v1/inventory_item/${encodeURIComponent(sku)}`;
        let existing: Record<string, any> = {};
        const getRes = await fetch(itemUrl, { method: "GET", headers });
        if (getRes.ok) existing = (await getRes.json().catch(() => ({}))) as Record<string, any>;
        // WIPE GUARD: createOrReplace REPLACES the whole item. If the GET
        // failed (rate-limit, blip) `existing` is {}, and a content PUT built
        // from it would DELETE the listing's product data (images included).
        // Never write a full replacement assembled from an empty read.
        if (!existing.product && !(payload.title && payload.description)) {
          return ebayFail(
            `inventory_item GET ${getRes.status} — refusing content PUT built from an empty read (would wipe product data)`,
            "failed", getRes.status,
          );
        }
        const itemBodyJson = JSON.stringify(mergeEbayInventoryItem(existing, payload));
        const putRes = await fetch(itemUrl, { method: "PUT", headers, body: itemBodyJson });
        if (!(putRes.ok || putRes.status === 204)) {
          const errBody = (await putRes.text().catch(() => "")).slice(0, 500);
          // RT.4 — 25004 self-heal, ported from the manual flat-file push
          // (ebay-variation-push.service.ts): eBay computes live qty as
          // min(inventory_item.quantity, offer.availableQuantity); a PUBLISHED
          // offer parked at availableQuantity:0 floors that min and rejects our
          // quantity>0 PUT with 25004 — a deadlock, since the offer update
          // that would raise it only runs on price changes. Break it: raise
          // the existing offer to the SAME dispatch quantity (pool-capped
          // upstream — never more than available) and retry the PUT once.
          if (errBody.includes('"errorId":25004') && payload.quantity !== undefined) {
            try {
              const bySku = await fetch(
                `${apiBase}/sell/inventory/v1/offer?sku=${encodeURIComponent(sku)}&marketplace_id=${marketplaceId}`,
                { headers },
              );
              const offerId = bySku.ok
                ? ((await bySku.json().catch(() => ({}))) as { offers?: Array<{ offerId?: string }> }).offers?.[0]?.offerId ?? null
                : null;
              if (offerId) {
                const getFull = await fetch(`${apiBase}/sell/inventory/v1/offer/${offerId}`, { headers });
                if (getFull.ok) {
                  const fullOffer = (await getFull.json().catch(() => ({}))) as Record<string, unknown>;
                  const raised = await fetch(`${apiBase}/sell/inventory/v1/offer/${offerId}`, {
                    method: "PUT",
                    headers,
                    body: JSON.stringify({ ...fullOffer, availableQuantity: payload.quantity }),
                  });
                  if (raised.ok || raised.status === 204) {
                    const retryItem = await fetch(itemUrl, { method: "PUT", headers, body: itemBodyJson });
                    if (retryItem.ok || retryItem.status === 204) {
                      logger.info("syncToEbay: recovered from 25004 — raised parked offer + retried", {
                        sku, offerId, quantity: payload.quantity,
                      });
                    } else {
                      return ebayFail(`inventory_item PUT retry after 25004 heal ${retryItem.status}: ${(await retryItem.text().catch(() => "")).slice(0, 300)}`, "failed", retryItem.status);
                    }
                  } else {
                    return ebayFail(`25004 heal offer PUT ${raised.status}: ${(await raised.text().catch(() => "")).slice(0, 300)}`, "failed", raised.status);
                  }
                } else {
                  return ebayFail(`inventory_item PUT ${putRes.status} (25004; offer GET ${getFull.status} blocked heal): ${errBody.slice(0, 200)}`, "failed", putRes.status);
                }
              } else {
                return ebayFail(`inventory_item PUT ${putRes.status}: ${errBody.slice(0, 300)}`, "failed", putRes.status);
              }
            } catch (healErr) {
              return ebayFail(`inventory_item PUT ${putRes.status} (25004 heal threw: ${healErr instanceof Error ? healErr.message : String(healErr)})`, "failed", putRes.status);
            }
          } else {
            return ebayFail(`inventory_item PUT ${putRes.status}: ${errBody.slice(0, 300)}`, "failed", putRes.status);
          }
        }
      }

      // 7b. Price → offer (resolve the offer by SKU, then PUT its pricingSummary).
      if (payload.price !== undefined) {
        const offersRes = await fetch(
          `${apiBase}/sell/inventory/v1/offer?sku=${encodeURIComponent(sku)}`,
          { method: "GET", headers },
        );
        if (!offersRes.ok) {
          return ebayFail(`get offers ${offersRes.status}: ${(await offersRes.text().catch(() => "")).slice(0, 300)}`, "failed", offersRes.status);
        }
        const offersData = (await offersRes.json().catch(() => ({}))) as {
          offers?: Array<Record<string, any>>;
        };
        const offer = offersData.offers?.[0];
        if (!offer?.offerId) {
          // No offer = the listing was never published; same root cause as a 404.
          // Pass 404 so classifyEbayFailure routes this as EBAY_VALIDATION:
          // non-retryable + does not trip the marketplace circuit.
          return ebayFail(`No eBay offer for SKU "${sku}" — publish the listing before syncing price.`, "failed", 404);
        }
        const offerRes = await fetch(
          `${apiBase}/sell/inventory/v1/offer/${encodeURIComponent(offer.offerId)}`,
          {
            method: "PUT",
            headers,
            body: JSON.stringify(buildEbayOfferUpdate(offer, payload.price, currency)),
          },
        );
        if (!offerRes.ok) {
          return ebayFail(`offer PUT ${offerRes.status}: ${(await offerRes.text().catch(() => "")).slice(0, 300)}`, "failed", offerRes.status);
        }
      }
    } catch (err) {
      return ebayFail(err instanceof Error ? err.message : String(err), "timeout");
    }

    recordEbayOutcome(connection.id, marketplaceId, true);
    writeAttemptLog({
      channel: "EBAY",
      marketplace: marketplaceId,
      sellerId: connection.id,
      sku,
      productId: product?.id ?? null,
      mode,
      outcome: "success",
      payloadDigest: digest,
      durationMs: Date.now() - t0,
    });
    return {
      success: true,
      queueId,
      channel: "EBAY",
      status: "SUCCESS",
      message: `Product ${sku} synced to eBay`,
    };
  }

  /**
   * Phase 3 — shared-SKU quantity fan-out via Trading API ReviseInventoryStatus.
   * These OutboundSyncQueue rows carry payload.pushVia:'TRADING' and have no
   * ChannelListing; the SKU lives in MANY listings (one membership per ItemID),
   * which the multi-variation shared listing model needs (the Inventory API
   * forces unique SKUs and can't address a shared SKU). Reuses the eBay gate +
   * connection + circuit + rate-limit + dry-run scaffolding from syncToEbay.
   */
  private async syncSharedTradingQuantity(queueItem: any): Promise<SyncResult> {
    const { payload, id: queueId } = queueItem;
    const itemId: string = payload?.itemId ?? queueItem.externalListingId ?? "";
    const market: string = payload?.market ?? "IT";
    const marketplaceId: string = payload?.marketplaceId ?? `EBAY_${market}`;

    // RT.2 — batched payloads carry ALL changed SKUs for the item in
    // `updates[]`; legacy rows (pre-deploy PENDING) carry a single
    // sku/quantity pair. Normalize both to one updates list.
    const updates: Array<{ sku: string; quantity: number }> = Array.isArray(payload?.updates)
      ? payload.updates
          .map((u: { sku?: unknown; quantity?: unknown }) => ({
            sku: String(u.sku ?? ""),
            quantity: Math.max(0, Math.trunc(Number(u.quantity ?? 0))),
          }))
          .filter((u: { sku: string }) => u.sku.length > 0)
      : [{
          sku: String(payload?.sku ?? "(unknown sku)"),
          quantity: Math.max(0, Math.trunc(Number(payload?.quantity ?? 0))),
        }];
    const sku: string = updates[0]?.sku ?? "(unknown sku)";
    const digest = digestPayload({ updates });

    const writeMembership = async (data: Record<string, unknown>, skuScope?: string) => {
      try {
        await prisma.sharedListingMembership.updateMany({
          where: skuScope
            ? { marketplace: market, itemId, sku: skuScope }
            : { marketplace: market, itemId, sku: { in: updates.map((u) => u.sku) } },
          data,
        });
      } catch { /* writeback is best-effort */ }
    };

    // RT.4 — re-read the pool at dispatch. The row's quantities were computed
    // at enqueue; the pool may have moved since (order mid-flight, superseded
    // row that outran coalescing). Recompute available−buffer NOW, and drop
    // SKUs already sitting at that value — a fully-no-op row returns success
    // WITHOUT spending a revise against the item's ~250/day budget.
    if (process.env.NEXUS_SYNC_ORDERING_V2 !== "0" && payload?.productId) {
      try {
        const wh = await prisma.stockLevel.findMany({
          where: { productId: payload.productId, location: { type: "WAREHOUSE" } },
          select: { available: true, location: { select: { code: true, syncRoutes: true } } },
        });
        // SC.1 — per-membership derivation at dispatch: routing + followPool
        // + per-membership buffer + channel policy. PAUSED/UNCOUNTED members
        // are dropped here exactly like at enqueue (controls can change
        // between the two — dispatch re-checks, never trusts the row).
        const scLedger = wh.map((s: { available: number; location: { code: string; syncRoutes: string[] } | null }) => ({
          locationCode: s.location?.code ?? '?',
          available: s.available,
          syncRoutes: s.location?.syncRoutes ?? [],
        }));
        const scPolicies = await loadChannelPolicies();
        const mems = await prisma.sharedListingMembership.findMany({
          where: { marketplace: market, itemId, sku: { in: updates.map((u) => u.sku) } },
          select: { sku: true, lastQtyPushed: true, followPool: true, stockBuffer: true },
        });
        const memBySku = new Map(
          mems.map((m: { sku: string; lastQtyPushed: number | null; followPool?: boolean; stockBuffer?: number }) => [m.sku, m]),
        );
        const effective: typeof updates = [];
        for (const u of updates) {
          const m = memBySku.get(u.sku);
          const r = resolveMembershipIntended({
            marketplace: market,
            followPool: m?.followPool ?? true,
            stockBuffer: m?.stockBuffer ?? 0,
            channelPolicy: policyFor(scPolicies, 'EBAY', market),
            ledger: scLedger,
          });
          if (r.kind !== 'FOLLOW') continue; // paused/uncounted member — never push
          u.quantity = r.quantity;
          if (m?.lastQtyPushed !== r.quantity) effective.push(u);
        }
        if (effective.length === 0) {
          return {
            success: true, queueId, channel: "EBAY", status: "SUCCESS",
            message: `Shared ${itemId}: pool unchanged/controlled since last push — no revise spent`,
          };
        }
        updates.length = 0;
        updates.push(...effective);
      } catch (err) {
        // Re-read is an accuracy upgrade, not a gate — fall back to the
        // enqueue-time quantities on any read failure.
        logger.warn("syncSharedTradingQuantity: dispatch re-read failed — using enqueue-time quantities", {
          itemId, error: err instanceof Error ? err.message : String(err),
        });
      }
    }

    // 1. Feature flag
    const mode = getEbayPublishMode();
    if (mode === "gated") {
      return {
        success: false, queueId, channel: "EBAY", status: "FAILED",
        message: "eBay outbound sync gated",
        error: "NEXUS_ENABLE_EBAY_PUBLISH=false — set true to enable eBay outbound sync.",
      };
    }

    // 2. Connection lookup — MAP.3, DECLARED (see the note on the sibling path).
    const connection = await tryResolveConnection({ channel: "EBAY", primary: true });
    if (!connection) {
      return {
        success: false, queueId, channel: "EBAY", status: "FAILED",
        message: "No active eBay connection",
        error: "No active eBay connection — link an eBay account in Settings first.",
      };
    }

    // 3. Circuit breaker
    const circuit = checkEbayCircuit(connection.id, marketplaceId);
    if (!circuit.ok) {
      return {
        success: false, queueId, channel: "EBAY", status: "FAILED",
        message: "Circuit open", error: circuit.error ?? "Circuit open",
        errorCode: "EBAY_CIRCUIT_OPEN",
      };
    }

    // 3b. RT.2 — per-item revise debounce (250/day cap defense). A row that
    // fires within the min interval of the item's last revise re-arms via the
    // deferral disposition (no retry budget consumed); coalescing usually
    // replaces it with a fresher row before it re-fires.
    if (EBAY_REVISE_MIN_INTERVAL_MS > 0) {
      const last = await prisma.sharedListingMembership.aggregate({
        where: { marketplace: market, itemId },
        _max: { lastPushedAt: true },
      });
      const lastAt = last._max.lastPushedAt?.getTime() ?? 0;
      if (lastAt && Date.now() - lastAt < EBAY_REVISE_MIN_INTERVAL_MS) {
        return {
          success: false, queueId, channel: "EBAY", status: "FAILED",
          message: "Revise debounced (item revised moments ago)",
          error: `debounced: last revise ${Math.round((Date.now() - lastAt) / 1000)}s ago (< ${Math.round(EBAY_REVISE_MIN_INTERVAL_MS / 1000)}s min interval)`,
          errorCode: "EBAY_REVISE_DEBOUNCED",
        };
      }
    }

    // 4. Rate limiter
    const t0 = Date.now();
    const acquired = await acquireEbayPublishToken(connection.id, marketplaceId);
    if (!acquired.ok) {
      return {
        success: false, queueId, channel: "EBAY", status: "FAILED",
        message: "Rate limited", error: acquired.error ?? "Rate limited",
        errorCode: "EBAY_RATE_LIMITED",
      };
    }

    // 5. Dry-run short-circuit.
    //    INTENTIONAL divergence from the Inventory-API sibling (syncToEbay):
    //    we treat `sandbox` the same as `dry-run` here because `callTradingApi`
    //    (Phase 1) has its own NEXUS_EBAY_REAL_API / EBAY_SANDBOX gate and would
    //    otherwise return a fake "DRYRUN-" success that we'd mis-mark as a real
    //    push.  Collapsing both modes here avoids that false-green.
    if (mode === "dry-run" || mode === "sandbox") {
      recordEbayOutcome(connection.id, marketplaceId, true);
      writeAttemptLog({
        channel: "EBAY", marketplace: marketplaceId, sellerId: connection.id, sku,
        productId: payload?.productId ?? null, mode, outcome: "success",
        payloadDigest: digest, durationMs: Date.now() - t0,
      });
      return {
        success: true, queueId, channel: "EBAY", status: "SUCCESS",
        message: `Shared ${sku}@${itemId} ${mode} (ReviseInventoryStatus)`, dryRun: true,
      };
    }

    // 6. Auth
    let token: string;
    try {
      token = await ebayAuthService.getValidToken(connection.id);
    } catch (err) {
      const message = `Could not obtain eBay token: ${err instanceof Error ? err.message : String(err)}`;
      recordEbayOutcome(connection.id, marketplaceId, false);
      await writeMembership({ lastError: message });
      return { success: false, queueId, channel: "EBAY", status: "FAILED", message: "eBay auth failed", error: message };
    }

    // 7. Guard: never call ReviseInventoryStatus with an empty ItemID
    if (!itemId) {
      const message = `shared Trading row missing itemId (sku ${sku})`;
      await writeMembership({ lastError: message });
      return { success: false, queueId, channel: "EBAY", status: "FAILED", message, error: message };
    }

    // 8. The Trading-API call — RT.2: ≤4 SKUs per call (each CALL counts once
    //    against the item's ~250/day revise budget), per-chunk membership
    //    writeback so a mid-loop failure only re-pushes unfinished SKUs on
    //    retry (revise is absolute-qty idempotent regardless).
    try {
      for (let i = 0; i < updates.length; i += REVISE_INVENTORY_STATUS_MAX_ENTRIES) {
        const chunk = updates.slice(i, i + REVISE_INVENTORY_STATUS_MAX_ENTRIES);
        await __ebayTrading.reviseInventoryStatusBatch(
          { itemId, entries: chunk },
          { oauthToken: token, market },
        );
        const dayCount = countEbayReviseCall(itemId);
        if (dayCount === EBAY_REVISE_DAILY_WARN) {
          logger.warn("syncSharedTradingQuantity: item nearing eBay's ~250 revises/day cap", {
            itemId, market, revisesToday: dayCount,
          });
        }
        for (const u of chunk) {
          await writeMembership(
            { lastQtyPushed: u.quantity, lastPushedAt: new Date(), lastError: null },
            u.sku,
          );
        }
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);

      // RT.0 auto-heal — the listing no longer exists on eBay (ended/expired).
      // This is a PER-LISTING terminal condition: end every membership riding
      // this ItemID so the fan-out stops producing rows for it, and do NOT
      // record a circuit outcome (a dead listing must never freeze the whole
      // marketplace lane — that was the measured 2026-07-19 incident).
      const endedCode = matchEbayEndedListingCode(message);
      if (endedCode) {
        try {
          const ended = await prisma.sharedListingMembership.updateMany({
            where: { marketplace: market, itemId, status: "ACTIVE" },
            data: {
              status: "ENDED",
              lastError: `auto-ended (eBay code ${endedCode}): ${message.slice(0, 300)}`,
            },
          });
          logger.warn("syncSharedTradingQuantity: listing ended on eBay — memberships auto-ENDED", {
            itemId, market, sku, endedCode, membershipsEnded: ended.count,
          });
        } catch (healErr) {
          logger.error("syncSharedTradingQuantity: membership auto-end failed", {
            itemId, market,
            error: healErr instanceof Error ? healErr.message : String(healErr),
          });
        }
        writeAttemptLog({
          channel: "EBAY", marketplace: marketplaceId, sellerId: connection.id, sku,
          productId: payload?.productId ?? null, mode, outcome: "failed",
          payloadDigest: digest, errorMessage: message.slice(0, 500), durationMs: Date.now() - t0,
        });
        return {
          success: false, queueId, channel: "EBAY", status: "FAILED",
          message: "eBay listing ended — memberships auto-ENDED, push permanently stopped",
          error: message,
          errorCode: "EBAY_LISTING_ENDED",
          retryable: false,
        };
      }

      recordEbayOutcome(connection.id, marketplaceId, false);
      writeAttemptLog({
        channel: "EBAY", marketplace: marketplaceId, sellerId: connection.id, sku,
        productId: payload?.productId ?? null, mode, outcome: "failed",
        payloadDigest: digest, errorMessage: message.slice(0, 500), durationMs: Date.now() - t0,
      });
      await writeMembership({ lastError: message.slice(0, 500) });
      return {
        success: false, queueId, channel: "EBAY", status: "FAILED",
        message: "Failed to sync to eBay (Trading)", error: message,
      };
    }

    // 9. Success — record outcome + log (membership writeback already done
    //    per-chunk inside the loop).
    recordEbayOutcome(connection.id, marketplaceId, true);
    writeAttemptLog({
      channel: "EBAY", marketplace: marketplaceId, sellerId: connection.id, sku,
      productId: payload?.productId ?? null, mode, outcome: "success",
      payloadDigest: digest, durationMs: Date.now() - t0,
    });
    return {
      success: true, queueId, channel: "EBAY", status: "SUCCESS",
      message: `Shared ${updates.length} SKU(s) pushed to ItemID ${itemId} (${market}) in ${Math.ceil(updates.length / REVISE_INVENTORY_STATUS_MAX_ENTRIES)} call(s)`,
    };
  }

  /**
   * Sync product to Shopify via inventory_levels/set.
   *
   * IS.1 — real implementation that updates the Shopify inventory level
   * for the SKU's inventory_item_id at the configured location. Replaces
   * the NOT_IMPLEMENTED gate from C.8.
   */
  private async syncToShopify(queueItem: any): Promise<SyncResult> {
    const { product, payload, channelListing, id: queueId, syncType } = queueItem;
    const sku = product?.sku ?? queueItem.externalListingId ?? "(unknown sku)";

    // PD.4 — Shopify publish-mode gate. Shopify used to write live the instant
    // creds existed (no mode switch — accidental-live risk). Only 'live' writes;
    // anything else is a dry-run no-op (marked SKIPPED, not green SUCCESS).
    const shopifyMode = getShopifyPublishMode();
    if (shopifyMode !== "live") {
      return { success: true, queueId, channel: "SHOPIFY", status: "SKIPPED",
        message: `Shopify ${shopifyMode} — not published (set NEXUS_ENABLE_SHOPIFY_PUBLISH=true + SHOPIFY_PUBLISH_MODE=live)`,
        dryRun: true };
    }

    if ((channelListing?.platformAttributes as Record<string, unknown> | null)?.nexusFamilyId) {
      try {
        const message = await syncNativeShopifyOffer(queueItem);
        return { success: true, queueId, channel: "SHOPIFY", status: "SUCCESS", message };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return { success: false, queueId, channel: "SHOPIFY", status: "FAILED", message, error: message };
      }
    }

    const shopName = process.env.SHOPIFY_SHOP_NAME ?? "";
    const accessToken = process.env.SHOPIFY_ACCESS_TOKEN ?? process.env.SHOPIFY_ADMIN_API_TOKEN ?? "";

    if (!shopName || !accessToken) {
      writeAttemptLog({
        channel: "SHOPIFY", marketplace: "GLOBAL", sellerId: shopName || "(unset)",
        sku, productId: product?.id ?? null, mode: "gated", outcome: "gated",
        payloadDigest: digestPayload(payload),
        errorMessage: "SHOPIFY_SHOP_NAME or SHOPIFY_ACCESS_TOKEN not configured.",
      });
      return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
        message: "Shopify outbound sync not configured",
        error: "SHOPIFY_SHOP_NAME or SHOPIFY_ACCESS_TOKEN env vars missing." };
    }

    // P3.0 — circuit breaker check
    const circuitCheck = checkShopifyCircuit(shopName);
    if (!circuitCheck.ok) {
      return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
        message: "Shopify circuit open", error: circuitCheck.error };
    }

    // P3.0 — rate limiter
    const tokenResult = await acquireShopifyPublishToken(shopName);
    if (!tokenResult.ok) {
      return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
        message: "Shopify rate limited", error: tokenResult.error };
    }

    const apiBase = `https://${shopName}.myshopify.com/admin/api/2024-01`;
    const headers = {
      "X-Shopify-Access-Token": accessToken,
      "Content-Type": "application/json",
      Accept: "application/json",
    };

    // Resolve variant (needed for price + inventory_item_id for qty) and the
    // parent product id (B3 — content lives on the product, not the variant).
    let variantId: string | null =
      (channelListing?.platformAttributes as Record<string, any>)?.variantId ?? null;
    let inventoryItemId: string | null =
      (channelListing?.platformAttributes as Record<string, any>)?.inventoryItemId ?? null;
    let shopifyProductId: string | null =
      (channelListing?.platformAttributes as Record<string, any>)?.shopifyProductId ?? null;

    if (!variantId || !inventoryItemId || !shopifyProductId) {
      const varRes = await fetch(
        `${apiBase}/variants.json?sku=${encodeURIComponent(sku)}&fields=id,inventory_item_id,product_id`,
        { headers },
      ).catch(() => null);
      if (varRes?.ok) {
        const varData = await varRes.json().catch(() => null) as {
          variants?: Array<{ id: string; inventory_item_id: string; product_id: string }>
        } | null;
        const v = varData?.variants?.[0];
        if (v) {
          variantId = String(v.id);
          inventoryItemId = String(v.inventory_item_id);
          shopifyProductId = String(v.product_id);
        }
      }
    }

    // ── B3 — Content update (title/description → Shopify product) ─────────
    // Keyed on syncType so a content sync can NEVER fall through to the
    // quantity path below (which sets inventory to payload.quantity ?? 0 and
    // would zero stock on a content-only change).
    if (syncType === "CONTENT_UPDATE") {
      // B3 content (title/body_html) + C3 GPSR compliance metafields, in ONE
      // product PUT. Compliance rides the content sync (a dedicated compliance-
      // only trigger is a follow-up). Both best-effort.
      const update = buildShopifyProductUpdate(shopifyProductId, payload);
      let metafields: Array<{ namespace: string; key: string; type: string; value: string }> = [];
      if (product?.id) {
        const cp = await resolveComplianceById(product.id).catch(() => null);
        if (cp) metafields = buildShopifyComplianceMetafields(cp);
      }

      if (!shopifyProductId) {
        // Hard error only when there's actually something to push.
        if (update || metafields.length > 0) {
          return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
            message: `No Shopify product for SKU ${sku} — publish the listing first`,
            error: "shopify product_id not resolved." };
        }
        return { success: true, queueId, channel: "SHOPIFY", status: "SUCCESS",
          message: `Shopify content: nothing to push for ${sku} (skipped)` };
      }
      // Nothing pushable (no content field, no compliance metafield) → skip.
      if (!update && metafields.length === 0) {
        return { success: true, queueId, channel: "SHOPIFY", status: "SUCCESS",
          message: `Shopify content: no pushable field for ${sku} (skipped)` };
      }

      const productBody: Record<string, any> = update?.product ?? { id: parseInt(shopifyProductId, 10) };
      if (metafields.length > 0) productBody.metafields = metafields;

      const t0 = Date.now();
      const contentRes = await fetch(`${apiBase}/products/${shopifyProductId}.json`, {
        method: "PUT",
        headers,
        body: JSON.stringify({ product: productBody }),
      }).catch((err: Error) => ({ ok: false, status: 0, text: async () => err.message } as any));

      const succeeded = contentRes.ok;
      const errBody = succeeded ? null : await contentRes.text().catch(() => "");
      writeAttemptLog({
        channel: "SHOPIFY", marketplace: "GLOBAL", sellerId: shopName,
        sku, productId: product?.id ?? null, mode: "live",
        outcome: succeeded ? "success" : "failed",
        payloadDigest: digestPayload(payload),
        errorMessage: succeeded ? null : `products PUT ${contentRes.status}: ${(errBody ?? "").slice(0, 300)}`,
        durationMs: Date.now() - t0,
      });
      recordShopifyOutcome(shopName, succeeded, succeeded ? undefined : `products PUT ${contentRes.status}`);

      if (!succeeded) {
        return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
          message: "Failed to update Shopify product content",
          error: `products PUT ${contentRes.status}: ${(errBody ?? "").slice(0, 300)}` };
      }
      const metaNote = metafields.length > 0 ? ` + ${metafields.length} compliance metafield(s)` : "";
      return { success: true, queueId, channel: "SHOPIFY", status: "SUCCESS",
        message: `Shopify content updated: ${sku}${metaNote}` };
    }

    // ── P3.0 — Price update ──────────────────────────────────────────────
    if (syncType === "PRICE_UPDATE" || payload?.price != null) {
      const newPrice: number | null = payload?.price ?? null;
      if (newPrice == null || !variantId) {
        return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
          message: `Cannot update Shopify price for SKU ${sku}: missing price or variantId`,
          error: "price or variantId not resolved." };
      }

      const t0 = Date.now();
      const priceStr = Number(newPrice).toFixed(2);
      const priceRes = await fetch(`${apiBase}/variants/${variantId}.json`, {
        method: "PUT",
        headers,
        body: JSON.stringify({ variant: { id: parseInt(variantId, 10), price: priceStr } }),
      }).catch((err: Error) => ({ ok: false, text: async () => err.message } as any));

      const succeeded = priceRes.ok;
      const errBody = succeeded ? null : await priceRes.text().catch(() => "");

      writeAttemptLog({
        channel: "SHOPIFY", marketplace: "GLOBAL", sellerId: shopName,
        sku, productId: product?.id ?? null, mode: "live",
        outcome: succeeded ? "success" : "failed",
        payloadDigest: digestPayload(payload),
        errorMessage: succeeded ? null : `variants PUT ${priceRes.status}: ${(errBody ?? "").slice(0, 300)}`,
        durationMs: Date.now() - t0,
      });

      recordShopifyOutcome(shopName, succeeded, succeeded ? undefined : `variants PUT ${priceRes.status}`);

      if (!succeeded) {
        return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
          message: "Failed to update Shopify variant price",
          error: `variants PUT ${priceRes.status}: ${(errBody ?? "").slice(0, 300)}` };
      }

      return { success: true, queueId, channel: "SHOPIFY", status: "SUCCESS",
        message: `Shopify price updated: ${sku} → €${priceStr}` };
    }

    // ── Quantity update (existing path) ─────────────────────────────────
    // RT.4 — parity with Amazon/eBay: re-read the live committed quantity at
    // dispatch (a stale payload from a superseded-but-undelivered row must
    // not overwrite a fresher value) and clamp to the warehouse pool so
    // Shopify can never advertise units the pool doesn't have.
    let newQty: number = payload?.quantity ?? 0;
    if (process.env.NEXUS_SYNC_ORDERING_V2 !== "0") {
      const cl = channelListing?.id
        ? await prisma.channelListing.findUnique({
            where: { id: channelListing.id },
            select: { quantity: true, stockBuffer: true, fulfillmentMethod: true },
          })
        : null;
      const resolved = resolveDispatchQuantity(cl?.quantity, payload?.quantity);
      if (resolved !== undefined) newQty = resolved;
      if (
        process.env.NEXUS_OVERSELL_CLAMP !== "0" &&
        product?.id &&
        cl?.fulfillmentMethod !== "FBA"
      ) {
        const wh = await prisma.stockLevel.findMany({
          where: { productId: product.id, location: { type: "WAREHOUSE" } },
          select: { available: true },
        });
        const available = computeAvailableToPublish({
          fulfillmentMethod: "FBM",
          warehouseAvailable: wh.reduce((a, s) => a + s.available, 0),
          fbaSellable: 0,
          stockBuffer: cl?.stockBuffer ?? 0,
        }).available;
        const clamp = applyOversellClamp(newQty, available);
        if (clamp.clamped) {
          try {
            publishOrderEvent({
              type: "sync.oversell.clamped",
              sku,
              channel: "SHOPIFY",
              marketplace: "GLOBAL",
              requested: newQty,
              clampedTo: clamp.quantity,
              available,
              ts: Date.now(),
            } as never);
          } catch { /* observability must never break the sync */ }
          newQty = clamp.quantity;
        }
      }
    }

    if (!inventoryItemId) {
      return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
        message: `No Shopify inventory_item_id found for SKU ${sku}`,
        error: "inventory_item_id not in ChannelListing and SKU lookup returned nothing." };
    }

    let locationId: string | null = process.env.SHOPIFY_LOCATION_ID ?? null;
    if (!locationId) {
      const locRes = await fetch(`${apiBase}/locations.json?limit=1&fields=id`, { headers }).catch(() => null);
      if (locRes?.ok) {
        const locData = await locRes.json().catch(() => null) as { locations?: Array<{ id: string }> } | null;
        locationId = String(locData?.locations?.[0]?.id ?? "");
      }
    }

    if (!locationId) {
      return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
        message: "Could not resolve Shopify location ID",
        error: "Set SHOPIFY_LOCATION_ID env var or connect a Shopify location." };
    }

    const t0 = Date.now();
    const setRes = await fetch(`${apiBase}/inventory_levels/set.json`, {
      method: "POST", headers,
      body: JSON.stringify({
        location_id: parseInt(locationId, 10),
        inventory_item_id: parseInt(inventoryItemId, 10),
        available: newQty,
      }),
    }).catch((err: Error) => ({ ok: false, text: async () => err.message } as any));

    const succeeded = setRes.ok;
    const errorBody = succeeded ? null : await setRes.text().catch(() => "");

    writeAttemptLog({
      channel: "SHOPIFY", marketplace: "GLOBAL", sellerId: shopName,
      sku, productId: product?.id ?? null, mode: "live",
      outcome: succeeded ? "success" : "failed",
      payloadDigest: digestPayload(payload),
      errorMessage: succeeded ? null : `inventory_levels/set ${setRes.status}: ${(errorBody ?? "").slice(0, 300)}`,
      durationMs: Date.now() - t0,
    });

    recordShopifyOutcome(shopName, succeeded, succeeded ? undefined : `inventory_levels/set ${setRes.status}`);

    if (!succeeded) {
      return { success: false, queueId, channel: "SHOPIFY", status: "FAILED",
        message: "Failed to update Shopify inventory",
        error: `inventory_levels/set ${setRes.status}: ${(errorBody ?? "").slice(0, 300)}` };
    }

    return { success: true, queueId, channel: "SHOPIFY", status: "SUCCESS",
      message: `Shopify inventory updated: ${sku} → ${newQty} at location ${locationId}` };
  }

  /**
   * Sync product to WooCommerce.
   *
   * C.8 — same shape as syncToShopify: honest NOT_IMPLEMENTED gate
   * until Wave 6 / C.19 wires the real REST adapter.
   */
  private async syncToWoocommerce(queueItem: any): Promise<SyncResult> {
    const { product, payload, id: queueId } = queueItem;
    const sku = product?.sku ?? queueItem.externalListingId ?? "(unknown sku)";
    const wooPayload = this.constructWoocommercePayload(payload);
    writeAttemptLog({
      channel: "WOOCOMMERCE",
      marketplace: "GLOBAL",
      sellerId: process.env.WOOCOMMERCE_STORE_URL ?? "(unset)",
      sku,
      productId: product?.id ?? null,
      mode: "gated",
      outcome: "gated",
      payload: wooPayload,
      errorMessage:
        "WooCommerce outbound sync not yet wired — see roadmap C.19 (Wave 6 Path A).",
    });
    return {
      success: false,
      queueId,
      channel: "WOOCOMMERCE",
      status: "FAILED",
      message: `Failed to sync to WooCommerce`,
      error:
        "WooCommerce outbound sync not yet wired — see roadmap C.19 (Wave 6 Path A).",
    };
  }

  /**
   * Handle sync failure with retry logic (RT.0 semantics — see
   * computeFailureDisposition). Circuit-open/rate-limit episodes defer without
   * consuming retry budget; terminal rows are dead-lettered + emit SYNC_DEAD.
   */
  private async handleSyncFailure(
    queueItem: any,
    errorMessage: string,
    opts?: { errorCode?: string; retryable?: boolean },
  ): Promise<void> {
    const disposition = computeFailureDisposition(queueItem, errorMessage, opts);

    if (disposition.kind === "deferral") {
      await prisma.outboundSyncQueue.update({
        where: { id: queueItem.id },
        data: {
          syncStatus: "FAILED",
          errorMessage,
          errorCode: disposition.errorCode,
          // retryCount deliberately NOT incremented — the failure belongs to
          // the circuit/rate-limit episode, not to this row.
          nextRetryAt: disposition.nextRetryAt,
        },
      });
      return;
    }

    if (disposition.kind === "terminal") {
      await prisma.outboundSyncQueue.update({
        where: { id: queueItem.id },
        data: {
          syncStatus: "FAILED",
          errorMessage,
          errorCode: disposition.errorCode,
          retryCount: queueItem.retryCount + 1,
          isDead: true,
          diedAt: new Date(),
        },
      });
      productEventService
        .emit({
          aggregateId: queueItem.productId ?? queueItem.id,
          aggregateType: "ChannelListing",
          eventType: "SYNC_DEAD",
          data: {
            queueId: queueItem.id,
            channel: queueItem.targetChannel,
            syncType: queueItem.syncType,
            error: errorMessage,
            retryCount: queueItem.retryCount + 1,
          },
          metadata: { source: "SYSTEM" },
        })
        .catch(() => {});
      return;
    }

    await prisma.outboundSyncQueue.update({
      where: { id: queueItem.id },
      data: {
        syncStatus: "FAILED",
        errorMessage,
        errorCode: disposition.errorCode,
        retryCount: queueItem.retryCount + 1,
        nextRetryAt: disposition.nextRetryAt,
      },
    });
  }

  /* A4.0 — constructAmazonPayload removed; replaced by the module-level
   * buildAmazonListingPatch (correct schema names + Listings PATCH shape). */

  /**
   * Construct WooCommerce payload
   */
  private constructWoocommercePayload(payload: SyncPayload): Record<string, any> {
    const wooPayload: Record<string, any> = {};

    if (payload.title) {
      wooPayload.name = payload.title;
    }

    if (payload.description) {
      wooPayload.description = payload.description;
    }

    if (payload.price !== undefined) {
      wooPayload.regular_price = payload.price.toString();
    }

    if (payload.quantity !== undefined) {
      wooPayload.stock_quantity = payload.quantity;
    }

    if (payload.images && payload.images.length > 0) {
      wooPayload.images = payload.images.map((url) => ({
        src: url,
      }));
    }

    return wooPayload;
  }

  /**
   * Get external listing ID from product based on channel
   */
  private getExternalListingId(
    product: any,
    channel: "AMAZON" | "EBAY" | "SHOPIFY" | "WOOCOMMERCE"
  ): string | null {
    switch (channel) {
      case "AMAZON":
        return product.amazonAsin || null;
      case "EBAY":
        return product.ebayItemId || null;
      case "SHOPIFY":
        return product.shopifyProductId || null;
      case "WOOCOMMERCE":
        return product.woocommerceProductId || null;
      default:
        return null;
    }
  }

  /**
   * Get queue status
   */
  async getQueueStatus(
    filters?: {
      status?: string;
      channel?: string;
      productId?: string;
    }
  ): Promise<any[]> {
    const where: any = {};

    if (filters?.status) {
      where.syncStatus = filters.status;
    }

    if (filters?.channel) {
      where.targetChannel = filters.channel;
    }

    if (filters?.productId) {
      where.productId = filters.productId;
    }

    return prisma.outboundSyncQueue.findMany({
      where,
      include: {
        product: {
          select: {
            id: true,
            sku: true,
            name: true,
            basePrice: true,
            totalStock: true,
          },
        },
      },
      orderBy: {
        createdAt: "desc",
      },
    });
  }

  /**
   * Retry a specific queue item
   */
  async retryQueueItem(queueId: string): Promise<QueueResult> {
    try {
      const queueItem = await prisma.outboundSyncQueue.findUnique({
        where: { id: queueId },
      });

      if (!queueItem) {
        return {
          success: false,
          message: `Queue item ${queueId} not found`,
        };
      }

      // Reset for retry
      await prisma.outboundSyncQueue.update({
        where: { id: queueId },
        data: {
          syncStatus: "PENDING",
          retryCount: 0,
          errorMessage: null,
          errorCode: null,
          nextRetryAt: null,
        },
      });

      return {
        success: true,
        queueId,
        message: `Queue item reset for retry`,
      };
    } catch (error) {
      return {
        success: false,
        message: `Failed to retry queue item: ${error instanceof Error ? error.message : "Unknown error"}`,
      };
    }
  }

  /**
   * Get sync statistics
   */
  getStats() {
    return this.stats;
  }

  /**
   * Reset statistics
   */
  resetStats() {
    this.stats = {
      queued: 0,
      processed: 0,
      succeeded: 0,
      failed: 0,
    };
  }
}

export default new OutboundSyncService();

import JSZip from 'jszip'
import { transferTargetKey, type TransferRow } from '@nexus/shared/catalog-transfer'
import { TRANSFER_MAX_ROWS, TransferWorkbookLimitError, writeTransferWorkbook } from './catalog-transfer-file.js'
import { checkWorkbookSize } from './catalog-source-file.js'

const XLSX = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
const MAX_PRODUCTS_PER_WORKBOOK = 500

/** Prefer whole products. Only an oversized product is split at its independent listing targets. */
function targetGroups(rows: TransferRow[]) {
  const groups = new Map<string, TransferRow[]>()
  for (const row of rows) {
    const key = transferTargetKey(row)
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key)!.push(row)
  }
  return [...groups.values()]
}

/** Consume bounded product batches and return one workbook, or numbered importable workbooks. */
export async function writeTransferDownload(products: AsyncIterable<TransferRow[]>, effective = false, writer?: (rows: TransferRow[]) => Promise<Buffer>, productEditor = false) {
  const base = `nexus-catalog-${effective ? 'effective' : 'editing'}`
  const parts: { data: Buffer; rows: number; skus: string[] }[] = []
  const allSkus = new Set<string>()
  let pending: TransferRow[][] = [], count = 0
  let totalRows = 0, totalBytes = 0, expandedBytes = 0

  const append = async (groups: TransferRow[][]): Promise<void> => {
    const rows = groups.flat()
    try {
      const data = await (writer ? writer(rows) : writeTransferWorkbook(rows, [], effective))
      let expanded = 0
      if (productEditor) {
        try { expanded = await checkWorkbookSize(data) } catch (e) {
          if (e instanceof Error && e.message.startsWith('Expanded workbook')) throw new TransferWorkbookLimitError('rows')
          throw e
        }
      }
      expandedBytes += expanded
      if (productEditor && expandedBytes > 128 * 1024 * 1024) throw new Error('This workbook batch expands beyond the import limit. Choose fewer products, destinations or attributes.')
      totalBytes += data.length
      if (productEditor && (totalBytes > 49 * 1024 * 1024 || parts.length >= 50)) throw new Error('This editing export exceeds the complete ZIP import limit. Choose fewer products, destinations or attributes.')
      const skus = [...new Set(rows.map(row => row.sku))]
      skus.forEach(sku => allSkus.add(sku))
      parts.push({ data, rows: rows.length, skus })
    } catch (error) {
      if (!(error instanceof TransferWorkbookLimitError)) throw error
      const smaller = groups.length > 1 ? groups : targetGroups(groups[0])
      if (smaller.length < 2) throw new Error(`${rows[0]?.sku ?? 'This product'}: one product or listing record exceeds the ${error.limit === 'rows' ? '50,000 attribute row' : '10 MB'} workbook limit. Its fields cannot be split safely across imports.`)
      const middle = Math.ceil(smaller.length / 2)
      await append(smaller.slice(0, middle))
      await append(smaller.slice(middle))
    }
  }

  for await (const rows of products) {
    if (!rows.length) continue
    totalRows += rows.length
    if (productEditor && totalRows > 250_000) throw new Error('Export at most 250,000 attribute values for one product import. Choose fewer products, destinations or attributes.')
    if (pending.length && (count + rows.length > TRANSFER_MAX_ROWS || pending.length >= MAX_PRODUCTS_PER_WORKBOOK)) {
      await append(pending)
      pending = []; count = 0
    }
    pending.push(rows); count += rows.length
  }
  if (pending.length) await append(pending)
  if (!parts.length) await append([])
  if (parts.length === 1) return { data: parts[0].data, filename: `${base}.xlsx`, contentType: XLSX }

  const zip = new JSZip()
  const manifest = parts.map((part, index) => {
    const filename = `${base}-${String(index + 1).padStart(3, '0')}.xlsx`
    zip.file(filename, part.data)
    return { filename, attributeRows: part.rows, productCount: part.skus.length, skus: part.skus }
  })
  zip.file('manifest.json', JSON.stringify({ formatVersion: 1, purpose: effective ? 'effective' : 'editing', productCount: allSkus.size, attributeRows: parts.reduce((total, part) => total + part.rows, 0), files: manifest }, null, 2))
  zip.file('README.txt', [
    `Nexus catalog ${effective ? 'review' : 'editing'} export — ${parts.length} workbooks.`,
    'Your complete selection is included. Each workbook contains at most 50,000 attribute rows and is at most 10 MB.',
    effective ? 'Effective values are for review only. They cannot be imported.' : productEditor ? 'Edit the XLSX parts, keep every part and manifest.json in this ZIP, then upload the complete ZIP to this product editor. All parts are reviewed together.' : 'Extract this ZIP, edit the workbooks, then preview and apply each XLSX separately in Catalog import & export.',
    effective ? '' : 'For an existing catalog, choose Update. Keep SKU, account, marketplace, alias and version cells intact.',
    effective ? '' : productEditor ? 'Edit value cells directly. Blank or unchanged cells preserve data. Unhide action columns for explicit SET, CLEAR or INHERIT. Return this export within 30 days.' : 'Keep SET, CLEAR and INHERIT actions unchanged unless you intend to change that value or its inheritance.',
    'Products are kept together wherever possible. An oversized product can occupy multiple files; a single product or listing record is never split.',
    'manifest.json lists the workbooks, SKUs and row counts. No rows are truncated.',
  ].filter(Boolean).join('\r\n'))
  // XLSX is already compressed. Stream the outer ZIP without a second full archive buffer.
  return { data: zip.generateNodeStream({ streamFiles: true, compression: 'STORE' }), filename: `${base}.zip`, contentType: 'application/zip' }
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import JSZip from 'jszip'
import type { TransferRow } from '@nexus/shared/catalog-transfer'
import * as workbook from './catalog-transfer-file.js'
import { writeTransferDownload } from './catalog-transfer-download.js'

const row = (sku: string, field: string, extra: Partial<TransferRow> = {}): TransferRow => ({ row: 0, entity: 'Products', sku, channel: '', accountId: '', marketplace: '', aliasKey: '', locale: '', field, action: 'SET', value: '00123', ...extra })
async function* products(groups: TransferRow[][]) { yield* groups }
async function bytes(data: Buffer | NodeJS.ReadableStream) {
  if (Buffer.isBuffer(data)) return data
  return new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = []
    data.on('data', chunk => chunks.push(Buffer.from(chunk)))
    data.once('error', reject)
    data.once('end', () => resolve(Buffer.concat(chunks)))
  })
}
afterEach(() => vi.restoreAllMocks())

describe('catalog download batching', () => {
  it('keeps a small export as an ordinary importable workbook', async () => {
    const rows = [row('SKU', 'name'), row('SKU', 'material', { value: ['Cotton', 'Linen'] }), row('SKU', 'flag', { value: false })]
    const result = await writeTransferDownload(products([rows]))
    expect(result.filename).toBe('nexus-catalog-editing.xlsx')
    const parsed = await workbook.readTransferFile(await bytes(result.data), result.filename)
    expect(parsed.issues).toEqual([])
    expect(parsed.rows.map(r => r.value)).toEqual(rows.map(r => r.value))
  })

  it('exports more than 50,000 attribute rows without dropping or splitting a product', async () => {
    const groups = ['A', 'B'].map((sku, i) => Array.from({ length: 25_000 + i }, (_, field) => row(sku, `attribute_${field}`)))
    const result = await writeTransferDownload(products(groups))
    expect(result.filename).toBe('nexus-catalog-editing.zip')
    expect(result.contentType).toBe('application/zip')
    const zip = await JSZip.loadAsync(await bytes(result.data))
    const manifest = JSON.parse(await zip.file('manifest.json')!.async('string'))
    expect(manifest).toMatchObject({ productCount: 2, attributeRows: 50_001 })
    expect(manifest.files).toHaveLength(2)
    let count = 0
    for (const [index, file] of manifest.files.entries()) {
      const data = await zip.file(file.filename)!.async('nodebuffer')
      expect(data.length).toBeLessThanOrEqual(workbook.TRANSFER_MAX_FILE_BYTES)
      const parsed = await workbook.readTransferFile(data, file.filename)
      expect(parsed.issues).toEqual([])
      expect(parsed.rows.length).toBeLessThanOrEqual(workbook.TRANSFER_MAX_ROWS)
      expect(parsed.rows.map(r => [r.sku, r.field, r.value])).toEqual(groups[index].map(r => [r.sku, r.field, r.value]))
      count += parsed.rows.length
    }
    expect(count).toBe(50_001)
    expect(await zip.file('README.txt')!.async('string')).toContain('each XLSX separately')
  }, 60_000)

  it('automatically creates another workbook after 500 products instead of refusing the selection', async () => {
    const result = await writeTransferDownload(products(Array.from({ length: 501 }, (_, i) => [row(`SKU-${i}`, 'name')])))
    const zip = await JSZip.loadAsync(await bytes(result.data))
    const manifest = JSON.parse(await zip.file('manifest.json')!.async('string'))
    expect(manifest.productCount).toBe(501)
    expect(manifest.files.map((file: { productCount: number }) => file.productCount)).toEqual([500, 1])
  })

  it('splits a workbook by product when encoded file size exceeds the import limit', async () => {
    const original = workbook.writeTransferWorkbook
    vi.spyOn(workbook, 'writeTransferWorkbook').mockImplementation(async (rows, dictionary, effective) => {
      if (new Set(rows.map(r => r.sku)).size > 1) throw new workbook.TransferWorkbookLimitError('bytes')
      return original(rows, dictionary, effective)
    })
    const result = await writeTransferDownload(products([[row('A', 'name')], [row('B', 'name')]]))
    const zip = await JSZip.loadAsync(await bytes(result.data))
    const manifest = JSON.parse(await zip.file('manifest.json')!.async('string'))
    expect(manifest.files.map((file: { skus: string[] }) => file.skus)).toEqual([['A'], ['B']])
  })

  it('keeps a listing category and its override in the same file when an oversized product must split', async () => {
    const original = workbook.writeTransferWorkbook
    vi.spyOn(workbook, 'writeTransferWorkbook').mockImplementation(async (rows, dictionary, effective) => {
      if (rows.length > 2) throw new workbook.TransferWorkbookLimitError('bytes')
      return original(rows, dictionary, effective)
    })
    const channel = { channel: 'AMAZON', accountId: 'account-a', marketplace: 'IT', aliasKey: 'alias-a', version: 7 }
    const result = await writeTransferDownload(products([[
      row('A', 'name'),
      row('A', 'productType', { ...channel, entity: 'Listings', value: 'OUTERWEAR' }),
      row('A', 'item_name', { ...channel, entity: 'Overrides', action: 'INHERIT', value: undefined }),
    ]]))
    const zip = await JSZip.loadAsync(await bytes(result.data))
    const manifest = JSON.parse(await zip.file('manifest.json')!.async('string'))
    const listingFile = manifest.files[1].filename
    const parsed = await workbook.readTransferFile(await zip.file(listingFile)!.async('nodebuffer'), listingFile)
    expect(parsed.rows.map(r => r.entity)).toEqual(['Listings', 'Overrides'])
    expect(parsed.rows.every(r => r.accountId === 'account-a' && r.aliasKey === 'alias-a' && r.version === 7)).toBe(true)
    expect(parsed.rows[1].action).toBe('INHERIT')
  })

  it('refuses a single oversized record instead of generating imports that invalidate one another', async () => {
    vi.spyOn(workbook, 'writeTransferWorkbook').mockRejectedValue(new workbook.TransferWorkbookLimitError('bytes'))
    await expect(writeTransferDownload(products([[row('A', 'name'), row('A', 'description')]]))).rejects.toThrow('cannot be split safely')
  })

  it('does not disguise unrelated workbook errors as a batch limit', async () => {
    vi.spyOn(workbook, 'writeTransferWorkbook').mockRejectedValue(new Error('serialization failure'))
    await expect(writeTransferDownload(products([[row('A', 'name')], [row('B', 'name')]]))).rejects.toThrow('serialization failure')
  })

  it('marks effective exports as review-only in every batch', async () => {
    const result = await writeTransferDownload(products(Array.from({ length: 501 }, (_, i) => [row(`SKU-${i}`, 'name')])), true)
    expect(result.filename).toBe('nexus-catalog-effective.zip')
    const zip = await JSZip.loadAsync(await bytes(result.data))
    expect(await zip.file('README.txt')!.async('string')).toContain('cannot be imported')
    const manifest = JSON.parse(await zip.file('manifest.json')!.async('string'))
    const file = manifest.files[0].filename
    const parsed = await workbook.readTransferFile(await zip.file(file)!.async('nodebuffer'), file)
    expect(parsed.rows).toEqual([])
  })
})

import { normalizeLanguage } from './content-language.js'
import { translationMissing } from './content-resolver.js'
import { contentWireValue } from './content-read.js'
import prisma from '../../db.js'
import { resolveAttributes, type ProductLike } from './attribute-resolver.js'
import { resolveBatch } from './mapping/resolve-batch.service.js'
import { projectCellValue } from './sheet-values.js'
import { languageForMarketplace } from '../products/translation-resolver.service.js'
import type { TransferContext, TransferContracts, TransferPlan, TransferTarget } from './catalog-transfer-plan.js'

/** Resolve the planner's in-memory patches through the same read rules used by the sheets. */
export async function enrichTransferEffects(jobId: string, plan: TransferPlan, context: TransferContext, contracts: TransferContracts, market: string) {
  const changed = plan.targets.filter(t => t.cells.some(c => c.verdict === 'changed'))
  if (!changed.length) return
  const products = [...context.products.values()]
  const earlier = await prisma.importJobRow.findMany({ where: { jobId, targetId: { in: products.map(p => JSON.stringify(['Products', p.sku])) }, status: 'REVIEWED' }, select: { parsedValues: true } })
  const sharedTargets = [...earlier.flatMap(r => {
    const target = (r.parsedValues as unknown as { target?: TransferTarget }).target
    return target ? [target] : []
  }), ...plan.targets.filter(t => t.identity.entity === 'Products')]
  const patches = Object.fromEntries(sharedTargets.flatMap(t => t.before ? [[String(t.before.id), t.patch]] : []))
  const beforeById = new Map(products.map(p => [p.id, p]))
  const afterById = new Map(products.map(p => [p.id, { ...p, ...patches[p.id] }]))
  const groups = new Map<string, TransferTarget[]>()
  for (const target of changed) {
    const id = target.identity, product = context.products.get(id.sku)
    if (!product) continue
    if (id.entity !== 'Products') {
      const key = JSON.stringify([id.channel, id.accountId, id.marketplace, id.aliasKey])
      if (!groups.has(key)) groups.set(key, [])
      groups.get(key)!.push(target)
      continue
    }
    const columns = await contracts.master(product.familyId, product)
    const cache = new Map<string, ReturnType<typeof resolveAttributes>>()
    for (const cell of target.cells.filter(c => c.verdict === 'changed')) {
      const column = columns.find(c => c.key === cell.field || c.key === 'name' && cell.field === 'title')
      if (!column) continue
      cell.label = column.label
      for (const side of ['Before', 'After'] as const) {
        const state = side === 'Before' ? cell.beforeState : cell.afterState
        const stored = side === 'Before' ? cell.before : cell.after
        const graph = side === 'Before' ? beforeById : afterById
        const current = graph.get(product.id)!, parent = current.parentId ? graph.get(current.parentId) ?? null : null
        const locale = normalizeLanguage(cell.locale || await languageForMarketplace(market, 'AMAZON'))
        const key = JSON.stringify([side, locale])
        if (!cache.has(key)) cache.set(key, resolveAttributes({ product: current as unknown as ProductLike, parent: parent as unknown as ProductLike | null, locale, localizableKeys: columns.filter(c => c.storage === 'localizedContent').map(c => c.key) }))
        const hit = cache.get(key)![cell.field === 'name' ? 'title' : cell.field]
        const value = state === 'stored' ? stored : hit?.value ?? null
        cell[`effective${side}`] = { value: contentWireValue(projectCellValue(column, value), column.slot ? undefined : column.shape), source: cell.locale && state !== 'stored' && hit?.language && translationMissing(hit, locale) ? `${locale} translation missing; showing ${hit.language} source` : state === 'stored' ? cell.locale ? `Stored ${cell.locale} content` : 'Shared product value'
          : hit?.inheritedFrom && parent && hit.inheritedFrom.startsWith(parent.id) ? `Inherited from ${parent.sku}` : hit ? `Inherited · ${hit.source}` : 'No inherited value' }
      }
    }
  }
  for (const targets of groups.values()) {
    const id = targets[0].identity
    const productIds = targets.map(t => context.products.get(t.identity.sku)!.id)
    const fieldKeys = [...new Set(targets.flatMap(t => t.cells.filter(c => c.verdict === 'changed' && !['productType', 'categoryId'].includes(c.field)).map(c => c.field)))]
    if (!fieldKeys.length) continue
    const input = { channel: id.channel, channelConnectionId: id.accountId, marketplace: id.marketplace, aliasKey: id.aliasKey, productIds, fieldKeys, includeCatalogue: false }
    try {
      const before = await resolveBatch(input)
      const after = await resolveBatch({ ...input, productChangesByProduct: patches, listingChangesByProduct: Object.fromEntries(targets.map(t => [context.products.get(t.identity.sku)!.id, t.patch])) })
      const beforeByProduct = new Map(before.products.map(p => [p.productId, p])), afterByProduct = new Map(after.products.map(p => [p.productId, p]))
      for (const target of targets) for (const cell of target.cells.filter(c => c.verdict === 'changed')) {
        const productId = context.products.get(target.identity.sku)!.id
        for (const [side, result] of [['Before', beforeByProduct.get(productId)], ['After', afterByProduct.get(productId)]] as const) {
          const hit = result?.cells[cell.field] ?? Object.values(result?.cells ?? {}).find(c => c.fieldKey === cell.field)
          if (!hit) continue
          cell.label = hit.label ?? cell.label
          const sources: Record<string, string> = { override: 'Listing override', missing: 'No resolved value', fallback: 'Inherited product value', catalogRule: 'Channel mapping rule', linked: 'Linked product value', default: 'Configured default', locked: 'Locked listing value' }
          cell[`effective${side}` as 'effectiveBefore' | 'effectiveAfter'] = { value: hit.value ?? null, source: sources[hit.provenance ?? ''] ?? 'Resolved product value' }
        }
      }
    } catch {
      plan.warnings.push(`${id.channel} ${id.marketplace}: effective values could not be resolved for this review. Stored changes remain visible; check the updated grid before publishing.`)
    }
  }
}

import { PRIMARY_CONTENT_LOCALE } from './content-locale.js'
import { contentLanguages } from './content-read.js'
import { normalizeLanguage } from './content-language.js'
import { listActiveConnections } from '../connection-resolver.service.js'
import type { Prisma } from '@prisma/client'
import prisma from '../../db.js'
import { TRANSFER_CHANNELS, transferCategoryField, transferIsStore, type TransferRow, type ProductTransferBoundary } from '@nexus/shared/catalog-transfer'
import { MANAGED_FIELDS, managedChannelField, masterTransferState, transferContracts, type TransferProduct } from './catalog-transfer-plan.js'
import { jsonRecord, storedChannelState } from './channel-value-mutation.js'
import { writeTransferWorkbook } from './catalog-transfer-file.js'
import { writeTransferDownload } from './catalog-transfer-download.js'
import { masterWorkbookField, channelWorkbookField, relationshipFields, workbookScopesForRows } from './catalog-workbook-scopes.js'
import { writeCatalogWorkbook, type WorkbookField } from './catalog-workbook.js'
import { marketLanguages } from './market-languages.js'

const empty = { row: 0, entity: 'Products' as const, sku: '', channel: '', accountId: '', marketplace: '', aliasKey: '', locale: '', field: '', action: 'SET' as const }
const contentFields = new Set(['name', 'title', 'description', 'bulletPoints', 'keywords'])

/** Shared destination choices without loading category dictionaries or provider metadata. */
export async function catalogDestinationOptions() {
  const [families, accounts, markets] = await Promise.all([
    prisma.productFamily.findMany({ select: { id: true, code: true, label: true }, orderBy: { label: 'asc' } }),
    Promise.all(TRANSFER_CHANNELS.map(channel => listActiveConnections(channel))).then(accounts => accounts.flat()),
    prisma.marketplace.findMany({ where: { isActive: true }, select: { channel: true, code: true, name: true, language: true, languages: true }, orderBy: { code: 'asc' } }),
  ])
  return { families,
    accounts: accounts.map(a => ({ id: a.id, channelType: a.channelType, marketplace: a.marketplace, accountLabel: a.accountLabel, isPrimary: a.isPrimary, displayName: `${a.accountLabel || a.displayName || a.channelType}${a.isPrimary ? ' · Primary account' : ''} · ${a.id.slice(-6)}` })),
    markets: markets.filter(m => TRANSFER_CHANNELS.includes(m.channel) && (m.code === 'GLOBAL' || /^[A-Z]{2}$/.test(m.code))).map(m => ({ ...m, language: marketLanguages(m.channel, m.code, [m])[0] })),
  }
}
export async function catalogTransferOptions() {
  const [destinations, categories, channelCategories, categoryLabels] = await Promise.all([
    catalogDestinationOptions(),
    prisma.category.findMany({ where: { isActive: true }, select: { id: true, name: true, slug: true, parentId: true }, orderBy: [{ depth: 'asc' }, { sortOrder: 'asc' }] }),
    prisma.categorySchema.findMany({ where: { channel: { in: TRANSFER_CHANNELS }, isActive: true }, distinct: ['channel', 'marketplace', 'productType'], select: { channel: true, marketplace: true, productType: true }, orderBy: [{ channel: 'asc' }, { productType: 'asc' }] }),
    prisma.categoryChannelMapping.findMany({ where: { channel: { in: TRANSFER_CHANNELS }, reviewedAt: { not: null }, channelCategoryPath: { not: null } }, select: { channel: true, marketplace: true, channelCategoryId: true, channelCategoryPath: true }, orderBy: { updatedAt: 'desc' } }),
  ])
  const labels = new Map<string, string>()
  for (const label of categoryLabels) {
    const key = JSON.stringify([label.channel, label.marketplace, label.channelCategoryId])
    if (label.channelCategoryPath && !labels.has(key)) labels.set(key, label.channelCategoryPath)
  }
  return { ...destinations, categories, channelCategories: channelCategories.map(c => ({ ...c,
    label: labels.get(JSON.stringify([c.channel, c.marketplace?.replace(/^EBAY_/, ''), c.productType]))
      ?? labels.get(JSON.stringify([c.channel, '*', c.productType])) ?? null,
  })) }
}

export async function catalogTransferTemplate(market: string, familyId: string, channel?: { channel: string; accountId: string; marketplace: string; category: string }) {
  const family = await prisma.productFamily.findUnique({ where: { id: familyId }, select: { code: true } })
  if (!family) throw new Error('Select a product family for the template')
  const contracts = transferContracts(market)
  const cols = await contracts.master(familyId)
  const localizedOnly = cols.some(col => col.storage === 'localizedContent' && !contentFields.has(col.key))
  const templateLocale = localizedOnly ? (await marketLanguages(channel?.channel ?? 'AMAZON', market))[0] : ''
  if (localizedOnly && !templateLocale) throw new Error('Configure a marketplace language before creating this localized template')
  const rows: TransferRow[] = [
    { ...empty, field: 'family', value: family.code },
    { ...empty, field: 'parentSku', action: '' as TransferRow['action'] },
  ]
  const dictionary: Record<string, unknown>[] = [
    { entity: 'Products', field: 'parentSku', label: 'Parent SKU', group: 'Product relationships', type: 'text', editable: true, required: false, options: [],
      help: 'SET the parent SKU on a child. Include a new parent and its children in the same file. Blank action and value preserve the current parent. CLEAR explicitly unlinks. Product role is calculated, never imported as a separate attribute.' },
  ]
  for (const col of cols) {
    dictionary.push({ entity: 'Products', field: col.key, label: col.label, group: col.group, type: col.shape === 'scalar' || !col.shape ? col.kind : col.shape, editable: col.editable && !MANAGED_FIELDS.has(col.key), required: col.requiredBy.length > 0, options: col.options ?? [], help: col.helpText ?? '' })
    if (col.editable && !MANAGED_FIELDS.has(col.key)) rows.push({ ...empty, field: col.key, locale: col.storage === 'localizedContent' && !contentFields.has(col.key) ? templateLocale! : '', action: '' as TransferRow['action'] })
  }
  if (channel) {
    const account = await prisma.channelConnection.findUnique({ where: { id: channel.accountId }, select: { channelType: true, marketplace: true, isActive: true } })
    if (!account || account.isActive === false || account.channelType !== channel.channel || account.marketplace && !['GLOBAL', channel.marketplace].includes(account.marketplace)) throw new Error('Select an active account that matches the channel and marketplace')
    const identity = { ...empty, channel: channel.channel, accountId: channel.accountId, marketplace: channel.marketplace }
    rows.push({ ...identity, entity: 'Listings', field: transferCategoryField(channel.channel), action: channel.category ? 'SET' : '' as TransferRow['action'], value: channel.category ? channel.channel === 'ETSY' ? Number(channel.category) : channel.category : undefined })
    const contract = await contracts.channel(channel.channel, channel.marketplace, channel.category)
    for (const field of contract.fields) {
      if (field.fieldKey === transferCategoryField(channel.channel)) continue
      if (managedChannelField(field)) continue
      dictionary.push({ entity: 'Overrides', field: field.fieldKey, label: field.label, group: field.group, type: field.shape ?? field.kind, editable: field.editable, required: field.priority, options: field.options ?? [], help: field.helpText ?? '' })
      rows.push({ ...identity, entity: 'Overrides', field: field.fieldKey, action: '' as TransferRow['action'] })
    }
  }
  return writeTransferWorkbook(rows, dictionary)
}

type ExportInput = { skus?: string[]; familyId?: string; market: string; marketplaces?: string[]; effective?: boolean; layout?: 'wide' | 'attributes'; boundary?: ProductTransferBoundary; fields?: string[]; workbookWriter?: (scopes: import('./catalog-workbook.js').WorkbookScope[]) => Promise<Buffer> }
const productInclude = { translations: true, categories: { select: { categoryId: true, isPrimary: true } }, parent: { include: { translations: true } } } as const

async function catalogRows(
  products: Prisma.ProductGetPayload<{ include: typeof productInclude }>[],
  input: ExportInput,
  contracts: ReturnType<typeof transferContracts>,
  families: { id: string; code: string }[],
  workbookMeta?: WeakMap<TransferRow, { fields: WorkbookField[]; category: string; note?: string }>,
  languages?: Map<string, string>,
) {
  const rows: TransferRow[] = []
  const listings = await prisma.channelListing.findMany({ where: { productId: { in: products.map(p => p.id) }, channel: { in: TRANSFER_CHANNELS }, ...(input.boundary ? { id: { in: input.boundary.listings.map(l => l.id) } } : input.marketplaces ? input.marketplaces.length ? { marketplace: { in: input.marketplaces } } : {} : { marketplace: input.market }) }, orderBy: [{ channel: 'asc' }, { marketplace: 'asc' }, { aliasKey: 'asc' }] })
  if (!input.effective && (!input.boundary || input.boundary.includeShared)) for (const product of products) {
    const start = rows.length
    const identity = { ...empty, sku: product.sku, version: product.version }
    const allColumns = await contracts.master(product.familyId ?? product.parent?.familyId ?? null, product as unknown as TransferProduct)
    const columns = input.boundary ? allColumns.filter(c => c.editable && !MANAGED_FIELDS.has(c.key)) : allColumns
    const metadata: Record<string, unknown> = { family: families.find(f => f.id === product.familyId)?.code ?? null, parentSku: product.parent?.sku ?? null, categoryIds: product.categories.map(c => c.categoryId).sort(), primaryCategoryId: product.categories.find(c => c.isPrimary)?.categoryId ?? null }
    for (const [field, value] of Object.entries(metadata)) rows.push({ ...identity, field, action: value === null ? 'INHERIT' : 'SET', value: value ?? undefined })
    for (const col of columns) {
      if (col.key === 'sku' || col.slot) continue
      if (col.storage !== 'localizedContent' || contentFields.has(col.key)) {
        const own = masterTransferState(product, col)
        rows.push({ ...identity, field: col.key, action: own.state === 'inherited' ? 'INHERIT' : own.value === null ? 'CLEAR' : 'SET', value: own.value })
      }
      const locales = new Set(input.boundary?.locales ?? [...contentLanguages(product, product.parent), ...listings.filter(l => l.productId === product.id).map(l => languages?.get(JSON.stringify([l.channel, l.marketplace]))).filter((l): l is string => !!l)])
      for (const locale of locales) {
        // Source core fields already have their existing language-neutral row. Explicitly selected languages retain their sheet.
        if (!input.boundary && locale === PRIMARY_CONTENT_LOCALE && contentFields.has(col.key)) continue
        if (!contentFields.has(col.key) && col.storage !== 'localizedContent') continue
        const localized = masterTransferState(product, col, normalizeLanguage(locale))
        const present = localized.state === 'stored'
        if (!present && !workbookMeta) continue
        rows.push({ ...identity, field: col.key, locale, action: !present ? 'INHERIT' : localized.value === null ? 'CLEAR' : 'SET', value: localized.value })
      }
    }
    if (workbookMeta) {
      const localized = columns.filter(c => !c.slot && (contentFields.has(c.key) || c.storage === 'localizedContent')).map(masterWorkbookField)
      const shared = [...relationshipFields.map(f => input.boundary && f.field === 'parentSku' ? { ...f, editable: false, help: 'Reference only in a product import. Manage parent relationships in the product relationship tools.' } : f), ...columns.filter(c => !c.slot && (c.storage !== 'localizedContent' || contentFields.has(c.key))).map(masterWorkbookField)]
      for (const row of rows.slice(start)) workbookMeta.set(row, { category: '', fields: row.locale ? localized : shared })
    }
  }
  const { resolveCategoriesForProducts } = await import('./mapping/category-mapping.service.js')
  const defaults = new Map<string, Awaited<ReturnType<typeof resolveCategoriesForProducts>>>()
  for (const coordinate of new Set(listings.map(l => JSON.stringify([l.channel, l.marketplace])))) {
    const [channel, marketplace] = JSON.parse(coordinate)
    defaults.set(coordinate, await resolveCategoriesForProducts({ productIds: products.map(p => p.id), channel, marketplace }))
  }
  for (const listing of listings) {
    const start = rows.length
    const sku = products.find(p => p.id === listing.productId)!.sku
    if (!listing.channelConnectionId) throw new Error(`${sku}: a ${listing.channel} listing has no account attribution. Assign its account before exporting an editable listing.`)
    const identity = { ...empty, sku, entity: 'Overrides' as const, channel: listing.channel, accountId: listing.channelConnectionId, marketplace: listing.marketplace, aliasKey: listing.aliasKey, version: listing.version }
    const categoryKey = transferCategoryField(listing.channel)
    const platform = jsonRecord(listing.platformAttributes)
    const hasCategory = Object.prototype.hasOwnProperty.call(platform, categoryKey)
    const storedCategory = platform[categoryKey]
    const category = String((hasCategory && transferIsStore(listing.channel) ? storedCategory : storedCategory ?? defaults.get(JSON.stringify([listing.channel, listing.marketplace]))?.[listing.productId]?.channelCategoryId) ?? '')
    const contract = await contracts.channel(listing.channel, listing.marketplace, category)
    if (input.effective) {
      const { resolveBatch } = await import('./mapping/resolve-batch.service.js')
      const result = await resolveBatch({ productIds: [listing.productId], channel: listing.channel, marketplace: listing.marketplace, channelConnectionId: listing.channelConnectionId, aliasKey: listing.aliasKey, productType: category, includeCatalogue: false })
      for (const value of Object.values(result.products[0]?.cells ?? {})) rows.push({ ...identity, field: value.fieldKey, action: 'SET', value: value.value })
    } else {
      rows.push({ ...identity, entity: 'Listings', field: categoryKey, action: storedCategory != null ? 'SET' : hasCategory && transferIsStore(listing.channel) ? 'CLEAR' : 'INHERIT', value: storedCategory ?? undefined })
      for (const field of contract.fields) {
        if (field.fieldKey === categoryKey) continue
        if (input.boundary && managedChannelField(field)) continue
        const own = storedChannelState(listing, field.channelStore, [field.fieldKey, field.sheetKey].filter((k): k is string => !!k))
        const value = typeof own.value === 'object' && own.value && 'toNumber' in own.value ? (own.value as { toNumber(): number }).toNumber() : own.value
        rows.push({ ...identity, field: field.fieldKey, action: own.state === 'inherited' ? 'INHERIT' : value === null ? 'CLEAR' : 'SET', value })
      }
    }
    if (workbookMeta) {
      const fields = [{ field: categoryKey, label: 'Channel category', type: listing.channel === 'ETSY' ? 'number' : 'text' }, ...contract.fields.filter(f => f.fieldKey !== categoryKey && (!input.boundary || !managedChannelField(f))).map(f => ({ ...channelWorkbookField(f), schemaVersion: contract.schemaVersion, help: `${channelWorkbookField(f).help} ${contract.fetchedAt ? `Schema retrieved ${contract.fetchedAt}.` : `Field definition ${contract.schemaVersion ?? 'unversioned'}.`}` }))]
      for (const row of rows.slice(start)) workbookMeta.set(row, { category, fields, note: contract.warning })
    }
  }
  return rows
}


export async function exportCatalogTransfer(input: ExportInput) {
  if (input.marketplaces && (!Array.isArray(input.marketplaces) || input.marketplaces.length > 50 || input.marketplaces.some(m => !/^(?:[A-Z]{2}|GLOBAL)$/.test(m)))) throw new Error('Select valid marketplace codes')
  if (!input.boundary && !input.skus?.length && !input.familyId) throw new Error('Choose a family or specify the SKUs to export')
  const requested = input.skus?.length ? [...new Set(input.skus.map(sku => sku.trim()))] : undefined
  // Capture identities once; fetch full records in bounded pages. A family export has no SKU cap.
  const selection = await prisma.product.findMany({ where: { deletedAt: null,
    ...(input.boundary ? { id: { in: input.boundary.products.map(p => p.id) } } : requested ? { sku: { in: requested } } : { OR: [{ familyId: input.familyId }, { familyId: null, parent: { familyId: input.familyId } }] }),
  }, select: { id: true, sku: true }, orderBy: { sku: 'asc' } })
  if (!selection.length) throw new Error('No products matched this export')
  const selectedSkus = new Set(selection.map(product => product.sku))
  if (requested?.some(sku => !selectedSkus.has(sku))) throw new Error('Some requested SKUs are missing or archived; correct the selection before exporting')
  const contracts = transferContracts(input.market, { allowIncompleteSchema: true })
  const families = await prisma.productFamily.findMany({ select: { id: true, code: true } })
  const workbookMeta = input.layout === 'wide' && !input.effective ? new WeakMap<TransferRow, { fields: WorkbookField[]; category: string; note?: string }>() : undefined
  // Match resolveBatch’s default locale from the same channel-qualified authority.
  const languages = workbookMeta ? new Map((await prisma.marketplace.findMany({ where: { isActive: true }, select: { channel: true, code: true, language: true, languages: true } })).map(m => [JSON.stringify([m.channel, m.code]), marketLanguages(m.channel, m.code, [m])[0]])) : undefined
  async function* productRows() {
    for (let offset = 0; offset < selection.length; offset += 100) {
      const ids = selection.slice(offset, offset + 100).map(product => product.id)
      const products = await prisma.product.findMany({ where: { id: { in: ids }, deletedAt: null }, include: productInclude, orderBy: { sku: 'asc' } })
      if (products.length !== ids.length) throw new Error('The selected catalog changed during export. Download it again to include every product.')
      const rows = await catalogRows(products, input, contracts, families, workbookMeta, languages)
      const bySku = new Map<string, TransferRow[]>()
      for (const row of rows.filter(r => !input.fields || ['family', 'parentSku', 'productType', 'categoryId'].includes(r.field) || input.fields.includes(r.field))) {
        if (!bySku.has(row.sku)) bySku.set(row.sku, [])
        bySku.get(row.sku)!.push(row)
      }
      for (const product of products) yield bySku.get(product.sku) ?? []
    }
  }
  return writeTransferDownload(productRows(), !!input.effective, workbookMeta ? rows => {
    const filtered = new WeakMap<WorkbookField[], WorkbookField[]>()
    const scopes = workbookScopesForRows(rows, row => {
      const fields = workbookMeta.get(row)?.fields ?? []
      if (!input.fields) return fields
      if (!filtered.has(fields)) filtered.set(fields, fields.filter(f => ['family', 'parentSku', 'productType', 'categoryId'].includes(f.field) || input.fields!.includes(f.field)))
      return filtered.get(fields)!
    }, row => workbookMeta.get(row)?.category ?? '')
    for (const scope of scopes) scope.note = workbookMeta.get(scope.rows[0])?.note
    return input.workbookWriter ? input.workbookWriter(scopes) : writeCatalogWorkbook(scopes, !!input.boundary)
  } : undefined, !!input.boundary)
}

