    }
  })
  it('maps exact category concepts, keeps constrained choices visible and preserves scale-specific distinctions', () => {
    const props = etsyTaxonomySpec('1', [property(), property({ property_id: 201, name: 'secondary_color' }),
      property({ property_id: 202, name: 'size', scales: [{ scale_id: 9, display_name: 'US' }] }),
      property({ property_id: 203, name: 'size', supports_attributes: false }),
      property({ property_id: 204, selected_values: [{ value_id: 1, name: 'Black' }] })]).fields
    expect(masterDefaultRule(props[0], keys)?.source).toBe('color')
    expect(planProductSource(props[0], 'ETSY', 'it')).toMatchObject({ rule: { source: 'color' }, definitions: [] })
    expect(validate(props[0], 'Nero')).toMatchObject({ value: 'Nero', errors: [expect.stringContaining('unaccepted')] })
    for (const id of [201, 202, 203]) expect(masterDefaultRule(props.find(f => f.key === `property_${id}`), keys)).toBeNull()
    expect(masterDefaultRule(props.find(f => f.key === 'property_204'), keys)?.transforms).toEqual([{ type: 'default', value: '1' }])
    for (const key of ['taxonomy_id', 'who_made', 'when_made', 'is_supply', 'type', 'shipping_profile_id', 'return_policy_id'])
      expect(masterDefaultRule(field(key), keys), key).toBeNull()
  })
})

import { etsyListingSchema } from './etsy-listing-schema.js'
import { humanizeKey, type ChannelFieldSpec, type ChannelGroup, type ChannelSpec, type ChannelStore } from './types.js'

const groups: ChannelGroup[] = ['Content', 'Classification', 'Search', 'Offer', 'Shipping', 'Policies', 'Listing status', 'Category attributes']
  .map((label, order) => ({ key: label.toLowerCase().replace(/ /g, '_'), label, channelLabel: null, order }))
const pa = (...path: string[]): ChannelStore => ({ kind: 'platformAttributes', path })
const column = (column: string, followFlag?: string): ChannelStore => ({ kind: 'listingColumn', column, followFlag })
function field(key: string, label: string, group: string, extra: Partial<ChannelFieldSpec> = {}): ChannelFieldSpec {
  return { key, attribute: key, path: [], label, englishLabel: label, kind: 'text', shape: 'scalar',
    cardinality: { min: 0, max: 1 }, requirement: 'optional', requiredInParent: false,
    editable: true, hidden: false, variantEligible: false, group: groups.find(g => g.key === group)!,
    channelStore: pa(key), ...extra }
}
const titleStore = column('title', 'followMasterTitle')
const descriptionStore = column('description', 'followMasterDescription')
const idRules = { minimum: 1, multipleOf: 1 }
const positive = { exclusiveMinimum: 0 }
const words = '^[\\p{L}\\p{Nd}\\p{Zs}]+$'

function coreFields(): ChannelFieldSpec[] {
  return [
    field('title', 'Title', 'content', { masterKey: 'name', kind: 'longtext', requirement: 'required', maxLength: 140, channelStore: titleStore,
      validation: { pattern: '^(?!.*%.*%)(?!.*:.*:)(?!.*&.*&)(?!.*\\+.*\\+)[\\p{L}\\p{Nd}\\p{P}\\p{Sm}\\p{Zs}™©®]+$' },
      helpText: 'Up to 140 characters. %, :, & and + may each appear only once.' }),
    field('description', 'Description', 'content', { masterKey: 'description', kind: 'longtext', requirement: 'required', channelStore: descriptionStore,
      helpText: 'Plain text description for this Etsy listing.' }),
    field('tags', 'Tags', 'search', { masterKey: 'keywords', shape: 'list', cardinality: { min: 0, max: 13 }, maxLength: 20,
      validation: { uniqueItems: true, pattern: "^[\\p{L}\\p{Nd}\\p{Zs}™©®][\\p{L}\\p{Nd}\\p{Zs}\\-'™©®]*$" }, helpText: 'Up to 13 tags, with up to 20 characters in each.' }),
    field('materials', 'Materials', 'content', { masterKey: 'material', shape: 'list', cardinality: { min: 0, max: null }, validation: { pattern: words },
      helpText: 'Materials used to make this item. Use letters, numbers and spaces.' }),
    field('taxonomy_id', 'Category', 'classification', { kind: 'number', requirement: 'required', validation: idRules,
      sourceOwner: { kind: 'listing', label: 'Etsy category selection', path: 'listing.platformAttributes.taxonomy_id' },
      helpText: 'Etsy seller taxonomy category ID. Refresh requirements after changing this category.' }),
    field('who_made', 'Who made it', 'classification', { kind: 'select', mode: 'strict', requirement: 'required',
      options: ['i_did', 'someone_else', 'collective'], optionLabels: { i_did: 'I did', someone_else: 'Someone else', collective: 'A member of my shop' } }),
    field('when_made', 'When made', 'classification', { kind: 'select', mode: 'strict', requirement: 'required',
      options: ['made_to_order', '2020_2026', '2010_2019', '2007_2009', 'before_2007', '2000_2006', '1990s', '1980s', '1970s', '1960s', '1950s', '1940s', '1930s', '1920s', '1910s', '1900s', '1800s', '1700s', 'before_1700'],
      optionLabels: { made_to_order: 'Made to order', '2020_2026': '2020–2026', '2010_2019': '2010–2019', '2007_2009': '2007–2009', before_2007: 'Before 2007', '2000_2006': '2000–2006', before_1700: 'Before 1700' } }),
    field('is_supply', 'Craft supply', 'classification', { kind: 'boolean', requirement: 'required' }),
    field('type', 'Listing type', 'classification', { kind: 'select', mode: 'strict', options: ['physical', 'download', 'both'],
      optionLabels: { physical: 'Physical item', download: 'Digital download', both: 'Physical and digital' } }),
    field('production_partner_ids', 'Production partner IDs', 'classification', { kind: 'number', shape: 'list', cardinality: { min: 0, max: null }, validation: { ...idRules, uniqueItems: true } }),
    field('shop_section_id', 'Shop section', 'classification', { kind: 'number', validation: idRules }),
    field('price', 'Price', 'offer', { kind: 'number', requirement: 'required', validation: positive, channelStore: column('price', 'followMasterPrice') }),
    field('quantity', 'Quantity', 'offer', { kind: 'number', requirement: 'required', validation: { minimum: 0, multipleOf: 1 }, channelStore: column('quantity', 'followMasterQuantity') }),
    field('item_weight', 'Item weight', 'shipping', { masterKey: 'weightValue', kind: 'number', validation: positive }),
    field('item_weight_unit', 'Weight unit', 'shipping', { masterKey: 'weightUnit', kind: 'select', mode: 'strict', options: ['oz', 'lb', 'g', 'kg'] }),
    field('item_length', 'Item length', 'shipping', { masterKey: 'dimLength', kind: 'number', validation: positive }),
    field('item_width', 'Item width', 'shipping', { masterKey: 'dimWidth', kind: 'number', validation: positive }),
    field('item_height', 'Item height', 'shipping', { masterKey: 'dimHeight', kind: 'number', validation: positive }),
    field('item_dimensions_unit', 'Dimension unit', 'shipping', { masterKey: 'dimUnit', kind: 'select', mode: 'strict', options: ['in', 'ft', 'mm', 'cm', 'm', 'yd', 'inches'] }),
    field('shipping_profile_id', 'Shipping profile', 'shipping', { kind: 'number', validation: idRules }),
    field('return_policy_id', 'Return policy', 'policies', { kind: 'number', validation: idRules }),
    field('is_taxable', 'Taxable', 'policies', { kind: 'boolean' }),
    field('should_auto_renew', 'Automatic renewal', 'policies', { kind: 'boolean', helpText: 'Renewal preference saved in Nexus. Publishing and renewal are separate channel actions.' }),
  ]
}

export interface EtsyTaxonomyValue { value_id: number | null; name: string; scale_id?: number | null; equal_to?: number[] }
export interface EtsyTaxonomyProperty {
  property_id: number; name: string; display_name: string
  is_required: boolean; supports_attributes: boolean; supports_variations: boolean
  is_multivalued: boolean; max_values_allowed: number | null
  scales: Array<{ scale_id: number; display_name: string; description?: string }>
  possible_values: EtsyTaxonomyValue[]; selected_values: EtsyTaxonomyValue[]
}

type NativeSchema = { type?: string; enum?: readonly string[]; items?: NativeSchema; minimum?: number; maximum?: number }
const native = etsyListingSchema.listing.properties as Record<string, NativeSchema>
const create = etsyListingSchema.create.properties as Record<string, NativeSchema>
const update = etsyListingSchema.update.properties as Record<string, NativeSchema>
const aliases: Record<string, string> = { listing_type: 'type', style: 'styles', creation_timestamp: 'created_timestamp', last_modified_timestamp: 'updated_timestamp' }
const shipping = new Set(['processing_min', 'processing_max', 'readiness_state_id'])

/** Every API field is represented by a sheet column or shared workspace; remote metadata stays read-only. */
export function etsyProductSpec(locale?: string): ChannelSpec {
  const fields = coreFields()
  const byKey = new Map(fields.map(f => [f.key, f]))
  const coverage: Record<string, string[]> = {}
  const all = { ...native, ...create, ...update }
  for (const [attribute, raw] of Object.entries(all)) {
    const key = aliases[attribute] ?? attribute
    const definition = update[key] ?? create[key] ?? raw
    const writable = !!(create[key] || update[key]) && key !== 'state'
    if (definition.type === 'money') {
      coverage[attribute] = []
      for (const leaf of ['amount', 'divisor', 'currency_code']) {
        const f = field(`${key}__${leaf}`, `Converted price ${leaf === 'currency_code' ? 'currency' : leaf}`, 'offer', {
          attribute, path: [leaf], kind: leaf === 'currency_code' ? 'text' : 'number',
          channelStore: pa(key, leaf), editable: false, readOnlyReason: 'Converted price reported by Etsy.',
          helpText: 'Reported by Etsy. Divide amount by divisor for the price in this currency.',
        })
        fields.push(f); byKey.set(f.key, f); coverage[attribute].push(f.key)
      }
      continue
    }
    if (!byKey.has(key)) {
      const scalar = definition.type === 'array' ? definition.items! : definition
      const f = field(key, humanizeKey(key), shipping.has(key) ? 'shipping' : writable ? 'content' : 'listing_status', {
        kind: scalar.type === 'boolean' ? 'boolean' : ['number', 'integer', 'money'].includes(scalar.type ?? '') ? 'number' : scalar.enum ? 'select' : key.endsWith('description') ? 'longtext' : 'text',
        shape: definition.type === 'array' ? 'list' : 'scalar',
        cardinality: { min: 0, max: definition.type === 'array' ? null : 1 },
        ...(scalar.enum ? { options: [...scalar.enum], mode: 'strict' } : {}),
        validation: { ...(scalar.type === 'integer' ? { multipleOf: 1 } : {}), ...(scalar.minimum !== undefined ? { minimum: scalar.minimum } : {}) },
        ...(writable ? {} : { editable: false, readOnlyReason: 'Reported by Etsy. This field cannot be edited in the information sheet.', helpText: 'Reported by Etsy. This field cannot be edited in the information sheet.' }),
      })
      fields.push(f); byKey.set(key, f)
    }
    coverage[attribute] = [key]
  }
  Object.assign(byKey.get('type')!, { channelStore: { kind: 'platformAttributes', path: ['type'], legacyPaths: [['listing_type']] } })
  Object.assign(byKey.get('styles')!, { masterKey: 'style', label: 'Styles', englishLabel: 'Styles', cardinality: { min: 0, max: 2 }, maxLength: 45, validation: { pattern: words, uniqueItems: true }, channelStore: { kind: 'platformAttributes', path: ['styles'], legacyPaths: [['style']] }, helpText: 'Inherits Master Style. Up to two styles, 45 characters each. Etsy accepts styles when creating a listing.' })
  Object.assign(byKey.get('image_ids')!, { managedBy: 'productMedia', label: 'Product media', englishLabel: 'Product media', editable: false,
    readOnlyReason: 'Manage images and their order in Product media. Etsy image IDs are remote references, not Nexus asset IDs.',
    cardinality: { min: 0, max: 20 }, validation: { ...idRules, uniqueItems: true },
    helpText: 'Uses the shared Product media gallery for this Etsy account, listing and language. Etsy image IDs are assigned by Etsy after upload; saving the gallery does not publish images.' })
  for (const [alias, key] of Object.entries(aliases).filter(([alias]) => alias.endsWith('_timestamp'))) {
    Object.assign(byKey.get(key)!, { channelStore: { kind: 'platformAttributes', path: [key], legacyPaths: [[alias]] },
      label: key === 'created_timestamp' ? 'Created on Etsy' : 'Updated on Etsy', englishLabel: key === 'created_timestamp' ? 'Created on Etsy' : 'Updated on Etsy' })
  }
  Object.assign(byKey.get('readiness_state_id')!, { label: 'Processing profile', englishLabel: 'Processing profile', helpText: 'Etsy processing profile. Existing variation offerings use the inventory endpoint.' })
  Object.assign(byKey.get('rich_description')!, { helpText: 'HTML description reported by Etsy, displayed as text. The listing API accepts plain-text description updates.' })
  Object.assign(byKey.get('state')!, { label: 'Listing status', englishLabel: 'Listing status', options: [...native.state.enum!], helpText: 'Reported by Etsy. Publishing, renewing and deactivating are separate channel actions.' })
  const currency = field('price_currency_code', 'Currency', 'offer', { channelStore: pa('price', 'currency_code'), editable: false, readOnlyReason: 'Currency reported by Etsy.', helpText: 'Currency reported by Etsy.' })
  fields.push(currency); coverage.price.push(currency.key)
  if (locale) for (const key of ['title', 'description', 'tags']) {
    const f = byKey.get(key)
    if (f) { f.channelStore = pa('_etsyInformationLocales', locale, key); f.helpText = `${f.helpText ?? ''} Saved as a Nexus draft for ${locale}. Etsy translation delivery is not connected to this save.`.trim() }
  }
  Object.assign(byKey.get('language')!, { editable: false, readOnlyReason: 'Original listing language reported by Etsy. Use the content language selector for translations.', helpText: 'Original listing language reported by Etsy.' })
  return makeSpec('*', fields, coverage)
}

/** Stable property IDs, all seller-category properties, exact multiplicity, scales and choices. */
export function etsyTaxonomySpec(category: string, properties: EtsyTaxonomyProperty[], fetchedAt: Date | null = null): ChannelSpec {
  const fields: ChannelFieldSpec[] = [], coverage: Record<string, string[]> = {}
  for (const property of properties) {
    const key = `property_${property.property_id}`
    const selected = property.selected_values ?? []
    const knownValues = [...selected, ...property.possible_values]
    const codeFor = (value: EtsyTaxonomyValue) => value.value_id == null ? value.name : String(value.value_id)
    const choices = [...new Set(knownValues.map(codeFor))]
    const fixed = selected.length > 0
    const editable = property.supports_attributes && !fixed
    const reason = fixed ? 'Etsy selects this value automatically for the category.' : !property.supports_attributes ? 'This property belongs to Etsy variation inventory.' : undefined
    const label = property.display_name || property.name
    const values = field(key, property.supports_attributes ? label : `${label} (${property.property_id})`, 'category_attributes', {
      shape: property.is_multivalued ? 'list' : 'scalar', kind: choices.length ? 'select' : 'text',
      cardinality: { min: 0, max: property.is_multivalued ? property.max_values_allowed && property.max_values_allowed > 0 ? property.max_values_allowed : null : 1 },
      requirement: property.is_required && property.supports_attributes && !fixed ? 'required' : 'optional',
      variantEligible: property.supports_variations, editable, readOnlyReason: reason,
      options: choices.length ? choices : undefined, mode: choices.length ? 'strict' : 'open',
      optionLabels: Object.fromEntries(knownValues.map(value => [codeFor(value), value.name])),
      validation: { pattern: '^[^()]+$', uniqueItems: true,
        etsyValues: knownValues.map(value => ({ code: codeFor(value), label: value.name, scaleId: value.scale_id == null ? null : String(value.scale_id) })) },
      channelStore: pa('etsyProperties', String(property.property_id), property.is_multivalued ? 'values' : 'value'),
      helpText: [reason, `Etsy property ${property.property_id}.`, property.supports_variations ? 'Available for variations.' : 'Listing attribute.'].filter(Boolean).join(' '),
      ...(fixed ? { defaultRule: { source: '', transforms: [{ type: 'default', value: property.is_multivalued ? selected.map(codeFor) : codeFor(selected[0]) }] } } : {}),
    })
    // Stable semantic names only. Keep property IDs as the destination so a category's
    // scale/choices remain independent of Master and of other Etsy properties.
    const source = ({ color: 'color', primary_color: 'color', material: 'material', materials: 'material', style: 'style', size: 'size' } as Record<string, string>)[property.name]
    if (editable && source && !property.scales.length) values.defaultRule = { source,
      notes: `Inherits Master ${source}. Etsy choices and limits are validated; values are never guessed or truncated.` }
    fields.push(values); coverage[String(property.property_id)] = [key]
    if (property.scales.length) {
      const scale = field(`${key}__scale_id`, `${values.label} scale`, 'category_attributes', {
        kind: 'select', options: property.scales.map(s => String(s.scale_id)), mode: 'strict',
        optionLabels: Object.fromEntries(property.scales.map(s => [String(s.scale_id), s.display_name])),
        editable, readOnlyReason: reason, channelStore: pa('etsyProperties', String(property.property_id), 'scale_id'),
        helpText: reason ?? `Measurement scale for ${values.label}. Select the scale that matches its value.`,
      })
      fields.push(scale); coverage[String(property.property_id)].push(scale.key)
    }
  }
  return { ...makeSpec(category, fields, coverage), fetchedAt }
}

function makeSpec(category: string, fields: ChannelFieldSpec[], coverage: Record<string, string[]>): ChannelSpec {
  const properties = Object.fromEntries(fields.filter(f => f.editable).map(f => {
    const scalar = { type: f.kind === 'number' ? 'number' : f.kind === 'boolean' ? 'boolean' : 'string',
      ...(f.options ? { enum: f.options } : {}), ...(f.maxLength ? { maxLength: f.maxLength } : {}),
      ...Object.fromEntries(Object.entries(f.validation ?? {}).filter(([key]) => !['uniqueItems', 'etsyValues'].includes(key))) }
    return [f.attribute, f.shape === 'list' ? { type: 'array', items: scalar,
      ...(f.cardinality.max !== null ? { maxItems: f.cardinality.max } : {}), ...(f.validation?.uniqueItems ? { uniqueItems: true } : {}) } : scalar]
  }))
  const allOf: Record<string, unknown>[] = []
  for (const field of fields) {
    const scale = fields.find(candidate => candidate.key === `${field.key}__scale_id`)
    if (!field.editable || !scale) continue
    allOf.push({ if: { required: [field.attribute] }, then: { required: [scale.attribute] } })
    const values = field.validation?.etsyValues as Array<{ code: string; scaleId: string | null }> | undefined
    for (const scaleId of scale.options ?? []) {
      const allowed = values?.filter(value => value.scaleId == null || value.scaleId === scaleId).map(value => value.code) ?? []
      if (!values?.length) continue
      allOf.push({ if: { required: [scale.attribute], properties: { [scale.attribute]: { const: scaleId } } },
        then: { properties: { [field.attribute]: field.shape === 'list' ? { items: { enum: allowed } } : { enum: allowed } } } })
    }
  }
  return { channel: 'ETSY', marketplace: 'GLOBAL', category, fields, coverage,
    validationSchema: { type: 'object', properties, required: fields.filter(f => f.requirement === 'required').map(f => f.attribute), ...(allOf.length ? { allOf } : {}) },
    groups: groups.filter(g => fields.some(f => f.group?.key === g.key)),
    fetchedAt: null, schemaVersion: `etsy-listing-${etsyListingSchema.verifiedAt}`, unrecognised: [], absent: false }
}

import { describe, expect, it } from 'vitest'
import { etsyProductSpec, etsyTaxonomySpec, type EtsyTaxonomyProperty } from './etsy.js'
import { etsyListingSchema } from './etsy-listing-schema.js'
import { buildSheetColumns } from '../sheet-columns.service.js'
import { coerceForShape } from '../sheet-values.js'
import { channelValuePatch, storedChannelState } from '../channel-value-mutation.js'
import { masterDefaultRule } from '../mapping/master-default-rule.js'

export const property = (changes: Partial<EtsyTaxonomyProperty> = {}): EtsyTaxonomyProperty => ({
  property_id: 200, name: 'color', display_name: 'Primary color', is_required: true,
  supports_attributes: true, supports_variations: true, is_multivalued: false, max_values_allowed: 1,
  possible_values: [{ value_id: 4, name: 'Green', scale_id: null }], selected_values: [], scales: [], ...changes,
})
const coordinate = { channel: 'ETSY' as const, marketplace: 'GLOBAL', label: 'ETSY:GLOBAL', inMarket: true }
const columns = (...specs: ReturnType<typeof etsyProductSpec>[]) => buildSheetColumns({ fields: [], coordinates: [coordinate], specs: specs.map(spec => ({ coordinate, spec })), scopeKind: 'channel' }).columns

describe('Etsy listing coverage on the shared sheet', () => {
  it('accounts for every official listing response, create and update attribute', () => {
    const spec = etsyProductSpec(), keys = new Set(spec.fields.map(f => f.key))
    for (const source of [etsyListingSchema.listing, etsyListingSchema.create, etsyListingSchema.update]) {
      for (const name of Object.keys(source.properties)) {
        expect(spec.coverage[name]?.length, name).toBeGreaterThan(0)
        for (const key of spec.coverage[name]) expect(keys.has(key), key).toBe(true)
      }
    }
    expect(keys.size).toBe(spec.fields.length)
    expect(spec.unrecognised).toEqual([])
    const sheet = columns(spec)
    for (const f of spec.fields) expect(sheet.some(c => c.key === (f.masterKey ?? f.key) || c.slot?.of === (f.masterKey ?? f.key)), f.key).toBe(true)
  })
  it('locks response fields and lifecycle actions against both manual edits and formula defaults', () => {
    const spec = etsyProductSpec(), sheet = columns(spec)
    for (const key of ['image_ids', 'listing_id', 'state', 'rich_description', 'num_favorers', 'is_personalizable', 'converted_price__amount']) {
      const f = spec.fields.find(f => f.key === key)!
      expect(f.readOnlyReason, key).toBeTruthy()
      expect(sheet.find(c => c.key === key), key).toMatchObject({ editable: false, formulaWritable: false })
      expect(masterDefaultRule(f, new Set([key]))).toBeNull()
    }
    expect(spec.fields.find(f => f.key === 'state')?.options).toContain('draft')
  })
  it('keeps wire aliases and collection limits without hiding their original API identities', () => {
    const spec = etsyProductSpec(), sheet = columns(spec)
    expect(spec.coverage.style).toEqual(['styles'])
    expect(spec.coverage.listing_type).toEqual(['type'])
    expect(coerceForShape(sheet.find(c => c.key === 'image_ids'), Array.from({ length: 21 }, (_, i) => i + 1)).ok).toBe(false)
    const styles = spec.fields.find(f => f.key === 'styles')!
    expect(styles.cardinality.max).toBe(2)
    expect(styles.maxLength).toBe(45)
    const listing = { platformAttributes: { style: ['Formal'], listing_type: 'physical', untouched: true }, overrideData: {} }
    expect(storedChannelState(listing, styles.channelStore, ['styles']).value).toEqual(['Formal'])
    const patch = channelValuePatch(listing, styles.channelStore, ['styles'], 'SET', ['Steampunk'])
    expect(patch.platformAttributes).toEqual({ styles: ['Steampunk'], listing_type: 'physical', untouched: true })
  })
  it('declares only semantic master defaults for shared title, description, price and stock', () => {
    const spec = etsyProductSpec(), master = new Set(['name', 'description', 'basePrice', 'totalStock', 'type'])
    expect(['title', 'description', 'price', 'quantity'].map(key => masterDefaultRule(spec.fields.find(f => f.key === key), master)?.source)).toEqual(['title', 'description', 'basePrice', 'totalStock'])
    for (const key of ['taxonomy_id', 'type', 'who_made', 'when_made']) expect(masterDefaultRule(spec.fields.find(f => f.key === key), master)).toBeNull()
  })
})

describe('Etsy category attribute contracts', () => {
  it('uses stable property IDs, exact category applicability and independent storage', () => {
    const a = etsyTaxonomySpec('1', [property()]), b = etsyTaxonomySpec('2', [property({ property_id: 201, is_required: false })])
    const sheet = columns(etsyProductSpec(), a, b)
    expect(sheet.find(c => c.key === 'property_200')).toMatchObject({ applicableProductTypes: ['1'], requiredForProductTypes: ['1'], variantEligible: true })
    const f = a.fields[0], listing = { platformAttributes: { untouched: true, etsyProperties: { '201': { value: 'Red' } } }, overrideData: {} }
    const changed = { ...listing, ...channelValuePatch(listing, f.channelStore, [f.key], 'SET', 'Green') }
    expect(storedChannelState(changed, f.channelStore, [f.key]).value).toBe('Green')
    expect(changed.platformAttributes).toMatchObject({ untouched: true, etsyProperties: { '201': { value: 'Red' } } })
  })
  it('preserves multivalued constraints, measurement scales, fixed and variation-only properties', () => {
    const spec = etsyTaxonomySpec('1', [property({ is_multivalued: true, max_values_allowed: 12, scales: [{ scale_id: 19, display_name: 'US / Canada' }] }),
      property({ property_id: 2, supports_attributes: false }), property({ property_id: 3, selected_values: [{ value_id: 4, name: 'Green' }] })])
    expect(spec.fields.find(f => f.key === 'property_200')).toMatchObject({ shape: 'list', cardinality: { max: 12 } })
    expect(spec.fields.find(f => f.key === 'property_200__scale_id')).toMatchObject({ options: ['19'], optionLabels: { '19': 'US / Canada' } })
    expect(spec.fields.find(f => f.key === 'property_2')).toMatchObject({ editable: false, requirement: 'optional' })
    expect(spec.fields.find(f => f.key === 'property_3')).toMatchObject({ editable: false, defaultRule: { transforms: [{ type: 'default', value: '4' }] } })
    expect(Object.values(spec.coverage).flat()).toHaveLength(spec.fields.length)
    expect(coerceForShape(columns(spec).find(c => c.key === 'property_200'), Array(13).fill('Green')).ok).toBe(false)
  })
  it('allows free text only when Etsy declares no choices', () => {
    const spec = etsyTaxonomySpec('1', [property({ possible_values: [] })])
    const col = columns(spec)[0]
    expect(coerceForShape(col, 'Leather').ok).toBe(true)
    expect(coerceForShape(col, 'Leather (soft)').ok).toBe(false)
  })
})

import { cachedSchemasOnly } from '../cached-schema-context.js'
import { WorkspaceCache } from '../../../lib/workspace-cache.js'
/**
 * AM.1 — the DB-backed loaders for channel specs, with the caches the page-load path needs.
 *
 * CACHE ONLY, whatever the TTL on the row — the rule `schema-caps.ts` documented: a month-old cap
 * beats no cap, the age is REPORTED (`fetchedAt`), and refreshing is the schema-sync cron's job.
 * Nothing here calls SP-API or eBay; a page load must never wait on a channel.
 *
 * Invalidation is the schema's own freshness stamp (max `fetchedAt` + row count for the
 * coordinate), so a cache refresh changes the key and the walk happens again — a TTL would be stale
 * after a refresh and wasteful when none happened (the F6 rule in `field-registry.service.ts`).
 */
import prisma from '../../../db.js'
import { amazonSpecFromDefinition } from './amazon.js'
import { ebaySpecFromCache, type EbayCachedAspect, type EbayCachedCondition, type EbayChannelSchemaRow } from './ebay.js'
import { normaliseKey, type ChannelSpec } from './types.js'

export * from './types.js'
export { amazonSpecFromDefinition, AMAZON_MASTER_LINKS } from './amazon.js'
export { ebaySpecFromCache, aspectNames } from './ebay.js'

/**
 * Marketplaces whose cached Amazon schema carries ENGLISH titles (D10). Verified: `AMAZON:UK`
 * OUTERWEAR gives `item_name` = "Item Name", `fabric_type` = "Fabric Type", against DE's
 * "Artikelname" / "Gewebeart".
 */
export const ENGLISH_MARKETPLACES = ['UK', 'US', 'IE', 'AU', 'CA']

const specCache = new WorkspaceCache<string, { stamp: string; value: ChannelSpec }>()
const SPEC_CACHE_MAX = 256

function remember(key: string, stamp: string, value: ChannelSpec): ChannelSpec {
  if (specCache.size >= SPEC_CACHE_MAX) {
    const first = specCache.keys().next().value
    if (first !== undefined) specCache.delete(first)
  }
  specCache.set(key, { stamp, value })
  return value
}

/** Exported for tests and for a refresh path that wants to drop it explicitly. */
export function clearChannelSpecCache(): void {
  specCache.clear()
}

async function amazonStamp(marketplace: string, productType: string): Promise<string> {
  const rows = (await prisma.$queryRawUnsafe(
    `SELECT COALESCE(max("fetchedAt")::text, '') AS stamp, count(*)::int AS n
     FROM "CategorySchema" WHERE channel='AMAZON' AND marketplace=$1 AND "productType"=$2 AND "isActive"=true`,
    marketplace,
    productType,
  )) as { stamp: string; n: number }[]
  return `${rows[0]?.stamp ?? ''}:${rows[0]?.n ?? 0}`
}

/** The Amazon spec for one (marketplace × product type). `absent: true` when nothing is cached. */
export async function loadAmazonSpec(marketplace: string, productType: string, accountId?: string | null): Promise<ChannelSpec> {
  const mk = String(marketplace).toUpperCase()
  const pt = String(productType).toUpperCase()
  const key = `AMAZON|${mk}|${pt}`
  const stamp = await amazonStamp(mk, pt)
  const hit = specCache.get(key)
  if (hit && hit.stamp === stamp) return hit.value

  const row = await prisma.categorySchema.findFirst({
    where: { channel: 'AMAZON', marketplace: mk, productType: pt, isActive: true },
    orderBy: { fetchedAt: 'desc' },
    select: { schemaDefinition: true, fetchedAt: true, schemaVersion: true },
  })
  if (!row) {
    // An account-specific provider read is a cache-miss fallback, never a page-load bypass.
    if (accountId && !cachedSchemasOnly()) return (await import('../../categories/seller-schema.service.js')).amazonSellerSpec(accountId, mk, pt)
    return remember(key, stamp, {
      channel: 'AMAZON', marketplace: mk, category: pt, fields: [], groups: [],
      fetchedAt: null, schemaVersion: null, coverage: {}, unrecognised: [], absent: true,
    })
  }
  const spec = amazonSpecFromDefinition({
    marketplace: mk, productType: pt, schemaDefinition: row.schemaDefinition,
    fetchedAt: row.fetchedAt, schemaVersion: row.schemaVersion,
  })
  return remember(key, stamp, spec)
}

/**
 * English labels for an Amazon product type, keyed by NORMALISED spec key, read from a cached
 * ENGLISH-marketplace schema through the same walker — so a compound leaf or a slot base gets
 * Amazon's own English wording, not a humanised key. Empty when no English schema is cached
 * (6 of 19 product types had one, measured 2026-09-02); the caller falls back to `humanizeKey`.
 */
export async function loadAmazonEnglishLabels(productType: string): Promise<Map<string, string>> {
  const pt = String(productType).toUpperCase()
  const out = new Map<string, string>()
  const rows = await prisma.categorySchema.findMany({
    where: { channel: 'AMAZON', marketplace: { in: ENGLISH_MARKETPLACES }, productType: pt, isActive: true },
    orderBy: { fetchedAt: 'desc' },
    select: { marketplace: true, schemaDefinition: true },
    take: 1,
  })
  for (const r of rows) {
    const spec = amazonSpecFromDefinition({ marketplace: r.marketplace, productType: pt, schemaDefinition: r.schemaDefinition })
    for (const f of spec.fields) {
      const k = normaliseKey(f.key)
      if (!out.has(k)) out.set(k, f.label)
    }
    for (const g of spec.groups) {
      const k = `group:${g.key}`
      if (!out.has(k) && g.channelLabel) out.set(k, g.channelLabel)
    }
  }
  return out
}

/** A separate contract per leaf. Missing metadata never borrows another category's aspects. */
export async function loadEbaySpec(marketplace: string, categoryIds: string[]): Promise<ChannelSpec> {
  const mk = String(marketplace).toUpperCase().replace(/^EBAY_/, '')
  const cats = [...new Set(categoryIds.map(String).map(c => c.trim()).filter(Boolean))]
  if (cats.length > 1) throw new Error('Load eBay categories separately to preserve each leaf contract')
  const category = cats[0] ?? '*'
  const [cached, schemaRows] = await Promise.all([
    cats.length ? prisma.categorySchema.findFirst({
      where: { channel: 'EBAY', marketplace: { in: [mk, `EBAY_${mk}`] }, productType: category, isActive: true },
      orderBy: [{ fetchedAt: 'desc' }, { id: 'asc' }],
      select: { schemaDefinition: true, fetchedAt: true, schemaVersion: true },
    }) : Promise.resolve(null),
    prisma.channelSchema.findMany({
      where: { channel: 'EBAY', OR: [{ marketplace: mk }, { marketplace: null }] },
      orderBy: { marketplace: { sort: 'desc', nulls: 'last' } },
      select: { fieldKey: true, label: true, maxLength: true, required: true, allowedValues: true, notes: true },
    }),
  ])
  const definition = cached?.schemaDefinition as { aspects?: EbayCachedAspect[]; conditions?: EbayCachedCondition[] } | null
  const rows = [...new Map(schemaRows.slice().reverse().map(r => [r.fieldKey, r])).values()] as EbayChannelSchemaRow[]
  const spec = ebaySpecFromCache({
    marketplace: mk, categoryId: category,
    aspects: Array.isArray(definition?.aspects) ? definition.aspects : [],
    conditions: Array.isArray(definition?.conditions) ? definition.conditions : [],
    channelSchemaRows: rows, fetchedAt: cached?.fetchedAt ?? null,
  })
  spec.schemaVersion = cached?.schemaVersion ?? null
  spec.absent = !cached || !Array.isArray(definition?.aspects)
  return spec
}

import { describe, expect, it } from 'vitest'
import { informationRegistry } from '@nexus/shared/shopify-information'
import type { ShopifyFieldDefinition, ShopifyStoreSchema } from '@nexus/shared/shopify-linked-products'
import { shopifyProductSpec } from './store.js'
import { masterDefaultRule } from '../mapping/master-default-rule.js'
import { sourceOwner } from '../mapping/source-definition-plan.js'
import { buildSheetColumns } from '../sheet-columns.service.js'
import { channelValuePatch } from '../channel-value-mutation.js'
import { validateChannelValue } from '../mapping/validate-channel-value.js'
import type { CatalogueField } from '../mapping/field-catalogue.service.js'
import { nativeListingValue } from '../../shopify/native-listing-value.js'

const def = (extra: Partial<ShopifyFieldDefinition> = {}): ShopifyFieldDefinition => ({ id: 'gid://shopify/MetafieldDefinition/1', name: 'Features',
  namespace: 'custom', key: 'features', ownerType: 'PRODUCT', type: 'list.metaobject_reference', description: null, validations: [], access: { admin: null, storefront: null }, ...extra })
const schema = (definitions: ShopifyFieldDefinition[]): ShopifyStoreSchema => ({ definitions, metaobjectDefinitions: [], types: [], locales: [], revision: 'r1' })
const keys = new Set(['name', 'description', 'brand', 'basePrice', 'costPrice', 'sku', 'countryOfOrigin', 'hsCode', 'weightValue', 'weightUnit', 'shopify_product_type', 'special_feature', 'status', 'inventory', 'barcode'])
const coordinate = { channel: 'SHOPIFY' as const, marketplace: 'GLOBAL', label: 'Shopify · GLOBAL', inMarket: false }

describe('Shopify information mapping contract', () => {
  it('covers the native registry and every live owner/namespace without guessing sources from names', () => {
    const live = schema([def(), def({ ownerType: 'PRODUCTVARIANT' }), def({ namespace: 'shopify', key: 'color-pattern', name: 'Colour' })])
    const spec = shopifyProductSpec(live, 'store-a')
    expect(spec.fields.map(f => f.attribute)).toEqual(informationRegistry(live).flatMap(f => f.id === 'inventory' ? ['availableQuantity', 'onHandQuantity'] : [f.id]))
    expect(new Set(spec.fields.map(f => f.key)).size).toBe(34)
    for (const f of spec.fields.filter(f => f.shopifyField?.definition)) {
      expect(masterDefaultRule(f, keys)).toBeNull()
      expect(sourceOwner(f)).toMatchObject({ kind: 'listing' })
      expect(f.editable).toBe(true)
      expect(f.readOnlyReason).toBeUndefined()
      expect(f.channelStore).toMatchObject({ kind: 'platformAttributes', path: ['metafields', f.shopifyField!.owner, f.shopifyField!.definition!.namespace, f.shopifyField!.definition!.key, f.shopifyField!.type] })
    }
  })
  it('keeps exact identities across renames and isolates stores, owners, namespaces and types', () => {
    const key = (d: ShopifyFieldDefinition, account = 'a') => shopifyProductSpec(schema([d]), account).fields.at(-1)!.key
    expect(key(def({ name: 'New name' }))).toBe(key(def()))
    expect(new Set([key(def()), key(def(), 'b'), key(def({ ownerType: 'PRODUCTVARIANT' })), key(def({ namespace: 'custom.other' })), key(def({ type: 'single_line_text_field' }))]).size).toBe(5)
    expect(() => shopifyProductSpec(schema([def()]))).toThrow('connected store identity')
  })
  it('maps native facts explicitly and keeps Shopify product type separate from category assignments', () => {
    const spec = shopifyProductSpec()
    const rule = (id: string) => masterDefaultRule(spec.fields.find(f => f.shopifyField?.id === id), keys)
    for (const [id, source] of Object.entries({ title: 'title', descriptionHtml: 'description', vendor: 'brand', price: 'basePrice', cost: 'costPrice', sku: 'sku', countryCodeOfOrigin: 'countryOfOrigin', harmonizedSystemCode: 'hsCode', productType: 'shopify_product_type' })) expect(rule(id)?.source).toBe(source)
    for (const id of ['inventory', 'barcode', 'status', 'salesChannels', 'package']) expect(rule(id)).toBeNull()
    expect(sourceOwner(spec.fields.find(f => f.key === 'productType')!)).toBeNull()
    expect(rule('weight')?.transforms?.[0]).toMatchObject({ type: 'expr', expr: expect.stringContaining('$weightUnit') })
  })
  it('projects every mapping destination once, with native labels and protected typed writes', () => {
    const spec = shopifyProductSpec(schema([def(), def({ namespace: 'custom-other' }), def({ namespace: 'custom_other' })]), 'a')
    const sheet = buildSheetColumns({ fields: [], specs: [{ coordinate, spec }], coordinates: [coordinate], scopeKind: 'channel' })
    expect(sheet.columns).toHaveLength(spec.fields.length)
    for (const f of spec.fields) {
      const c = sheet.columns.find(c => c.channels?.[coordinate.label]?.key === f.key)!
      expect(c, f.key).toBeDefined()
      expect(c.label).toBe(f.label)
      if (f.readOnlyReason) expect(c.editable).toBe(false)
    }
  })
  it('preserves explicit values, zeros and clears while migrating legacy storage on edit', () => {
    for (const [id, oldKey, value] of [['vendor', 'shopifyVendor', 'Store brand'], ['productType', 'shopifyProductType', 'Jackets'], ['compareAtPrice', 'shopifyCompareAtPrice', 0]] as const) {
      const f = shopifyProductSpec().fields.find(f => f.key === id)!
      const before = { platformAttributes: { [oldKey]: value, unrelated: 'keep' } }
      expect(nativeListingValue(before, id, 'Master')).toBe(value)
      const changed = { ...before, ...channelValuePatch(before, f.channelStore, [f.key], 'SET', value) }
      expect(nativeListingValue(changed, id, 'Master')).toBe(value)
      expect((changed.platformAttributes as any)[oldKey]).toBeUndefined()
      const cleared = { ...before, ...channelValuePatch(before, f.channelStore, [f.key], 'CLEAR') }
      expect(nativeListingValue(cleared, id, 'Master')).toBeNull()
      const inherited = { ...before, ...channelValuePatch(before, f.channelStore, [f.key], 'INHERIT') }
      expect(nativeListingValue(inherited, id, 'Master')).toBe('Master')
      expect((inherited.platformAttributes as any).unrelated).toBe('keep')
    }
  })
  it('applies store definition types and constraints to mapping outputs', () => {
    const field = (d: ShopifyFieldDefinition) => {
      const f = shopifyProductSpec(schema([d]), 'a').fields.at(-1)!
      return { ...f, fieldKey: f.key, priority: 'optional', selectionOnly: false, shopifyField: f.shopifyField } as unknown as CatalogueField
    }
    expect(validateChannelValue(field(def()), ['Waterproof']).errors.join(' ')).toContain('Shopify reference')
    expect(validateChannelValue(field(def()), ['gid://shopify/Product/1']).errors.join(' ')).toContain('Metaobject')
    expect(validateChannelValue(field(def({ type: 'number_integer', validations: [{ name: 'min', value: '0' }] })), -1).errors).not.toEqual([])
    expect(validateChannelValue(field(def({ type: 'color' })), 'Giallo').errors).not.toEqual([])
    expect(validateChannelValue(field(def({ type: 'boolean' })), false).errors).toEqual([])
    expect(validateChannelValue(field(def({ type: 'number_integer' })), 0).errors).toEqual([])
    expect(validateChannelValue(field(def({ type: 'list.single_line_text_field', validations: [{ name: 'list.max', value: '1' }] })), ['a', 'b']).errors).not.toEqual([])
  })
})

import { beforeEach, describe, expect, it, vi } from 'vitest'
import { withWorkspace } from '../../../lib/workspace-context.js'
const mocks = vi.hoisted(() => ({ admin: vi.fn(), read: vi.fn(), invalidateConstraints: vi.fn() }))
vi.mock('../../shopify/admin-client.js', () => ({ shopifyAdmin: mocks.admin }))
vi.mock('../../shopify/linked-products-gateway.js', () => ({ readLinkedStoreSchema: mocks.read, invalidateShopifyDefinitionConstraints: mocks.invalidateConstraints }))
import { invalidateShopifyMappingSchema, readShopifyMappingSchema, loadShopifyProductSpec } from './shopify.js'
const schema = (revision: string) => ({ revision, definitions: [], metaobjectDefinitions: [], types: [], locales: [] })
const scoped = <T>(id: string, work: () => T) => withWorkspace({ workspaceId: id, actorUserId: null, membershipId: null, roleKeys: [] }, work)
beforeEach(() => { vi.clearAllMocks(); for (const id of ['a', 'b']) invalidateShopifyMappingSchema(id); mocks.admin.mockImplementation(async id => ({ graphql: id })); mocks.read.mockImplementation(async id => schema(id)) })
describe('Shopify mapping schema lifecycle', () => {
  it('keeps the editable listing SKU separate from the common sheet identity band', async () => {
    const spec = await loadShopifyProductSpec('a')
    const sku = spec.fields.find(field => field.shopifyField?.id === 'sku')!
    expect(sku).toMatchObject({ key: 'listing_sku', editable: true, defaultRule: { source: 'sku' }, channelStore: { kind: 'platformAttributes', path: ['sku'] } })
    expect(sku.masterKey).toBeUndefined()
  })
  it('shares concurrent reads only in the same workspace and store', async () => {
    const [a, again, b] = await Promise.all([readShopifyMappingSchema('a'), readShopifyMappingSchema('a'), readShopifyMappingSchema('b')])
    expect(a).toBe(again); expect(b.revision).toBe('b'); expect(mocks.read).toHaveBeenCalledTimes(2)
    await scoped('profile-a', () => readShopifyMappingSchema('a'))
    await scoped('profile-b', () => readShopifyMappingSchema('a'))
    expect(mocks.read).toHaveBeenCalledTimes(4)
  })
  it('invalidates on a schema event and does not let an older read replace the fresh result', async () => {
    let finish!: (value: ReturnType<typeof schema>) => void
    mocks.read.mockImplementationOnce(() => new Promise(resolve => { finish = resolve }))
    const old = readShopifyMappingSchema('a'); await Promise.resolve(); await Promise.resolve()
    invalidateShopifyMappingSchema('a')
    mocks.read.mockResolvedValue(schema('new'))
    expect((await readShopifyMappingSchema('a')).revision).toBe('new')
    finish(schema('old')); await old
    expect((await readShopifyMappingSchema('a')).revision).toBe('new')
  })
  it('propagates errors and recovers instead of caching an empty catalogue', async () => {
    mocks.read.mockRejectedValueOnce(new Error('Shopify unavailable'))
    await expect(loadShopifyProductSpec('a')).rejects.toThrow('Shopify unavailable')
    expect((await loadShopifyProductSpec('a')).fields.length).toBe(31)
    expect(mocks.read).toHaveBeenCalledTimes(2)
  })
})

import { cachedSchemasOnly } from '../cached-schema-context.js'
import { WorkspaceCache } from '../../../lib/workspace-cache.js'
import { shopifyAdmin } from '../../shopify/admin-client.js'
import { readLinkedStoreSchema, invalidateShopifyDefinitionConstraints } from '../../shopify/linked-products-gateway.js'
import { shopifyProductSpec } from './store.js'
import type { ShopifyStoreSchema } from '@nexus/shared/shopify-linked-products'

const schemas = new WorkspaceCache<string, { expires: number; pending: Promise<ShopifyStoreSchema>; value?: ShopifyStoreSchema }>()
export function invalidateShopifyMappingSchema(accountId: string) { schemas.delete(accountId); invalidateShopifyDefinitionConstraints() }

/** Workspace/store isolation and single-flight reads. Failures never become an empty schema. */
export function readShopifyMappingSchema(accountId: string, fresh = false): Promise<ShopifyStoreSchema> {
  const cached = schemas.get(accountId)
  if (cachedSchemasOnly()) {
    if (cached?.value) return Promise.resolve(cached.value)
    throw new Error('Shopify requirements are not cached for this account.')
  }
  if (!fresh && cached && cached.expires > Date.now()) return cached.pending
  const entry: { expires: number; pending: Promise<ShopifyStoreSchema>; value?: ShopifyStoreSchema } = { expires: Date.now() + 30_000, pending: Promise.resolve(null as unknown as ShopifyStoreSchema) }
  entry.pending = shopifyAdmin(accountId).then(({ graphql }) => readLinkedStoreSchema(graphql)).then(value => { entry.value = value; return value }).catch(error => {
    if (schemas.get(accountId) === entry) schemas.delete(accountId)
    throw error
  })
  schemas.set(accountId, entry)
  return entry.pending
}

export async function loadShopifyProductSpec(accountId?: string | null, locale?: string) {
  return shopifyProductSpec(accountId ? await readShopifyMappingSchema(accountId) : null, accountId, locale)
}

import { normalizeLanguage } from '../content-language.js'
import { informationRegistry, nativeTranslationKeys, shopifyMappingFieldKey } from '@nexus/shared/shopify-information'
import type { ShopifyStoreSchema } from '@nexus/shared/shopify-linked-products'
import type { ChannelFieldSpec, ChannelGroup, ChannelSpec, ChannelStore } from './types.js'

/** Store product information. Source references and scope are recorded in the audit. */
const groups: ChannelGroup[] = ['Content', 'Classification', 'Search', 'Offer', 'Shipping', 'Policies']
  .map((label, order) => ({ key: label.toLowerCase(), label, channelLabel: null, order }))
const pa = (...path: string[]): ChannelStore => ({ kind: 'platformAttributes', path })
const column = (column: string, followFlag?: string): ChannelStore => ({ kind: 'listingColumn', column, followFlag })
function field(key: string, label: string, group: string, extra: Partial<ChannelFieldSpec> = {}): ChannelFieldSpec {
  return { key, attribute: key, path: [], label, englishLabel: label, kind: 'text', shape: 'scalar',
    cardinality: { min: 0, max: 1 }, requirement: 'optional', requiredInParent: false,
    editable: true, hidden: false, variantEligible: false, group: groups.find(g => g.key === group)!,
    channelStore: pa(key), ...extra }
}
const titleStore = column('title', 'followMasterTitle')
const descriptionStore = column('description', 'followMasterDescription')

/** The information sheet and mapping catalogue consume the same native/live registry. */
export function shopifyProductSpec(schema: ShopifyStoreSchema | null = null, accountId?: string | null, locale?: string): ChannelSpec {
  if (schema && !accountId) throw new Error('A Shopify definition requires its connected store identity.')
  if (locale) locale = normalizeLanguage(locale)
  const primaryTag = schema?.locales.find(l => l.primary)?.locale
  const primaryLocale = primaryTag ? normalizeLanguage(primaryTag) : undefined
  const translationLocale = locale && locale !== 'und' && primaryLocale && locale !== primaryLocale ? locale : null
  if (translationLocale && !schema?.locales.some(l => normalizeLanguage(l.locale) === translationLocale)) throw new Error('This language is not enabled in the selected Shopify store.')
  const native: Record<string, Partial<ChannelFieldSpec>> = {
    title: { masterKey: 'name', requirement: 'required', channelStore: titleStore },
    descriptionHtml: { masterKey: 'description', channelStore: descriptionStore },
    vendor: { masterKey: 'brand', channelStore: { kind: 'platformAttributes', path: ['vendor'], legacyPaths: [['shopifyVendor']] } },
    productType: { masterKey: 'shopify_product_type', channelStore: { kind: 'platformAttributes', path: ['productType'], legacyPaths: [['shopifyProductType']] } },
    price: { masterKey: 'basePrice', channelStore: column('price', 'followMasterPrice'), validation: { minimum: 0 } },
    cost: { masterKey: 'costPrice', validation: { minimum: 0 } },
    sku: { defaultRule: { source: 'sku' } },
    countryCodeOfOrigin: { masterKey: 'countryOfOrigin', validation: { pattern: '^[A-Z]{2}$' } },
    harmonizedSystemCode: { masterKey: 'hsCode' },
    weight: { shape: 'measure', kind: 'number', unitOptions: ['g', 'kg', 'oz', 'lb'],
      defaultRule: { source: 'weightValue', transforms: [{ type: 'expr', expr: 'measure($weightValue, $weightUnit, "g|kg|oz|lb")' }] } },
    compareAtPrice: { validation: { minimum: 0 }, channelStore: { kind: 'platformAttributes', path: ['compareAtPrice'], legacyPaths: [['shopifyCompareAtPrice']] } },
    inventoryPolicy: { kind: 'select', mode: 'strict', options: schema?.native?.enums.inventoryPolicy?.map(choice => choice.name) ?? [] },
    category: { validation: { pattern: '^gid://shopify/TaxonomyCategory/[a-zA-Z0-9-]+$' } },
    handle: { validation: { pattern: '^[a-zA-Z0-9-]+$' } },
    tags: { validation: { uniqueItems: true }, maxLength: 255 },
  }
  const fields = informationRegistry(schema).flatMap(info => {
    const key = shopifyMappingFieldKey(info, accountId ?? '')
    const baseType = info.type.replace(/^list\./, '')
    const kind = ['number_integer', 'number_decimal', 'money'].includes(baseType) ? 'number'
      : baseType === 'boolean' ? 'boolean' : ['date', 'date_time'].includes(baseType) ? 'date'
      : ['multi_line_text_field', 'rich_text_field', 'json'].includes(baseType) ? 'longtext' : 'text'
    const group = { key: info.group.toLowerCase().replace(/ /g, '_'), label: info.group, channelLabel: null,
      order: ['General', 'Publishing', 'Pricing', 'Inventory', 'Shipping', 'SEO', 'Metafields', 'Category Metafields'].indexOf(info.group) }
    const entry = field(key, info.label, 'content', {
      attribute: info.id, kind, group, shopifyField: info,
      shape: info.cardinality, cardinality: { min: 0, max: info.cardinality === 'list' ? null : 1 },
      variantEligible: info.owner === 'PRODUCTVARIANT',
      channelStore: info.definition ? pa('metafields', info.owner, info.definition.namespace, info.definition.key, info.type)
        : pa(...info.id.split('.')),
      helpText: info.definition ? `${info.owner === 'PRODUCT' ? 'Product' : 'Variant'} · ${info.source}. ${info.definition.description ?? ''}`.trim()
        : [info.channelLabel !== info.label ? `Shopify: ${info.channelLabel}.` : '', info.reason].filter(Boolean).join(' ') || undefined,
      // Media and stock require a published Shopify resource; their native workspace
      // owns exact file and stocking-location identities after publication.
      readOnlyReason: info.reason ?? (info.id === 'media' ? 'Use the media workspace to manage product media.' : undefined),
      editable: !info.reason,
      ...(native[info.id] ?? {}),
    })
    if (translationLocale) {
      const translatable = info.definition ? ['single_line_text_field', 'multi_line_text_field', 'rich_text_field', 'json', 'url', 'link', 'list.single_line_text_field', 'list.url', 'list.link'].includes(info.type) : !!nativeTranslationKeys[info.id]
      const reason = info.reason ?? (!translatable ? 'Shopify shares this field across languages. Select the store’s primary language to edit its base value.'
        : !schema?.native?.scopes.includes('write_translations') ? 'This Shopify connection needs write_translations permission.' : undefined)
      entry.channelStore = pa('_shopifyInformationLocales', translationLocale, info.id)
      entry.readOnlyReason = reason
      entry.editable = !reason
      entry.shopifyField = { ...info, reason }
      entry.helpText = `${translationLocale} translation. Clearing restores the primary-language value. Shopify translatability is verified against the created resource before synchronization.`
    }
    return info.id === 'inventory'
      ? [{ key: 'availableQuantity', label: 'Available quantity' }, { key: 'onHandQuantity', label: 'On hand quantity' }]
        .map(quantity => ({ ...entry, ...quantity, englishLabel: quantity.label, attribute: quantity.key, kind: 'number' as const, channelStore: pa(quantity.key), editable: false,
          readOnlyReason: 'This draft has no Shopify inventory item or stocking locations. Publish it, then edit inventory by location in Shopify Information.' }))
      : [entry]
  })
  const result = spec('SHOPIFY', fields)
  result.groups = [...new Map(fields.map(f => [f.group!.key, f.group!])).values()]
  result.schemaVersion = schema?.revision ?? 'shopify-native-mapping-2026-09-10'
  // Shopify values have dedicated typed validation; JSON/reference records are not text.
  result.validationSchema = undefined
  return result
}

export { etsyProductSpec } from './etsy.js'

function spec(channel: 'SHOPIFY' | 'ETSY', fields: ChannelFieldSpec[]): ChannelSpec {
  const properties = Object.fromEntries(fields.map(f => {
    const scalar = { type: f.kind === 'number' ? 'number' : f.kind === 'boolean' ? 'boolean' : 'string',
      ...(f.options ? { enum: f.options } : {}), ...(f.maxLength ? { maxLength: f.maxLength } : {}),
      ...Object.fromEntries(Object.entries(f.validation ?? {}).filter(([key]) => key !== 'uniqueItems')) }
    return [f.attribute, f.shape === 'list' ? { type: 'array', items: scalar,
      ...(f.cardinality.max !== null ? { maxItems: f.cardinality.max } : {}),
      ...(f.validation?.uniqueItems ? { uniqueItems: true } : {}) } : scalar]
  }))
  return { channel, marketplace: 'GLOBAL', category: '*', fields,
    validationSchema: { type: 'object', properties, required: fields.filter(f => f.requirement === 'required').map(f => f.attribute) },
    groups: groups.filter(g => fields.some(f => f.group?.key === g.key)),
    fetchedAt: null, schemaVersion: 'product-information-2026-09-08',
    coverage: Object.fromEntries(fields.map(f => [f.attribute, [f.key]])), unrecognised: [], absent: false }
}

