import { translationMissing } from './content-resolver.js'
import type { Prisma } from '@prisma/client'
import type { ListingReadinessIssue, ListingReadinessPage, ListingReadinessRow } from '@nexus/shared/listing-readiness'
import prisma from '../../db.js'
import { resolveBatch, type ResolvedProduct } from './mapping/resolve-batch.service.js'
import { isPresent } from './resolve-channel-field.js'
import { marketLanguages } from './market-languages.js'

const PAGE_SIZE = 25
const identifier = (value: unknown, name: string) => {
  if (value === undefined || value === '') return undefined
  if (typeof value !== 'string' || !value.trim() || value.length > 200) throw new Error(`Invalid ${name}`)
  return value.trim()
}
export function readinessQuery(query: Record<string, unknown>) {
  const familyId = identifier(query.familyId, 'family'), jobId = identifier(query.job, 'import job')
  const list = (value: unknown, name: string) => {
    if (value === undefined || value === '') return undefined
    if (typeof value !== 'string') throw new Error(`Invalid ${name}`)
    // SKUs can themselves contain commas. New clients send a JSON list; a plain
    // string remains a single SKU for bookmarked links.
    let parsed: unknown
    try { parsed = name === 'SKUs' ? value.startsWith('[') ? JSON.parse(value) : [value] : value.split(',') } catch { throw new Error(`Invalid ${name}`) }
    if (!Array.isArray(parsed) || !parsed.length || parsed.length > 200 || parsed.some(v => typeof v !== 'string' || !v.trim() || v.length > 200)) throw new Error(`Choose 1–200 ${name}`)
    const values = [...new Set((parsed as string[]).map(v => v.trim()))]
    return values
  }
  const productIds = list(query.productIds, 'product IDs'), skus = list(query.skus, 'SKUs'), listingIds = list(query.listingIds, 'listing IDs')
  if ([familyId, jobId, productIds, skus, listingIds].filter(Boolean).length !== 1) throw new Error('Choose one product family, product selection, listing selection, SKU list or completed import')
  const accountId = identifier(query.accountId, 'account')
  const channel = identifier(query.channel, 'channel')?.toUpperCase()
  const marketplace = identifier(query.marketplace, 'marketplace')?.toUpperCase()
  if (channel && !['AMAZON', 'EBAY', 'SHOPIFY', 'ETSY'].includes(channel)) throw new Error('Select a supported channel')
  if (marketplace && marketplace !== 'GLOBAL' && !/^[A-Z]{2}$/.test(marketplace)) throw new Error('Select a valid marketplace')
  if (query.page !== undefined && (typeof query.page !== 'string' || !/^\d+$/.test(query.page))) throw new Error('Use a positive page number')
  const page = Number(query.page ?? 1)
  if (!Number.isSafeInteger(page) || page < 1 || page > 100_000) throw new Error('Use a positive page number')
  return { familyId, jobId, productIds, skus, listingIds, accountId, channel, marketplace, page }
}

export function preparationIssues(product: ResolvedProduct): ListingReadinessIssue[] {
  const issues: ListingReadinessIssue[] = []
  if (!Object.keys(product.cells).length) issues.push({ field: '', label: 'Attribute checks', kind: 'check', message: 'No attributes were evaluated for this listing. Review its category and schema.' })
  if (!product.readiness || product.readiness.schemaValidation !== 'evaluated') issues.push({ field: 'category', label: 'Category requirements', kind: 'schema', message: 'Category requirements could not be fully checked. Refresh the category schema in the channel mapping workspace.' })
  for (const cell of Object.values(product.cells)) {
    const identity = { field: cell.fieldKey, label: cell.label ?? cell.fieldKey }
    for (const message of cell.errors) issues.push({ ...identity, kind: cell.required && !isPresent(cell.value) ? 'missing' : 'invalid', message })
    if (cell.requestedLocale && translationMissing({ language: cell.effectiveLocale }, cell.requestedLocale)) issues.push({ ...identity, kind: 'translation', message: 'Complete and review the translation for this destination.' })
    for (const message of cell.warnings) issues.push({ ...identity, kind: 'warning', message })
  }
  // A future resolver-level block must never turn green merely because it has no cell error.
  if (product.readiness?.state === 'blocked' && !issues.some(i => i.kind !== 'warning')) issues.push({ field: '', label: 'Validation', kind: 'check', message: 'The mapping engine reports a blocking check. Review this listing in the editor.' })
  return [...new Map(issues.map(issue => [JSON.stringify([issue.field, issue.kind, issue.message]), issue])).values()]
}

/** One bounded listing page, grouped by exact account + market + alias. No channel writes. */
export async function listingReadiness(query: Record<string, unknown>, userId: string | null): Promise<ListingReadinessPage> {
  const input = readinessQuery(query)
  let skus = input.skus
  if (input.jobId) {
    const job = await prisma.bulkOperation.findFirst({ where: { id: input.jobId, userId }, select: { status: true, changes: true } })
    if (!job || (job.changes as { kind?: string } | null)?.kind !== 'catalog-transfer-v2') throw new Error('Import job not found')
    if (!['COMPLETED', 'PARTIAL', 'FAILED'].includes(job.status)) throw new Error('Wait for this import to finish saving before checking listing readiness')
    // Stable target keys contain only identity, avoiding heavy attribute snapshots. Saved
    // products include every destination affected by a shared fact, not only imported listings.
    const records = await prisma.importJobRow.findMany({ where: { jobId: input.jobId, status: 'SUCCESS' }, select: { targetId: true }, take: 50_001 })
    if (records.length > 50_000) throw new Error('This import is too large for one selection. Choose a product family instead.')
    skus = [...new Set(records.map(row => {
      const key: unknown = JSON.parse(row.targetId ?? 'null')
      if (!Array.isArray(key) || !['Products', 'Listings'].includes(key[0]) || typeof key[1] !== 'string') throw new Error('The saved import has an invalid product identity')
      return key[1] as string
    }))]
  }
  const products: Prisma.ProductWhereInput = { deletedAt: null,
    ...(input.productIds ? { id: { in: input.productIds } } : input.listingIds ? { channelListings: { some: { id: { in: input.listingIds } } } } : skus ? { sku: { in: skus } }
      : { OR: [{ familyId: input.familyId }, { familyId: null, parent: { familyId: input.familyId } }] }),
  }
  const destination: Prisma.ChannelListingWhereInput = { channel: input.channel ?? { in: ['AMAZON', 'EBAY', 'SHOPIFY', 'ETSY'] },
    ...(input.listingIds ? { id: { in: input.listingIds } } : {}),
    ...(input.accountId ? { channelConnectionId: input.accountId } : {}), ...(input.marketplace ? { marketplace: input.marketplace } : {}) }
  const where = { ...destination, product: products }
  const without = { AND: [products, { channelListings: { none: destination } }] }
  const [productCount, total, unlistedCount, unlisted, listings, markets, selectedListingCount] = await Promise.all([
    prisma.product.count({ where: products }), prisma.channelListing.count({ where }),
    prisma.product.count({ where: without }),
    prisma.product.findMany({ where: without, select: { id: true, sku: true }, orderBy: { sku: 'asc' }, take: 10 }),
    prisma.channelListing.findMany({ where, orderBy: [{ channel: 'asc' }, { marketplace: 'asc' }, { channelConnectionId: 'asc' }, { id: 'asc' }], skip: (input.page - 1) * PAGE_SIZE, take: PAGE_SIZE,
      select: { id: true, productId: true, channel: true, marketplace: true, channelConnectionId: true, aliasKey: true, version: true,
        listingStatus: true, lastSyncedAt: true, product: { select: { id: true, sku: true, name: true, version: true } },
        channelConnection: { select: { channelType: true, isActive: true, marketplace: true, accountLabel: true, displayName: true } } } }),
    prisma.marketplace.findMany({ where: { isActive: true }, select: { channel: true, code: true, language: true, languages: true } }),
    input.listingIds ? prisma.channelListing.count({ where: { id: { in: input.listingIds }, product: { deletedAt: null } } }) : Promise.resolve(0),
  ])
  const rows: ListingReadinessRow[] = listings.map(listing => {
    const { channelConnection: account, product } = listing
    const issues: ListingReadinessIssue[] = []
    if (!account?.isActive || account.channelType !== listing.channel || account.marketplace && !['GLOBAL', listing.marketplace].includes(account.marketplace)) issues.push({ field: '', label: 'Seller account', kind: 'account', message: 'Assign an active seller account that supports this channel and marketplace.' })
    if (!markets.some(m => m.channel === listing.channel && m.code === listing.marketplace)) issues.push({ field: '', label: 'Marketplace', kind: 'account', message: 'This marketplace is not active for the selected channel.' })
    const params = new URLSearchParams({ scope: listing.channel, market: listing.marketplace, listing: listing.id })
    if (listing.channelConnectionId) params.set('account', listing.channelConnectionId)
    return { id: listing.id, productId: product.id, sku: product.sku, name: product.name, channel: listing.channel,
      marketplace: listing.marketplace, accountId: listing.channelConnectionId, accountName: account?.accountLabel || account?.displayName || 'Unassigned account',
      aliasKey: listing.aliasKey, locale: markets.some(m => m.channel === listing.channel && m.code === listing.marketplace) ? marketLanguages(listing.channel, listing.marketplace, markets)[0] : '', category: null, state: 'unavailable', issues, schema: null,
      savedStatus: listing.listingStatus, lastSyncedAt: listing.lastSyncedAt?.toISOString() ?? null,
      editorHref: `/products/${encodeURIComponent(product.id)}/edit/studio?${params}` }
  })
  const groups = new Map<string, ListingReadinessRow[]>()
  for (const row of rows.filter(r => !r.issues.length)) {
    const key = JSON.stringify([row.channel, row.marketplace, row.accountId, row.aliasKey])
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key)!.push(row)
  }
  // At most three destination resolutions concurrently; schema/template work is shared per group.
  const batches = [...groups.values()]
  for (let offset = 0; offset < batches.length; offset += 3) await Promise.all(batches.slice(offset, offset + 3).map(async group => {
    try {
      const first = group[0]
      const resolved = await resolveBatch({ channel: first.channel, marketplace: first.marketplace, channelConnectionId: first.accountId,
        aliasKey: first.aliasKey, productIds: group.map(r => r.productId), includeCatalogue: false })
      const byProduct = new Map(resolved.products.map(p => [p.productId, p]))
      for (const row of group) {
        const product = byProduct.get(row.productId)
        if (!product) { row.issues.push({ field: '', label: 'Product', kind: 'check', message: 'This product could not be resolved. Refresh the check.' }); continue }
        row.locale = resolved.locale; row.category = product.category.channelCategoryId
        row.schema = product.validationContext?.schema ?? null
        row.issues = preparationIssues(product)
        row.state = row.issues.some(i => ['schema', 'check'].includes(i.kind)) ? 'unavailable' : row.issues.some(i => i.kind !== 'warning') ? 'needs-attention' : 'checks-passed'
      }
    } catch {
      // A failed destination cannot hide results from another account or masquerade as ready.
      for (const row of group) row.issues.push({ field: '', label: 'Validation', kind: 'check', message: 'The checks for this destination could not finish. Retry; if this continues, open its channel mapping workspace to check the schema.' })
    }
  }))
  if (listings.length) {
    const latest = await prisma.channelListing.findMany({ where: { id: { in: listings.map(l => l.id) } }, select: { id: true, version: true, product: { select: { version: true } } } })
    const versions = new Map(latest.map(l => [l.id, l]))
    for (const [index, row] of rows.entries()) {
      const current = versions.get(row.id), original = listings[index]
      if (!current || current.version !== original.version || current.product.version !== original.product.version) {
        row.state = 'unavailable'; row.issues.push({ field: '', label: 'Changed during check', kind: 'check', message: 'This product or listing changed while it was being checked. Refresh to check the saved values.' })
      }
    }
  }
  return { computedAt: new Date().toISOString(), page: input.page, pageSize: PAGE_SIZE, total, productCount,
    missingSelectionCount: Math.max(0, input.listingIds ? input.listingIds.length - selectedListingCount : (input.productIds?.length ?? skus?.length ?? productCount) - productCount),
    withoutListing: { total: unlistedCount, sample: unlisted }, rows }
}

'use client'

import { useEffect, useState } from 'react'
import Link from '@/lib/workspaces/Link'
import type { ListingReadinessPage, ListingReadinessRow } from '@nexus/shared/listing-readiness'
import { PageHeader } from '@/design-system/patterns/PageHeader'
import { Button, Textarea } from '@/design-system/primitives'
import { Banner, Card, Disclosure, Field, Listbox, MetricStrip, Pagination } from '@/design-system/components'
import type { TransferOptions } from '../catalog-transfer/sourceMapping'
import { transferApi } from '../catalog-transfer/transferApi'
import { channelName, languageName } from '../catalog-transfer/workbookSelection'
import styles from './readiness.module.css'

type Selection = { familyId?: string; productIds?: string; listingIds?: string; job?: string; skus?: string }
type Request = Selection & { accountId?: string; marketplace?: string; page: string }
const stateLabel = { 'needs-attention': 'Needs attention', 'checks-passed': 'Local checks passed', unavailable: 'Checks incomplete' }
const issueLabel = { missing: 'Missing fact', invalid: 'Invalid value', translation: 'Translation needed', schema: 'Requirements unavailable', account: 'Destination setup', check: 'Check incomplete', warning: 'Review warning' }
const regionNames = new Intl.DisplayNames(['en'], { type: 'region' })

export default function ListingReadiness() {
  const [options, setOptions] = useState<TransferOptions | null>(null), [optionsError, setOptionsError] = useState(''), [optionsAttempt, setOptionsAttempt] = useState(0)
  const [selection, setSelection] = useState<Selection>({}), [selectionMode, setSelectionMode] = useState('family')
  const [accountId, setAccountId] = useState(''), [marketplace, setMarketplace] = useState('')
  const [request, setRequest] = useState<Request | null>(null), [result, setResult] = useState<ListingReadinessPage | null>(null)
  const [error, setError] = useState(''), [loading, setLoading] = useState(false)
  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const initial: Selection = Object.fromEntries(['familyId', 'productIds', 'listingIds', 'job', 'skus'].filter(key => params.has(key)).map(key => [key, params.get(key)!]))
    if (Object.keys(initial).length) {
      let readableSkus = initial.skus
      try { const parsed: unknown = JSON.parse(initial.skus ?? 'null'); if (Array.isArray(parsed) && parsed.every(v => typeof v === 'string')) readableSkus = parsed.join('\n') } catch { /* Single-SKU bookmark. */ }
      setSelection({ ...initial, ...(readableSkus !== undefined ? { skus: readableSkus } : {}) }); setSelectionMode(initial.job || initial.productIds || initial.listingIds ? 'selection' : initial.skus ? 'skus' : 'family')
      setAccountId(params.get('accountId') ?? ''); setMarketplace(params.get('marketplace') ?? '')
      setRequest({ ...initial, accountId: params.get('accountId') ?? undefined, marketplace: params.get('marketplace') ?? undefined, page: params.get('page') ?? '1' })
    }
  }, [])
  useEffect(() => {
    const abort = new AbortController(); setOptionsError('')
    void transferApi<TransferOptions>('catalog-transfer/readiness/options', undefined, abort.signal).then(value => { if (!abort.signal.aborted) setOptions(value) })
      .catch(e => { if (!abort.signal.aborted) setOptionsError(e.message) })
    return () => abort.abort()
  }, [optionsAttempt])
  useEffect(() => {
    if (!request) return
    const abort = new AbortController(); setLoading(true); setResult(null); setError('')
    const params = new URLSearchParams(Object.entries(request).filter((entry): entry is [string, string] => !!entry[1]))
    window.history.replaceState(null, '', `${window.location.pathname}?${params}`)
    void transferApi<ListingReadinessPage>(`catalog-transfer/readiness?${params}`, undefined, abort.signal)
      .then(value => { if (!abort.signal.aborted) setResult(value) })
      .catch(e => { if (!abort.signal.aborted) setError(e.message) })
      .finally(() => { if (!abort.signal.aborted) setLoading(false) })
    return () => abort.abort()
  }, [request])
  const clearCheck = () => { setRequest(null); setResult(null); setError(''); setLoading(false) }
  const check = () => setRequest({ ...selection, ...(selection.skus ? { skus: JSON.stringify(selection.skus.split(/\r?\n/).map(s => s.trim()).filter(Boolean)) } : {}), accountId: accountId || undefined, marketplace: marketplace || undefined, page: '1' })
  const chosenAccount = options?.accounts.find(a => a.id === accountId)
  const markets = [...new Map((options?.markets ?? []).filter(m => ['AMAZON', 'EBAY', 'SHOPIFY', 'ETSY'].includes(m.channel) && (!chosenAccount || m.channel === chosenAccount.channelType && (!chosenAccount.marketplace || chosenAccount.marketplace === 'GLOBAL' || chosenAccount.marketplace === m.code))).map(m => [m.code, m])).values()]
  const groups = new Map<string, ListingReadinessRow[]>()
  for (const row of result?.rows ?? []) {
    const key = JSON.stringify([row.channel, row.marketplace, row.accountId])
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key)!.push(row)
  }
  return <div className={styles.workspace}>
    <PageHeader eyebrow="Products" title="Listing readiness" subtitle="Find what needs attention for each seller account and marketplace." actions={<>
      <Button asChild><Link href="/products/catalog-transfer">Import &amp; export</Link></Button>
      <Button asChild><Link href="/products">Back to products</Link></Button>
    </>} />
    <Card header={<h2>Choose products to check</h2>} description="Checks saved Amazon and eBay listings, including drafts. Shared facts are reused; each destination keeps its own category and language.">
      <form className={styles.stack} onSubmit={e => { e.preventDefault(); check() }}>
        {optionsError && <Banner tone="danger" action={<Button onClick={() => setOptionsAttempt(n => n + 1)}>Retry options</Button>}>{optionsError}</Banner>}
        <div className={styles.fields}>
          <Field label="Products"><Listbox value={selectionMode} onChange={mode => { setSelectionMode(mode); setSelection({}); clearCheck() }} options={[
            ...(selectionMode === 'selection' ? [{ value: 'selection', label: selection.job ? 'Products saved by this import' : selection.listingIds ? 'Selected listings' : 'Selected products' }] : []),
            { value: 'family', label: 'Product family' }, { value: 'skus', label: 'Specific SKUs' },
          ]} width="100%" /></Field>
          <Field label="Seller account"><Listbox value={accountId} options={[{ value: '', label: 'All accounts' }, ...(options?.accounts ?? []).map(a => ({ value: a.id, label: a.displayName ?? a.id }))]} onChange={id => { setAccountId(id); setMarketplace(''); clearCheck() }} disabled={!options} width="100%" /></Field>
          <Field label="Marketplace"><Listbox value={marketplace} options={[{ value: '', label: 'All marketplaces' }, ...markets.map(m => ({ value: m.code, label: `${regionNames.of(m.code === 'UK' ? 'GB' : m.code) ?? m.code} · ${m.code}` }))]} onChange={value => { setMarketplace(value); clearCheck() }} disabled={!options} width="100%" /></Field>
        </div>
        {selectionMode === 'family' && <Field label="Product family" required><Listbox options={(options?.families ?? []).map(f => ({ value: f.id, label: f.label }))} value={selection.familyId ?? ''} onChange={familyId => { setSelection({ familyId }); clearCheck() }} disabled={!options} width="100%" /></Field>}
        {selectionMode === 'skus' && <Field label="SKUs" required hint="Up to 200 SKUs, one per line."><Textarea rows={3} value={selection.skus ?? ''} onChange={e => { setSelection({ skus: e.target.value }); clearCheck() }} /></Field>}
        {selectionMode === 'selection' && <p>{selection.job ? 'Checks the products successfully saved by this import across their existing destinations. Refused and excluded records remain in the import review.' : selection.listingIds ? `${selection.listingIds.split(',').length} selected ${selection.listingIds.split(',').length === 1 ? 'listing' : 'listings'}. Each seller account, marketplace and listing alias is preserved.` : `${selection.productIds?.split(',').length ?? 0} selected products. Each selected parent and variant is checked only if included in the selection.`}</p>}
        <div><Button variant="primary" type="submit" disabled={loading || !Object.values(selection).some(v => v?.trim())}>{loading ? 'Checking listings…' : 'Check listings'}</Button></div>
      </form>
    </Card>
    {loading && <p role="status">Resolving current values, category requirements and translations…</p>}
    {error && <Banner tone="danger" title="Readiness could not be checked" action={<Button onClick={check}>Retry check</Button>}>{error}</Banner>}
    {result && <>
      <div className={styles.actions}><p role="status">{result.productCount.toLocaleString()} {result.productCount === 1 ? 'product' : 'products'} · {result.total.toLocaleString()} matching {result.total === 1 ? 'listing' : 'listings'}. Checked {new Date(result.computedAt).toLocaleString()}.</p><Button onClick={() => setRequest(r => r && { ...r })}>Refresh checks</Button></div>
      {!!result.missingSelectionCount && <Banner tone="warning">{result.missingSelectionCount} selected {selection.listingIds ? 'listings' : 'products'} are missing or archived and could not be checked.</Banner>}
      {!!result.withoutListing.total && <Banner tone="warning" title={`${result.withoutListing.total} products have no matching listing`}>
        Open the product to choose its destination and create a listing draft.
        <div className={styles.links}>{result.withoutListing.sample.map(p => <Button key={p.id} asChild variant="link" size="sm"><Link href={`/products/${encodeURIComponent(p.id)}/edit/studio`}>{p.sku}</Link></Button>)}</div>
        {result.withoutListing.total > result.withoutListing.sample.length && <p>Showing the first {result.withoutListing.sample.length}. Narrow the product selection to find the others.</p>}
      </Banner>}
      {!!result.rows.length && <>
        <MetricStrip metrics={[
          { label: 'Listings on this page', value: result.rows.length },
          { label: 'Need attention', value: result.rows.filter(r => r.state === 'needs-attention').length },
          { label: 'Checks incomplete', value: result.rows.filter(r => r.state === 'unavailable').length },
          { label: 'Local checks passed', value: result.rows.filter(r => r.state === 'checks-passed').length },
        ]} />
        <Banner title="Prepare, validate with the channel, then publish">These are local attribute checks against cached category requirements. Review pricing, stock, policies and live channel validation in the listing editor before submitting. Channel acceptance and live availability must be confirmed there.</Banner>
        {[...groups.entries()].map(([key, rows]) => <Card key={key} header={<h2>{channelName(rows[0].channel)} · {rows[0].marketplace}</h2>} description={`${rows[0].accountName}${rows[0].accountId ? ` · ${rows[0].accountId.slice(-6)}` : ''} · ${rows.length} ${rows.length === 1 ? 'listing' : 'listings'} on this page`}>
          <div className={styles.stack}>{rows.map(row => <Disclosure key={row.id} summary={`${row.sku} · ${row.aliasKey || 'Primary listing'} · ${stateLabel[row.state]}${row.issues.length ? ` · ${row.issues.length} issues` : ''}`}>
            <div className={styles.stack}>
              <p>{row.name} · {languageName(row.locale)} · Category: {row.category ?? 'Not resolved'}</p>
              <div className={styles.actions}><Button asChild variant="primary" size="sm"><Link href={row.editorHref}>Review {row.sku} listing</Link></Button></div>
              {!!row.issues.length && <ul className={styles.issues}>{row.issues.map((issue, index) => <li key={index}><strong>{issue.label} · {issueLabel[issue.kind]}</strong><p>{issue.message}</p></li>)}</ul>}
              <Disclosure summary="Check details"><p>Schema: {row.schema?.version ?? 'Version unavailable'} · Retrieved {row.schema?.fetchedAt ? new Date(row.schema.fetchedAt).toLocaleString() : 'at an unknown date'}.</p><p>Saved listing status: {row.savedStatus}. Last sync: {row.lastSyncedAt ? new Date(row.lastSyncedAt).toLocaleString() : 'not recorded'}. This check did not contact the marketplace.</p></Disclosure>
            </div>
          </Disclosure>)}</div>
        </Card>)}
      </>}
      {!result.rows.length && <Card padded><p>{result.total ? 'This page no longer contains listings. Return to the first page to refresh the selection.' : 'No existing listings matched this selection.'}</p>{result.total > 0 && <Button onClick={() => setRequest(r => r && { ...r, page: '1' })}>First page</Button>}</Card>}
      {result.total > result.pageSize && <div className={styles.actions}><p>Page {result.page} of {Math.ceil(result.total / result.pageSize)}. Counts above describe this page.</p><Pagination page={result.page} pageCount={Math.ceil(result.total / result.pageSize)} onPage={page => setRequest(r => r && { ...r, page: String(page) })} /></div>}
    </>}
  </div>
}

