'use client'

/**
 * The inventory editor — the modal behind the Available cell.
 *
 * One AG Grid for both cases (a family's variations, or a single product as a one-row family),
 * edited like a spreadsheet, applied as ONE audited batch: every change the operator has typed
 * sits in `pending` until Apply, with one reason and one note for the batch. The server derives
 * each delta from a fresh read and answers per change; a refused cell stays pending and marked,
 * a confirmed one clears. Nothing here writes a number the server has not confirmed.
 */
import { useCallback, useEffect, useMemo, useState } from 'react'
import { Redo2, Search, Undo2 } from 'lucide-react'

import { Modal, Combobox, Listbox, MultiSelect } from '@/design-system/components'
import { GridToolbar } from '@/design-system/patterns'
import { Input, Button, Pill } from '@/design-system/primitives'
import { GridFooterSpacer, GridFooterStrip, GridPanel, type GridApi } from '@/design-system/grid'
import type { ProductRow } from '../_types'

import { useInventoryEditor } from './useInventoryEditor'
import type { DensityMode } from './density'
import { InventoryGrid, OPTIONAL_COLUMN_KINDS, OPTIONAL_COLUMN_LABELS, type OptionalColumnKind } from './InventoryGrid'
import { changesOf, DEFAULT_REASON, editorModeForRow, pendingKey, REASON_OPTIONS, withEdit, type MatrixRow } from './inventoryEditor.logic'
import styles from './styles.module.css'

/** Which optional columns the operator has hidden; remembered per browser. */
const COLUMNS_KEY = 'products-next:inventory-editor:hidden-columns'
const readHidden = (): OptionalColumnKind[] => {
  try {
    const raw = JSON.parse(localStorage.getItem(COLUMNS_KEY) ?? '[]')
    return Array.isArray(raw) ? raw.filter((k): k is OptionalColumnKind => (OPTIONAL_COLUMN_KINDS as readonly string[]).includes(k)) : []
  } catch { return [] }
}

export function InventoryEditorModal({ row, density, onClose }: { row: ProductRow | null; density: DensityMode; onClose: () => void }) {
  const open = row != null
  const single = row ? editorModeForRow(row) === 'list' : true
  const { loading, error, model, reload, applyBatch } = useInventoryEditor(row)

  const [pending, setPending] = useState<Map<string, number>>(new Map())
  const [failed, setFailed] = useState<Map<string, string>>(new Map())
  const [selected, setSelected] = useState<string[]>([])
  const [reason, setReason] = useState<string>(DEFAULT_REASON)
  const [notes, setNotes] = useState('')
  const [search, setSearch] = useState('')
  const [confirmDiscard, setConfirmDiscard] = useState(false)
  const [applying, setApplying] = useState(false)
  const [message, setMessage] = useState<{ text: string; tone: 'success' | 'danger' } | null>(null)
  const [history, setHistory] = useState({ undo: 0, redo: 0 })
  const [setLocation, setSetLocation] = useState<string>('')
  const [setValue, setSetValue] = useState('')
  const [gridApi, setGridApi] = useState<GridApi<never> | null>(null)
  const [hiddenKinds, setHiddenKinds] = useState<OptionalColumnKind[]>([])
  useEffect(() => { setHiddenKinds(readHidden()) }, [])
  const setVisibleKinds = useCallback((visible: string[]) => {
    const hidden = OPTIONAL_COLUMN_KINDS.filter((k) => !visible.includes(k))
    setHiddenKinds(hidden)
    try { localStorage.setItem(COLUMNS_KEY, JSON.stringify(hidden)) } catch { /* the choice just won't survive a reload */ }
  }, [])

  // A fresh product is a fresh session: nothing pending carries over.
  useEffect(() => {
    setPending(new Map()); setFailed(new Map()); setSelected([]); setReason(DEFAULT_REASON); setNotes('')
    setSearch(''); setConfirmDiscard(false); setMessage(null); setHistory({ undo: 0, redo: 0 }); setSetValue('')
  }, [row?.id])

  const editableLocations = useMemo(() => (model?.columns ?? []).filter((c) => c.editable), [model])
  useEffect(() => {
    if (!setLocation || !editableLocations.some((c) => c.locationId === setLocation)) setSetLocation(editableLocations[0]?.locationId ?? '')
  }, [editableLocations, setLocation])

  /** Every edit path — keystroke, fill, paste, undo, "Set selected" — lands here. */
  const onEdit = useCallback((r: MatrixRow, locationId: string, value: unknown) => {
    setPending((prev) => withEdit(prev, r, locationId, value))
    setFailed((prev) => {
      const key = pendingKey(r.productId, locationId)
      if (!prev.has(key)) return prev
      const next = new Map(prev); next.delete(key); return next
    })
    setMessage(null)
  }, [])

  const setSelectedTo = useCallback(() => {
    if (!model || !setLocation) return
    const n = Number(setValue.trim())
    if (!Number.isInteger(n) || n < 0) return
    setPending((prev) => {
      let next: Map<string, number> = new Map(prev)
      for (const id of selected) {
        const r = model.rows.find((x) => x.productId === id)
        if (r) next = withEdit(next, r, setLocation, n)
      }
      return next
    })
    setMessage(null)
  }, [model, selected, setLocation, setValue])

  const apply = useCallback(async () => {
    if (!pending.size || applying) return
    setApplying(true)
    setMessage(null)
    const res = await applyBatch({ reason, notes: notes.trim() || undefined, changes: changesOf(pending) })
    setApplying(false)
    if (!res.ok) { setMessage({ text: res.error, tone: 'danger' }); return }
    const refused = new Map<string, string>()
    let applied = 0
    for (const r of res.results) {
      if (r.ok) applied += 1
      else refused.set(pendingKey(r.productId, r.locationId), r.error ?? 'Refused')
    }
    setPending((prev) => {
      const next = new Map<string, number>()
      for (const [k, v] of prev) if (refused.has(k)) next.set(k, v)
      return next
    })
    setFailed(refused)
    setHistory({ undo: 0, redo: 0 })
    setMessage(
      refused.size
        ? { text: `${applied} applied · ${refused.size} refused — hover a red cell for why`, tone: 'danger' }
        : { text: `${applied} ${applied === 1 ? 'change' : 'changes'} applied`, tone: 'success' },
    )
  }, [pending, applying, applyBatch, reason, notes])

  /** Close asks first when there is unapplied work; the DS modal routes Esc and ✕ here too. */
  const requestClose = useCallback(() => {
    if (pending.size && !confirmDiscard) { setConfirmDiscard(true); return }
    onClose()
  }, [pending.size, confirmDiscard, onClose])

  const pendingCount = pending.size
  const rowCount = model?.rows.length ?? 0
  const subtitle = row
    ? [row.sku, single ? null : `${rowCount} ${rowCount === 1 ? 'variation' : 'variations'}`, model ? `${model.columns.length} ${model.columns.length === 1 ? 'location' : 'locations'}` : null].filter(Boolean).join(' · ')
    : undefined

  /** The card's footer strip — the page's pager row, carrying the batch's reason, notes and Apply. */
  const footerStrip = (
    <GridFooterStrip>
      {confirmDiscard ? (
        <>
          <span className={styles.ieDiscard}>Discard {pendingCount} unapplied {pendingCount === 1 ? 'change' : 'changes'}?</span>
          <GridFooterSpacer />
          <Button size="sm" variant="secondary" onClick={() => setConfirmDiscard(false)}>Keep editing</Button>
          <Button size="sm" variant="danger" onClick={onClose}>Discard</Button>
        </>
      ) : (
        <>
          <span className={styles.ieSetLabel}>Reason</span>
          <Combobox options={[...REASON_OPTIONS]} value={reason} onChange={setReason} placeholder="Select reason" className={styles.ieReason} />
          <Input fieldClassName={styles.ieNotes} placeholder="Notes (optional) — stored on every movement in this batch" value={notes} onChange={(e) => setNotes(e.target.value)} aria-label="Adjustment notes" />
          <GridFooterSpacer />
          {message && <span className={message.tone === 'danger' ? styles.ieMsgDanger : styles.ieMsgSuccess} role="status">{message.text}</span>}
          <Button size="sm" variant="secondary" onClick={requestClose}>{pendingCount ? 'Cancel' : 'Close'}</Button>
          <Button size="sm" variant="primary" disabled={!pendingCount || applying} onClick={() => void apply()}>
            {applying ? 'Applying…' : pendingCount ? `Apply ${pendingCount} ${pendingCount === 1 ? 'change' : 'changes'}` : 'Apply'}
          </Button>
        </>
      )}
    </GridFooterStrip>
  )

  return (
    <Modal open={open} onClose={requestClose} size="xxl" className={styles.ieModal} title={row ? row.name : 'Inventory'} subtitle={subtitle}>
      {loading && <div className={styles.invState}>Loading inventory…</div>}

      {!loading && error && (
        <div className={styles.invState}>
          <p>{error}</p>
          <Button type="button" variant="secondary" size="sm" onClick={() => void reload()}>Retry</Button>
        </div>
      )}

      {!loading && !error && model && (
        model.columns.length === 0 ? (
          <div className={styles.invState}>
            <p>No active locations yet.</p>
            <a href="/fulfillment/stock/locations" className={styles.invManageLink} target="_blank" rel="noopener noreferrer">Create a location →</a>
          </div>
        ) : (
          <>
            {/* The page's own grid card and toolbar: the editor is the products grid, in a modal. */}
            <GridPanel footer={footerStrip}>
              <GridToolbar
                count={
                  pendingCount
                    ? <Pill tone="warning" size="sm">{pendingCount} {pendingCount === 1 ? 'change' : 'changes'} pending</Pill>
                    : <Pill tone="neutral" size="sm">No changes</Pill>
                }
                right={
                  <>
                    <Button size="sm" variant="ghost" disabled={!history.undo} onClick={() => gridApi?.undoCellEditing()} title="Undo (⌘Z)"><Undo2 size={13} /> Undo</Button>
                    <Button size="sm" variant="ghost" disabled={!history.redo} onClick={() => gridApi?.redoCellEditing()} title="Redo (⌘⇧Z)"><Redo2 size={13} /> Redo</Button>
                    {selected.length > 0 && editableLocations.length > 0 && (
                      <span className={styles.ieSetSel}>
                        <span className={styles.ieSetLabel}>Set {selected.length} selected at</span>
                        <Listbox size="sm" width={150} options={editableLocations.map((c) => ({ value: c.locationId, label: c.locationCode }))} value={setLocation} onChange={setSetLocation} ariaLabel="Location" />
                        <span className={styles.ieSetLabel}>to</span>
                        <Input fieldClassName={styles.ieSetInput} inputMode="numeric" placeholder="0" value={setValue} onChange={(e) => setSetValue(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') setSelectedTo() }} aria-label="On hand value" />
                        <Button size="sm" onClick={setSelectedTo} disabled={setValue.trim() === ''}>Set</Button>
                      </span>
                    )}
                    <span className={styles.ieSetLabel}>Columns</span>
                    <MultiSelect
                      className={styles.ieColumns}
                      options={OPTIONAL_COLUMN_KINDS.map((k) => ({ value: k, label: OPTIONAL_COLUMN_LABELS[k] }))}
                      value={OPTIONAL_COLUMN_KINDS.filter((k) => !hiddenKinds.includes(k))}
                      onChange={setVisibleKinds}
                      placeholder="Columns"
                      ariaLabel="Columns"
                    />
                  </>
                }
              >
                {!single && (
                  <span className={styles.searchField}>
                    <Input leadingIcon={<Search size={13} style={{ color: 'var(--nds-text-3)' }} />} placeholder="Search variations…" value={search} onChange={(e) => setSearch(e.target.value)} aria-label="Search variations" style={{ width: '100%' }} />
                  </span>
                )}
              </GridToolbar>
              <InventoryGrid
                model={model}
                density={density}
                hiddenKinds={hiddenKinds}
                pending={pending}
                failed={failed}
                onEdit={onEdit}
                onSelectionChanged={setSelected}
                onReady={(api) => setGridApi(api as unknown as GridApi<never>)}
                onHistoryChanged={setHistory}
                quickFilterText={search}
                single={single}
              />
            </GridPanel>
            <p className={styles.ieHint}>Type into a cell to edit · <kbd>Enter</kbd> moves down · <kbd>Tab</kbd> moves right · <kbd>Esc</kbd> reverts · drag a cell's corner to fill · paste a column from a sheet · <kbd>⌘Z</kbd> undo</p>
          </>
        )
      )}
    </Modal>
  )
}

'use client'

/**
 * The inventory editor's grid — AG Grid, client-side, edited like a spreadsheet.
 *
 * Rows are the products being edited (a family's variations, or one product); columns are the
 * locations, each a group of three: On hand (the number you edit), Reserved (held by open
 * orders), Available (the difference — what the products grid shows). Pending edits live in the
 * modal (`pending`) and sit over the server's numbers through the value getters here; the grid
 * itself holds no stock figure it did not get from one or the other.
 *
 * Editing is AG's own: type into a focused cell or double-click, Enter commits and moves down,
 * Tab moves right, Esc reverts; a cell range with a fill handle; paste from a spreadsheet;
 * undo/redo. Every one of those paths ends in the same `valueSetter`, so a fill, a paste and a
 * keystroke are the same edit — and a locked column refuses all of them in the column
 * definition, not in a renderer.
 */
import { useCallback, useEffect, useMemo, useRef } from 'react'
import type { ColGroupDef, IRowNode, ValueGetterParams, ValueSetterParams } from '@/design-system/grid'

import { Pill } from '@/design-system/primitives'
import { DeltaChip, GridDensityProvider, IdentityCell, NexusGrid, SkuTag, numericColumn, type ColDef, type GridApi, type GridReadyEvent, type ICellRendererParams } from '@/design-system/grid'

import styles from './styles.module.css'
import { gridDensity, gridGeometry } from '@/design-system/tokens/grid'
import type { DensityMode } from './density'
import {
  availableOf, deltaOf, onHandOf, pendingKey, rowSyncStatus, rowTotalAvailable, stockLevelOf, totalsOf,
  type LevelCell, type MatrixModel, type MatrixRow, type PendingEdits,
} from './inventoryEditor.logic'

/** The pinned totals row. Same `cells` shape as a product row so one value getter serves both. */
interface TotalsRow { __total: true; productId: '__total'; sku: string; name: ''; thumbnailUrl: null; lowStockThreshold: number; cells: Record<string, LevelCell>; totalAvailable: number }
type GridRow = MatrixRow | TotalsRow
const isTotals = (d: GridRow | undefined): d is TotalsRow => !!d && (d as TotalsRow).__total === true

// Fits a 962px-tall window (the DS modal is 82vh) with the modal's header, toolbar, hint and footer.
const MAX_GRID_HEIGHT = 480
/** Header height per engine size tier — the engine's own numbers (NexusGrid HEADER_HEIGHT). */
/** The location strip above the header — a band, not a header row (engine CSS, IE.4). */
const STRIP_PX = gridGeometry.stripH
/** Identity column at the Compact thumbnail; wider tiers add the thumbnail's extra width. */
const IDENTITY_BASE_PX = gridGeometry.identityW

/** The columns an operator may hide from the Columns control; `onhand` and the identity never hide. */
export const OPTIONAL_COLUMN_KINDS = ['reserved', 'available', 'totalAvailable', 'sync'] as const
export type OptionalColumnKind = (typeof OPTIONAL_COLUMN_KINDS)[number]
export const OPTIONAL_COLUMN_LABELS: Record<OptionalColumnKind, string> = { reserved: 'Reserved', available: 'Available', totalAvailable: 'Total available', sync: 'Sync state' }

export interface InventoryGridProps {
  model: MatrixModel
  /** The page's density — rows, header and thumbnail follow it, so the editor IS the page's grid. */
  density: DensityMode
  /** Column kinds the operator has hidden (see OPTIONAL_COLUMN_KINDS). */
  hiddenKinds: readonly OptionalColumnKind[]
  pending: PendingEdits
  /** Cells the server refused on the last Apply, with its reason. */
  failed: ReadonlyMap<string, string>
  onEdit: (row: MatrixRow, locationId: string, value: unknown) => void
  onSelectionChanged: (productIds: string[]) => void
  onReady: (api: GridApi<GridRow>) => void
  onHistoryChanged: (h: { undo: number; redo: number }) => void
  quickFilterText: string
  single: boolean
}

/** The page's product cell, SKU first: the same classes the products grid draws its cell with. */
function RowIdentity({ data }: ICellRendererParams<GridRow>) {
  if (!data) return null
  if (isTotals(data)) return <span className={styles.ieTotalsLabel}>{data.sku}</span>
  return <IdentityCell image={data.thumbnailUrl} title={<SkuTag>{data.sku}</SkuTag>} sub={<span className={styles.ieName} title={data.name}>{data.name}</span>} />
}

function SyncCell({ data }: ICellRendererParams<GridRow>) {
  if (!data || isTotals(data)) return null
  const s = rowSyncStatus(data)
  if (!s) return null
  return <Pill tone={s === 'FAILED' ? 'danger' : s === 'PENDING' ? 'warning' : 'success'} size="sm">{s.toLowerCase()}</Pill>
}

export function InventoryGrid({ model, density, hiddenKinds, pending, failed, onEdit, onSelectionChanged, onReady, onHistoryChanged, quickFilterText, single }: InventoryGridProps) {
  // The value getters read these through refs so the column definitions stay STABLE — a new
  // column definition per keystroke would make AG rebuild its columns on every edit. The effect
  // below tells AG to re-read the cells when the pending set changes.
  const pendingRef = useRef(pending); pendingRef.current = pending
  const failedRef = useRef(failed); failedRef.current = failed
  const apiRef = useRef<GridApi<GridRow> | null>(null)

  const totals = useMemo<TotalsRow>(() => {
    const t = totalsOf(model, pending)
    return { __total: true, productId: '__total', sku: single ? 'Total' : 'Family total', name: '', thumbnailUrl: null, lowStockThreshold: 0, cells: t.cells, totalAvailable: t.totalAvailable }
  }, [model, pending, single])

  useEffect(() => {
    const api = apiRef.current
    if (!api || api.isDestroyed()) return
    api.setGridOption('pinnedBottomRowData', [totals])
    api.refreshCells({ force: true })
  }, [pending, failed, totals])

  /** Hidden kinds → column visibility, by colId prefix (`reserved:<loc>`, `totalAvailable`, `sync`). */
  const applyHidden = useCallback((api: GridApi<GridRow>) => {
    const state = api.getColumnState().map((s) => {
      const kind = s.colId.split(':')[0] as OptionalColumnKind
      return OPTIONAL_COLUMN_KINDS.includes(kind) ? { colId: s.colId, hide: hiddenKinds.includes(kind) } : { colId: s.colId }
    })
    api.applyColumnState({ state })
  }, [hiddenKinds])
  useEffect(() => {
    const api = apiRef.current
    if (api && !api.isDestroyed()) applyHidden(api)
  }, [applyHidden])

  const columnDefs = useMemo<(ColDef<GridRow> | ColGroupDef<GridRow>)[]>(() => {
    const identity: ColDef<GridRow> = {
      colId: 'product',
      headerName: single ? 'Product' : 'Variation',
      pinned: 'left',
      lockPosition: 'left',
      lockPinned: true,
      suppressMovable: true,
      // 34-character SKUs are normal in this catalogue; the thumbnail and the mono SKU need 320px
      // at the Compact thumbnail, and the thumbnail's extra width at the wider tiers.
      width: IDENTITY_BASE_PX + (gridDensity[density].thumb - gridDensity.compact.thumb),
      cellRenderer: RowIdentity,
      getQuickFilterText: (p) => `${p.data?.sku ?? ''} ${p.data?.name ?? ''}`,
      cellClass: 'nds-ag-cell',
      sortable: false,
    }
    const groups: ColGroupDef<GridRow>[] = model.columns.map((loc) => {
      const onHand: ColDef<GridRow> = {
        colId: `onhand:${loc.locationId}`,
        headerName: 'On hand',
        width: 88,
        editable: (p) => loc.editable && !p.node.rowPinned,
        cellEditor: 'agNumberCellEditor',
        cellEditorParams: { min: 0, precision: 0, step: 1, showStepperButtons: false },
        valueGetter: (p: ValueGetterParams<GridRow>) => (!p.data ? null : isTotals(p.data) ? (p.data.cells[loc.locationId]?.quantity ?? 0) : onHandOf(p.data, loc.locationId, pendingRef.current)),
        valueSetter: (p: ValueSetterParams<GridRow>) => {
          if (!p.data || isTotals(p.data)) return false
          const n = Number(String(p.newValue ?? '').trim())
          const valid = Number.isFinite(n) && Number.isInteger(n) && n >= 0
          if (valid) onEdit(p.data, loc.locationId, n)
          return valid
        },
        cellRenderer: (p: ICellRendererParams<GridRow>) => {
          if (!p.data) return null
          if (isTotals(p.data)) return <span>{p.value}</span>
          const delta = deltaOf(p.data, loc.locationId, pendingRef.current)
          const err = failedRef.current.get(pendingKey(p.data.productId, loc.locationId))
          return (
            <span className={styles.ieOnHand} title={err ?? undefined}>
              {p.value}
              <DeltaChip delta={delta} />
              {!loc.editable && <span className="nds-cell-lock-glyph" role="img" aria-label="Read-only">🔒</span>}
            </span>
          )
        },
        cellClassRules: {
          'nds-cell-is-pending': (p) => !!p.data && !isTotals(p.data) && deltaOf(p.data, loc.locationId, pendingRef.current) !== 0,
          'nds-cell-is-refused': (p) => !!p.data && !isTotals(p.data) && failedRef.current.has(pendingKey(p.data.productId, loc.locationId)),
          'nds-cell-is-locked': () => !loc.editable,
          'nds-cell-is-editable': (p) => loc.editable && !p.node.rowPinned,
        },
        ...numericColumn,
        sortable: false,
      }
      const reserved: ColDef<GridRow> = {
        colId: `reserved:${loc.locationId}`,
        headerName: 'Reserved',
        width: 84,
        valueGetter: (p) => p.data?.cells[loc.locationId]?.reserved ?? 0,
        cellClass: [...numericColumn.cellClass, 'nds-cell-muted'],
        headerClass: numericColumn.headerClass,
        type: 'rightAligned',
        sortable: false,
      }
      const available: ColDef<GridRow> = {
        colId: `available:${loc.locationId}`,
        headerName: 'Available',
        width: 86,
        valueGetter: (p: ValueGetterParams<GridRow>) => (!p.data ? null : isTotals(p.data) ? (p.data.cells[loc.locationId]?.available ?? 0) : availableOf(p.data, loc.locationId, pendingRef.current)),
        cellClassRules: {
          'nds-cell-stock-out': (p) => !!p.data && !isTotals(p.data) && stockLevelOf(Number(p.value), p.data.lowStockThreshold) === 'out',
          'nds-cell-stock-low': (p) => !!p.data && !isTotals(p.data) && stockLevelOf(Number(p.value), p.data.lowStockThreshold) === 'low',
          'nds-cell-stock-ok': (p) => !!p.data && !isTotals(p.data) && stockLevelOf(Number(p.value), p.data.lowStockThreshold) === 'ok',
        },
        ...numericColumn,
        sortable: false,
      }
      return {
        groupId: loc.locationId,
        headerName: loc.editable ? loc.locationCode : `${loc.locationCode} · locked`,
        headerClass: loc.editable ? undefined : styles.ieGroupLocked,
        marryChildren: true,
        children: [onHand, reserved, available],
      }
    })
    const totalAvailable: ColDef<GridRow> = {
      colId: 'totalAvailable',
      headerName: 'Total avail.',
      width: 96,
      valueGetter: (p: ValueGetterParams<GridRow>) => (!p.data ? null : isTotals(p.data) ? p.data.totalAvailable : rowTotalAvailable(p.data, model.columns, pendingRef.current)),
      cellClass: [...numericColumn.cellClass, 'nds-cell-strong'],
      headerClass: numericColumn.headerClass,
      type: 'rightAligned',
      sortable: false,
    }
    const sync: ColDef<GridRow> = { colId: 'sync', headerName: 'Sync', width: 76, cellRenderer: SyncCell, sortable: false, cellClass: 'nds-ag-cell' }
    return [identity, ...groups, totalAvailable, sync]
    // `onEdit` is stable (the modal memoises it); the columns depend on the locations and density.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [model.columns, single, density])

  const onGridReady = useCallback((e: GridReadyEvent<GridRow>) => {
    apiRef.current = e.api
    e.api.setGridOption('pinnedBottomRowData', [totals])
    applyHidden(e.api)
    onReady(e.api)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onReady, applyHidden])

  const history = useCallback((api: GridApi<GridRow>) => onHistoryChanged({ undo: api.getCurrentUndoSize(), redo: api.getCurrentRedoSize() }), [onHistoryChanged])
  // ONE stable handler for the five edit-history events (GDS decision 12: an inline arrow is a new
  // identity every render, and AG re-runs its column model for each changed option).
  const onHistory = useCallback((e: { api: GridApi<GridRow> }) => history(e.api), [history])

  const rowSelection = useMemo(() => ({
    mode: 'multiRow' as const,
    checkboxes: true,
    headerCheckbox: true,
    enableClickSelection: false,
    isRowSelectable: (n: IRowNode<GridRow>) => !n.rowPinned && !isTotals(n.data),
  }), [])
  const selectionColumnDef = useMemo(() => ({ width: gridGeometry.selectColW, maxWidth: gridGeometry.selectColW, resizable: false, pinned: 'left' as const }), [])
  const cellSelection = useMemo(() => ({ handle: { mode: 'fill' as const } }), [])
  // No header menus or sorting in the editor — the columns are the locations, fixed. Resizing
  // stays on (it is harmless), and the header partitions are the THEME's, never a per-grid option.
  const defaultColDef = useMemo<ColDef<GridRow>>(() => ({ suppressHeaderMenuButton: true, sortable: false }), [])
  const getRowId = useCallback((p: { data: GridRow }) => p.data.productId, [])
  const onSel = useCallback((e: { api: GridApi<GridRow> }) => onSelectionChanged(e.api.getSelectedNodes().map((n) => n.data!.productId).filter((id) => id !== '__total')), [onSelectionChanged])

  const rowPx = gridDensity[density].rowMedia
  // The location strip, the header, the rows, and a totals row the height of the header — the
  // page's header is shorter than its rows, and the totals row reads as a footer, not a row.
  // The totals row is the HEADER's height (IE.4), never a data row's.
  const totalsPx = gridDensity[density].header
  const height = Math.min(MAX_GRID_HEIGHT, STRIP_PX + totalsPx + model.rows.length * rowPx + totalsPx + 2)

  return (
    <GridDensityProvider value={density}>
      <NexusGrid<GridRow>
        height={height}
        density={density}
        rows="media"
        groupHeaderHeight={STRIP_PX}
        rowData={model.rows}
        getRowId={getRowId}
        columnDefs={columnDefs}
        defaultColDef={defaultColDef}
        quickFilterText={quickFilterText}
        // Spreadsheet behaviour: a focused cell takes keystrokes, Enter walks down the column.
        suppressCellFocus={false}
        enterNavigatesVertically
        enterNavigatesVerticallyAfterEdit
        stopEditingWhenCellsLoseFocus
        undoRedoCellEditing
        undoRedoCellEditingLimit={100}
        cellSelection={cellSelection}
        rowSelection={rowSelection}
        selectionColumnDef={selectionColumnDef}
        onSelectionChanged={onSel}
        // After Apply the model reloads and the rows are replaced; the selection the modal shows
        // must be what the grid holds now, not what it held before.
        onRowDataUpdated={onSel}
        onGridReady={onGridReady}
        onCellValueChanged={onHistory}
        onUndoEnded={onHistory}
        onRedoEnded={onHistory}
        onPasteEnd={onHistory}
        onFillEnd={onHistory}
      />
    </GridDensityProvider>
  )
}

'use client'

/**
 * The tree column's cell — AG's "custom group cell renderer" (`autoGroupColumnDef.cellRenderer`).
 *
 * Draws the product identity cell with its own expander wired to `node.setExpanded`, so AG renders
 * no chevron slot and no level step of its own. Under a row grouping the same cell draws the group
 * row (label + count) and indents leaf rows by level.
 */
import { useEffect, useState } from 'react'

import type { ProductRow } from '@/app/products/_types'
import { ExpandButton, GroupCell, type ICellRendererParams, type IRowNode } from '@/design-system/grid'

import { ProductCell, isGroupRow, type ProductGroupRow, groupRowLabel, type PageColumn } from './columns'

export interface ProductTreeCellParams {
  grouped: boolean
  columns: readonly PageColumn[]
  canExpand: (row: ProductRow) => boolean
}

function useExpanded(node: IRowNode): boolean {
  const [expanded, setExpanded] = useState(!!node.expanded)
  useEffect(() => {
    setExpanded(!!node.expanded)
    const onChange = () => setExpanded(!!node.expanded)
    node.addEventListener('expandedChanged', onChange)
    return () => node.removeEventListener('expandedChanged', onChange)
  }, [node])
  return expanded
}

export function ProductTreeCell(p: ICellRendererParams<ProductRow | ProductGroupRow> & ProductTreeCellParams) {
  const expanded = useExpanded(p.node)
  const data = p.data
  if (!data) return null

  if (isGroupRow(data)) {
    return (
      <div className="nds-cell-identity">
        <ExpandButton expanded={expanded} onToggle={() => p.node.setExpanded(!expanded)} labels={['Expand group', 'Collapse group']} />
        <GroupCell label={groupRowLabel(data, p.columns)} count={data.childCount} noun={['product', 'products']} />
      </div>
    )
  }

  const hasChildren = !p.grouped && p.canExpand(data)
  const level = p.grouped ? p.node.level : 0
  return (
    <div style={level > 0 ? { paddingLeft: level * 28, minWidth: 0, display: 'flex' } : undefined}>
      <ProductCell
        row={data}
        isChild={data.parentId !== null}
        hasChildren={hasChildren}
        isExpanded={expanded}
        onExpand={() => p.node.setExpanded(!expanded)}
      />
    </div>
  )
}

