// ─────────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────────

/**
 * Columns that START padlocked in the Customise dialog: the identity column and the row actions.
 *
 * A LOCK is one thing on both pages (the lock contract, 2026-09-05): the column is FROZEN — AG
 * `pinned` — always visible, not draggable, and released back into the scrolling band when the
 * operator unlocks it. These two are the grid's STRUCTURAL lead and trail (`STRUCTURAL_COLUMNS`),
 * frozen left and right; every other lock is the operator's and forms one block between them. The
 * Owner holds the key to all of them: unlock either bookend in Customise and it moves or hides like
 * any other column.
 */
const DEFAULT_LOCKED_COLUMNS: readonly string[] = STRUCTURAL_COLUMNS

/**
 * A `previous` for `columnStateToPrefs` when only its DERIVED half is read.
 *
 * `columnStateToPrefs` spreads `previous` and overwrites what the grid has an opinion about, so a
 * caller that reads only `lockedColumns` off the result must not hand it a real draft: the values it
 * carries through (the sort fallback, the page size) would come back attached to a value nobody
 * asked for. `lockedColumns: []` is what makes the field appear at all — the engine withholds it
 * from a caller that never opted into locks.
 */
const LOCKS_ONLY_PREVIOUS: PreferencesValue = {
  visibleColumns: [],
  lockedColumns: [],
  stickyFirstColumn: false,
  stickyLastColumn: false,
  pageSize: 0,
  sortBy: '',
  sortDir: 'asc',
}

/**
 * The same lock set in the same frozen order.
 *
 * `composeLocks` returns a new array every time, and this page's column definitions are memoised on
 * `lockedColumns` — so writing an equal-but-new set re-runs AG's column model for nothing, on every
 * column event and every view application. Kept referentially stable when it has not moved.
 */
const sameLocks = (a: readonly string[], b: readonly string[]): boolean => a.length === b.length && a.every((k, i) => k === b[i])

/** Which page warning the operator has already read and closed. Holds the warning's VALUE. */
const WARNING_DISMISS_KEY = 'products-next:dismissed-warning'


/** One server block — the unit the datasource fetches, whatever page size the operator picks. */
const BLOCK_SIZE = 100
/** The family footer row: a single line with a small button, not a data-row-tall band. */
const FAMILY_FOOTER_PX = gridGeometry.footerRowH
/** Rows per page, set in the footer as on Ad Manager. */
const NO_ROWS_TEMPLATE = '<span style="color: var(--nds-text-muted)">No products match this filter.</span>'

// ─────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────

type KpiTileKey = 'active' | 'out-of-stock' | 'attention' | null

/**
 * The page's OWN filter state: the accordion dimensions that are not grid columns. Everything
 * column-backed — Product search, Status, Channels, Brand, Product type, Tags, Price, Available —
 * is an AG column filter and lives in the grid's `filterModel`.
 */
type ProductFilters = ProductGridContextFilters
const EMPTY_FILTERS: ProductFilters = EMPTY_CONTEXT_FILTERS

/** What a saved view stores BESIDE the grid state — the page's own knobs. */
interface PageViewState {
  filters: ProductFilters
  tile: KpiTileKey
  density: DensityMode
  /** Columns the operator padlocked in Customise: not removable, not draggable, until unlocked. */
  lockedColumns: string[]
  /** Rows per page, from the footer. Absent on views saved before it existed. */
  pageSize?: number
  columnLayout?: SheetLayoutPayload
}

const WORKING_LAYOUT_SURFACE = 'products-next:layout'
function isProductsWorkingPayload(value: unknown): value is GridViewPayload<PageViewState> {
  return isGridStatePayload<PageViewState>(value) && !!value.gridState && typeof value.gridState === 'object' && readProductsLayout(value) !== null
}

/** GET /api/products/facets — the subset this page reads. */
interface ServerFacets {
  productTypes: Array<{ value: string; count: number }>
  brands: Array<{ value: string; count: number }>
  families: Array<{ value: string; label: string; code: string | null; count: number }>
  workflowStages: Array<{ value: string; label: string; code: string | null; count: number }>
  hygiene: { total: number; missingPhotos: number; missingDescription: number; missingBrand: number; missingGtin: number }
}

/** The grid's selection, as the page reads it. The GRID owns it; this is a read. */
interface Selection {
  ids: string[]
  rows: ProductRow[]
}
const EMPTY_SELECTION: Selection = { ids: [], rows: [] }

/**
 * Walk the loaded nodes rather than trust `getSelectedNodes()`: under SSRM a header select-all is
 * recorded as a selection STATE, and the loaded nodes answer `isSelected()` correctly while the
 * convenience list lagged behind it (measured: 12 rows ticked, count still "14 products").
 */
function readSelection(api: GridApi<ProductRow>): Selection {
  const rows: ProductRow[] = []
  api.forEachNode((n) => { if (n.data && !isGroupRow(n.data) && !isFamilyFooter(n.data) && n.isSelected()) rows.push(n.data) })
  return { ids: rows.map((r) => r.id), rows }
}

/** A family parent: the row AG may expand to its variations. ONE predicate for the grid and the cell. */
const isFamilyParent = (d: ProductRow): boolean => d.isParent || (d.childCount ?? 0) > 0

// ─────────────────────────────────────────────────────────────────
// Inner component (uses DS toast context)
// ─────────────────────────────────────────────────────────────────

function ProductsNextInner() {
  const { toast } = useToast()
  const router = useRouter()

  // The family scope. Null on the normal catalogue view. `?parent=<id>` scopes the whole page to
  // ONE variation family — the same grid, the same columns, the same filters, showing only that
  // parent's variants; the endpoint scopes its `stats` block to the query too.
  const searchParams = useSearchParams()
  const familyId = searchParams?.get('parent') ?? null

  // ── State ─────────────────────────────────────────────────────
  const [filters, setFilters] = useState<ProductFilters>(EMPTY_FILTERS)
  const [density, setDensity] = useState<DensityMode>(DEFAULT_DENSITY)
  const [activeTile, setActiveTile] = useState<KpiTileKey>(null)
  const [confirmDelete, setConfirmDelete] = useState(false)
  const [modalRow, setModalRow] = useState<ProductRow | null>(null)
  const [bulkEditOpen, setBulkEditOpen] = useState(false)
  const [tagDialogOpen, setTagDialogOpen] = useState(false)
  const [customizeOpen, setCustomizeOpen] = useState(false)

  // ── The grid's own state ───────────────────────────────────────
  // Sort, column order, widths, visibility, pinning, filters and selection all live IN the grid
  // (`api.getState()` snapshots them for a saved view). The page keeps only what the grid cannot
  // know: the accordion filters, the density, the clicked tile — and READS the rest.
  const [gridApi, setGridApi] = useState<GridApi<ProductRow> | null>(null)
  /**
   * The same api, available SYNCHRONOUSLY from the moment the grid is ready.
   *
   * `setGridApi` is a state write, so the render that sets it has not happened yet while
   * `onGridReady` is still running — and the last-used restore happens inside that call
   * (`gridViews.bind` → `applyPageState`), which has to read the grid back.
   */
  const gridApiRef = useRef<GridApi<ProductRow> | null>(null)
  /** Mirror of AG's filter model, kept current by `onFilterChanged`; the accordion reads it. */
  const [filterModel, setFilterModelState] = useState<GridFilterModel>({})
  /** Mirror of AG's selection, kept current by `onSelectionChanged`; the toolbar reads it. */
  const [selection, setSelection] = useState<Selection>(EMPTY_SELECTION)
  // What the last top-level block said about the whole result: the "of N" count and the KPI
  // stats. Null until a response lands — a count of zero for something never counted is a lie.
  const [listMeta, setListMeta] = useState<{
    total: number
    stats?: ProductsListStats
    salesUnattributed: Array<{ channel: string; orders: number; units: number; revenueCents: number }> | null
  } | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  // Things the request could not express (a tag with no id, a sort the server lacks). Shown,
  // never swallowed: a filter that silently stops filtering widens the result behind the
  // operator's back.
  const [unsupported, setUnsupported] = useState<string[]>([])
  /**
   * The LOCK SET, in frozen order (`composeLocks`): the identity column, the operator's frozen
   * block, the actions column. The two structural padlocks cannot be read back out of AG's column
   * state — a pin says "frozen", not "padlocked", and the actions pin is on the right — so the set
   * lives here and rides into the saved view with the other page knobs. The operator's own locks
   * ARE readable from the grid, and the grid is their truth: see `locksFromGrid`.
   */
  const [lockedColumns, setLockedColumns] = useState<string[]>([...DEFAULT_LOCKED_COLUMNS])
  const lockedRef = useRef(lockedColumns)
  lockedRef.current = lockedColumns
  /**
   * Grouped is a VIEW MODE: AG's auto column is either the family tree or the group column, never
   * both. While a grouping is active the tree is off and families do not expand.
   */
  const [grouped, setGrouped] = useState(false)
  const [pageSize, setPageSize] = useState(BLOCK_SIZE)
  const [pager, setPager] = useState<{ page: number; pageCount: number }>({ page: 1, pageCount: 1 })

  const columnLayoutRef = useRef<SheetLayoutPayload | null>(null)
  const initialPayloadRef = useRef<GridViewPayload<PageViewState> | null>(null)
  const layoutLanded = useRef(false)
  const [layoutBootstrapped, setLayoutBootstrapped] = useState(false)
  const [workingState, setWorkingState] = useState<{ loaded: boolean; error: string | null; record: StoredSheetLayout<GridViewPayload<PageViewState>> | null }>({ loaded: false, error: null, record: null })
  const workingRef = useRef(workingState)
  const workingRequest = useRef(0)
  const layoutSaving = useRef(false)
  const backendUrl = getBackendUrl()
  const loadSavedLayout = useCallback(async () => {
    const request = ++workingRequest.current
    try {
      const record = await loadWorkingLayout(backendUrl, WORKING_LAYOUT_SURFACE, isProductsWorkingPayload)
      if (request !== workingRequest.current) throw new Error('A newer layout load is already in progress')
      workingRef.current = { loaded: true, error: null, record }
      setWorkingState(workingRef.current)
      return record
    } catch (error) {
      if (request === workingRequest.current) {
        workingRef.current = { ...workingRef.current, loaded: true, error: error instanceof Error ? error.message : 'Could not load your saved layout' }
        setWorkingState(workingRef.current)
      }
      throw error
    }
  }, [backendUrl])
  useEffect(() => {
    void loadSavedLayout().catch(() => {})
    return () => { workingRequest.current += 1 }
  }, [loadSavedLayout])

  const pageSnapshot = useCallback((): PageViewState => ({ filters, tile: activeTile, density, lockedColumns, pageSize, ...(columnLayoutRef.current ? { columnLayout: columnLayoutRef.current } : {}) }), [filters, activeTile, density, lockedColumns, pageSize])
  const restorePageState = useCallback((pg: PageViewState) => {
    columnLayoutRef.current = pg.columnLayout ?? null
    setFilters(pg.filters ?? EMPTY_FILTERS)
    setActiveTile(pg.tile ?? null)
    setDensity(pg.density ?? DEFAULT_DENSITY)
    const viewLocks = composeLocks(pg.lockedColumns ?? DEFAULT_LOCKED_COLUMNS)
    lockedRef.current = viewLocks
    setLockedColumns((prev) => sameLocks(prev, viewLocks) ? prev : viewLocks)
    if (pg.pageSize) setPageSize(pg.pageSize)
  }, [])

  // Current layout and named views use the same payload; named Save writes both atomically.
  const gridViews = useGridState<PageViewState>({
    surface: 'products-next',
    baseUrl: backendUrl,
    getPageState: pageSnapshot,
    applyPageState: (pg) => restorePageState(!layoutLanded.current && initialPayloadRef.current ? initialPayloadRef.current.page : pg),
  })
  useEffect(() => {
    if (layoutBootstrapped || !workingState.loaded || (!gridViews.loaded && !gridViews.loadError)) return
    const named = gridViews.defaultView
    const payload = workingState.record?.filters ?? (named && isGridStatePayload<PageViewState>(named.payload) ? named.payload : null)
      ?? (gridViews.lastUsed ? { v: 1 as const, gridState: gridViews.lastUsed.gridState, page: gridViews.lastUsed.page } : null)
    initialPayloadRef.current = payload
    if (payload) {
      restorePageState(payload.page)
      setGrouped(!!payload.gridState.rowGroup?.groupColIds.length)
      const matching = gridViews.views.find((view) => JSON.stringify(view.payload) === JSON.stringify(payload))
      gridViews.markActive(matching?.id ?? null)
    }
    setLayoutBootstrapped(true)
  }, [layoutBootstrapped, workingState, gridViews, restorePageState])
  const gridViewsBind = gridViews.bind
  // What AG's state cannot hold — density, page size, the accordion, a tile, the padlocks — is the
  // page's; the state hook is told when it moves so the last-used state carries it too.
  const gridViewsMarkDirty = gridViews.markDirty
  useEffect(() => { gridViewsMarkDirty() }, [gridViewsMarkDirty, filters, activeTile, density, lockedColumns, pageSize])

  // ── Data the page fetches itself ───────────────────────────────
  // The grid asks the server for blocks (see the datasource below). The page's own fetches are
  // the facets (accordion option lists, the "Needs attention" tile), the merchant's active
  // channels, the tag list, and — in family scope — the family's own row for the header.
  const [facets, setFacets] = useState<ServerFacets | null>(null)
  const refreshFacets = useCallback(() => {
    fetch(`${getBackendUrl()}/api/products/facets`, { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: ServerFacets) => setFacets(d))
      .catch(() => { /* option lists stay empty — visibly, not silently */ })
  }, [])
  useEffect(() => { refreshFacets() }, [refreshFacets])

  const [family, setFamily] = useState<ProductRow | null>(null)
  useEffect(() => {
    if (!familyId) { setFamily(null); return }
    let cancelled = false
    fetch(`${getBackendUrl()}/api/products/${encodeURIComponent(familyId)}`, { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: ProductRow) => { if (!cancelled) setFamily(d) })
      .catch(() => { /* header falls back to the SKU-less wording */ })
    return () => { cancelled = true }
  }, [familyId])

  /**
   * Which channels COUNT for this merchant — the active connections, not every channel the
   * platform supports. Driving it from here is also the scalability answer: connect Etsy and the
   * column includes it with no code change, drop a connection and it stops being a gap.
   */
  const [activeChannels, setActiveChannels] = useState<string[]>([])
  useEffect(() => {
    let cancelled = false
    fetch(`${getBackendUrl()}/api/connections`, { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: { connections?: Array<{ channel: string; isActive: boolean }> }) => {
        if (cancelled) return
        setActiveChannels([...new Set((d.connections ?? []).filter((c) => c.isActive).map((c) => c.channel))])
      })
      .catch(() => { /* no roster ⇒ the cell says "no channels" rather than inventing one */ })
    return () => { cancelled = true }
  }, [])

  const [allTags, setAllTags] = useState<ProductTag[]>([])
  const refreshTags = useCallback(() => {
    fetch(`${getBackendUrl()}/api/tags`, { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: { items?: ProductTag[] }) => setAllTags(d.items ?? []))
      .catch(() => { /* tags are optional; the dialog offers to create the first one */ })
  }, [])
  useEffect(() => { refreshTags() }, [refreshTags])

  /**
   * Re-ask the server for whatever is on screen, IN PLACE. Called on every invalidation and by
   * the error state's "Try again". `purge: false` on purpose: a purge throws away every loaded
   * block AND collapses every expanded family, so a stock event landing while an operator is
   * looking at a family's variations would fold them away mid-read.
   */
  const refetch = useCallback(() => {
    setListError(null)
    if (gridApi && !gridApi.isDestroyed()) gridApi.refreshServerSide({ purge: false })
    refreshFacets()
  }, [gridApi, refreshFacets])
  /**
   * The SERVER's events, not just this tab's.
   *
   * `useInvalidationChannel` is a BroadcastChannel: until this hook was mounted (2026-08-31) the
   * only thing feeding it here was the page's own optimistic emits, so a sale landing by webhook, a
   * cron sync, a bulk job or another operator's edit never reached the grid — it sat on whatever it
   * had until someone reloaded. This route is standalone (`AppShell` suppresses global chrome), so
   * no provider above it mounts the stream; every other workspace mounts this hook itself.
   *
   * It is self-contained — one `EventSource` per tab, auto-reconnecting — and dispatches into the
   * same invalidation channel subscribed to below, so nothing else here changes.
   *
   * 🔴 `stock.adjusted` is NOT among the events it maps: every emitter of that type is a client
   * file, so a server-side stock change still will not move the Available column. That needs the
   * API to raise an inventory event onto this bus.
   */
  useListingEvents()
  useInvalidationChannel(
    ['product.updated', 'product.created', 'product.deleted', 'stock.adjusted', 'listing.updated'],
    () => refetch(),
  )

  const stats = listMeta?.stats
  const loading = listMeta == null && listError == null
  const error = listError
  const totalCount = listMeta?.total ?? null
  // From the server's hygiene facet — the whole catalogue, not the rows a page holds.
  const needsAttentionCount: number | null = facets?.hygiene.missingPhotos ?? null

  // Filter options from the server's facets. Families and stages carry an id (`value`) AND a
  // code; the accordion keeps showing codes, and the contract maps code → id on the way out.
  const facetOptions = useMemo(() => {
    const byStr = (a: string, b: string) => a.localeCompare(b)
    const fam = (facets?.families ?? []).map((f) => [f.code ?? 'null', f.label] as [string, string])
    const stg = (facets?.workflowStages ?? []).map((f) => [f.code ?? 'null', f.label] as [string, string])
    return {
      types: (facets?.productTypes ?? []).map((t) => t.value).sort(byStr),
      brands: (facets?.brands ?? []).map((b) => b.value).sort(byStr),
      families: fam.sort((a, b) => a[1].localeCompare(b[1])),
      stages: stg.sort((a, b) => a[1].localeCompare(b[1])),
    }
  }, [facets])

  // ── Selection: the grid owns it, the page reads it ─────────────
  // One direction. The grid reports every change; "Clear" and every consuming bulk action ask
  // the grid to deselect, and the report comes back through the same event.
  const clearSelection = useCallback(() => {
    setConfirmDelete(false)
    if (gridApi && !gridApi.isDestroyed()) gridApi.deselectAll()
  }, [gridApi])
  const onSelectionChanged = useCallback((e: { api: GridApi<ProductRow> }) => {
    const next = readSelection(e.api)
    setSelection((prev) => (prev.ids.length === next.ids.length && prev.ids.every((id, i) => id === next.ids[i]) ? { ...prev, rows: next.rows } : next))
  }, [])
  /**
   * How many VARIATIONS the current selection reaches. Selecting a parent selects the parent — one
   * row, one tick — because the depth differs per action and folding them together would make
   * select-all unusable (14 parents expand to 315, and every bulk endpoint caps at 200). So the
   * reach is stated instead of implied, and stated BEFORE the click rather than in the toast.
   */
  const selectionReach = useMemo(
    () => selection.rows.filter((r) => r.parentId === null).reduce((n, r) => n + (r.childCount ?? 0), 0),
    [selection.rows],
  )
  useEffect(() => {
    if (selection.ids.length === 0 && confirmDelete) setConfirmDelete(false)
  }, [selection.ids.length, confirmDelete])

  // ── Mutations ─────────────────────────────────────────────────
  const { busy, setStatusBulk, duplicateBulk, softDeleteBulk } = useBulkActions({ toast, onConsumed: clearSelection })
  /**
   * One write per field that was ticked, in order, each reporting its own outcome — a status
   * flip that lands and a tag write that fails must not share one green toast.
   */
  const applyBulkEdit = useCallback(
    async (c: BulkEditChanges) => {
      if (c.status) await setStatusBulk(selection.ids, c.status, c.includeChildren)
      setBulkEditOpen(false)
    },
    [setStatusBulk, selection.ids],
  )
  const moreActionItems = useMemo<MenuItemDef[]>(
    () => [{ id: 'readiness', label: 'Check listing readiness…', icon: <Send size={13} />, onSelect: () => {
      if (selection.ids.length > BULK_MAX) { toast(`Select ${BULK_MAX} or fewer products for a readiness check.`, 'danger'); return }
      router.push(`/products/listing-readiness?${new URLSearchParams({ productIds: selection.ids.join(',') })}`)
    } }],
    [selection.ids, router, toast],
  )

  // ── Columns ───────────────────────────────────────────────────
  const onDuplicate = useCallback((id: string) => void duplicateBulk([id]), [duplicateBulk])
  /**
   * Right-click a row. The SAME actions the `⋯` column offers, read from `rowActions` — a context
   * menu that drifted from the row menu would be two answers to one question.
   *
   * AG's own items (copy, CSV export) stay below a rule: the operator gains this menu without
   * losing what the grid already gave them. A group row and the family-footer sentinel are not
   * products, so they get AG's defaults alone — "Edit" on a footer would navigate to an id that is
   * not one.
   *
   * Memoised: an inline callback re-runs AG's column model on every render.
   */
  const getContextMenuItems = useCallback(
    (p: GetContextMenuItemsParams<ProductRow>) => {
      const defaults = (p.defaultItems ?? []) as (DefaultMenuItem | AgMenuItemDef<ProductRow>)[]
      const data = p.node?.data
      if (!data || isGroupRow(data) || isFamilyFooter(data)) return defaults
      const own: AgMenuItemDef<ProductRow>[] = rowActions(data, { onDuplicate, navigate: (href) => router.push(href) }).map((item) => ({
        // AG takes `name: string`; `rowActions` keeps its labels plain so both menus can read it.
        name: typeof item.label === 'string' ? item.label : item.id,
        disabled: item.disabled,
        action: item.onSelect,
      }))
      return defaults.length ? [...own, 'separator' as DefaultMenuItem, ...defaults] : own
    },
    [onDuplicate, router],
  )

  const columns = useMemo(
    // The Channels cell reads `activeChannels`; omitting it froze the column on the empty roster
    // it was built with, so every row read "no channels" while /api/connections answered 200.
    () => buildPageColumns({ activeChannels, onDuplicate, onOpenInventory: setModalRow, navigate: (href) => router.push(href) }),
    [activeChannels, onDuplicate, router],
  )

  const preferenceColumns = useMemo<PreferencesColumnSpec[]>(() => columns.map((c) => ({
    key: c.key, label: columnLabel(c), group: c.group, groupKey: c.groupKey,
    defaultLocked: DEFAULT_LOCKED_COLUMNS.includes(c.key),
    ...(c.key === 'actions' ? { lockSide: 'right' as const } : {}),
  })), [columns])

  /**
   * Which column carries which filter, from the shared contract — the same table the server
   * reads. Set-filter options come from the facets the accordion already loads.
   */
  const filterDefFor = useCallback(
    (key: string): Partial<ColDef<ProductRow>> => {
      const kind = (GRID_FILTER_COLUMNS as Record<string, 'set' | 'number' | 'text' | undefined>)[key]
      if (!kind) return {}
      if (kind === 'text') return gridFilterDef('text')
      if (kind === 'number') return gridFilterDef('number', key === 'price' ? { unit: '€' } : {})
      const options =
        key === 'status' ? STATUS_OPTS
        : key === 'channels' ? CHANNEL_OPTS
        : key === 'brand' ? facetOptions.brands.map((b) => ({ value: b, label: b }))
        : key === 'productType' ? facetOptions.types.map((t) => ({ value: t, label: t }))
        : key === 'tags' ? allTags.map((t) => ({ value: t.name, label: t.name }))
        : []
      return gridFilterDef('set', { options, searchable: key === 'brand' || key === 'productType' || key === 'tags' })
    },
    [facetOptions, allTags],
  )

  const colDefs = useMemo(() => projectColDefs(columns, { lockedColumns, filterDefFor }), [columns, lockedColumns, filterDefFor])

  /**
   * The Product column IS the tree column. Its cell is this page's own (`ProductTreeCell`), which
   * is AG's way to draw a custom group cell: the DS expander wired to `node.setExpanded`, a
   * variation directly under its parent, a group's products stepped in under the group.
   */
  const groupHeader = useMemo(() => {
    if (!gridApi || !grouped) return 'Product'
    const labels = gridApi.getRowGroupColumns().map((col) => {
      const c = columns.find((x) => x.key === col.getColId())
      return c ? columnLabel(c) : (col.getColDef().headerName ?? col.getColId())
    })
    return labels.length ? labels.join(' › ') : 'Product'
  }, [gridApi, grouped, columns])
  const autoGroupColumnDef = useMemo<ColDef<ProductRow>>(
    () => ({
      colId: 'product',
      headerName: groupHeader,
      // A value on every row: the CSV export and the sort indicator read it.
      valueGetter: (p) => (isGroupRow(p.data) ? p.data.groupKey : p.data?.name ?? null),
      flex: 1,
      minWidth: 320,
      /**
       * FROZEN at the left edge, always visible, not draggable WHILE padlocked — the default — and
       * an ordinary scrolling column the moment the operator unlocks it in Customise.
       *
       * 🔴 No `pinned` here, deliberately, though this column IS pinned left while locked. AG
       * ignores `flex` on a pinned column (`ColumnFlexService` sizes `visibleCols.centerCols` only),
       * so a definition that pins it before the first flex pass would freeze it at its `minWidth`
       * — measured: 320px in a 1,552px card, leaving a 143px dead strip between "Last updated" and
       * "Actions". Pinned by the page AFTER the grid has sized it (`applyStructuralPins`, run from
       * the reconciliation effect and from every apply), it keeps the width flex gave it: measured
       * 463px, total column width 1,552 = the card, no gap. `lockPinned` still belongs in the
       * definition — it is what takes "Pin column" out of a structural column's header menu.
       */
      lockPosition: lockedColumns.includes('product') ? 'left' : undefined,
      lockPinned: lockedColumns.includes('product'),
      lockVisible: lockedColumns.includes('product'),
      suppressMovable: lockedColumns.includes('product'),
      sortable: true,
      cellClass: 'nds-ag-cell',
      ...gridFilterDef('text'),
      cellRenderer: ProductTreeCell,
      cellRendererParams: { grouped, columns, canExpand: isFamilyParent } satisfies ProductTreeCellParams,
    }),
    [lockedColumns, groupHeader, columns, grouped],
  )

  // ── The datasource ────────────────────────────────────────────
  // Stable identity, live context: a ref lets one datasource read the CURRENT page context on
  // every request, and the effect below tells the grid to re-ask whenever that context changes.
  // Names and codes travel as the operator sees them; the server resolves them to ids.
  const ctxRef = useRef({ filters, tile: activeTile, familyId, salesDays: SALES_WINDOW_DAYS })
  ctxRef.current = { filters, tile: activeTile, familyId, salesDays: SALES_WINDOW_DAYS }
  const datasource = useMemo(
    () =>
      createProductsDatasource<ProductRow>({
        getContext: () => ctxRef.current,
        onTopLevel: ({ total, stats, response }) => {
          setListError(null)
          setListMeta({ total, stats, salesUnattributed: response.salesUnattributed ?? null })
        },
        onUnsupported: (items) => setUnsupported((prev) => (prev.join('|') === items.join('|') ? prev : items)),
        onError: (message) => setListError(message),
      }),
    [],
  )

  /**
   * A NEW QUERY purges the cache and re-asks. What counts as a new query is decided by the
   * contract itself — the effect keys on the context the datasource would send, not on the
   * inputs that feed it. Keying on the inputs was a real bug: facets and tags arrive one to
   * three seconds after load and used to purge the grid — collapsing every expanded family —
   * exactly when an operator had just expanded one.
   */
  const querySignature = useMemo(
    // The sort and the column filters are AG's own; AG re-asks on its own when they change.
    () => JSON.stringify(buildGridRequest(ctxRef.current, { sortModel: [], groupKeys: [] }).context),
    // ctxRef mirrors exactly these; listing them keeps the memo honest.
    [filters, activeTile, familyId],
  )
  const lastSignature = useRef<string | null>(null)
  useEffect(() => {
    if (!gridApi) return
    if (lastSignature.current === querySignature) return
    const isFirst = lastSignature.current === null
    lastSignature.current = querySignature
    if (isFirst) return // the grid's own first load already asked with this query
    setUnsupported([])
    if (!gridApi.isDestroyed()) gridApi.refreshServerSide({ purge: true })
  }, [gridApi, querySignature])

  // Row height is a grid option; when the density changes AG must re-measure the rows it holds.
  useEffect(() => {
    if (gridApi && !gridApi.isDestroyed()) gridApi.resetRowHeights()
  }, [gridApi, density])

  // ── Customise: the DS dialog, backed by AG's column state ──────
  // Opening reads the grid's LIVE state — a column dragged in the header shows up in that order —
  // and confirming applies the dialog's answer in one call. Views persist it as part of the grid
  // state they already snapshot, so there is no separate store to drift.
  /**
   * The bridge for a GIVEN lock set, not for the current one.
   *
   * `PrefsColumnMeta.locked` is what tells the engine which columns are the grid's structural lead
   * and trail — it pins those itself and keeps them out of the operator's block. On this page that
   * is a function of the lock set, because the Owner can unlock either bookend, so an apply must be
   * bridged with the lock set it is APPLYING. Bridging the operator's new answer with the old locks
   * was the bug this shape prevents: unlock Product in the dialog and the engine would still treat
   * it as its own lead, pin it, and drop it from `lockedColumns` — the padlock would come back.
   */
  const bridgeFor = useCallback(
    (locks: readonly string[]): PrefsBridgeOptions => ({
      columns: columns.map((c) => ({ key: c.key, locked: isStructuralColumn(c.key) && locks.includes(c.key) })),
      treeColumnKey: 'product',
      sortKeyToColumn: { product: 'product', available: 'available', price: 'price' },
    }),
    [columns],
  )
  const defaultPrefs = useMemo<PreferencesValue>(
    () => ({
      visibleColumns: columns.filter((c) => !c.defaultHidden).map((c) => c.key),
      lockedColumns,
      rowGroups: [],
      aggregations: {},
      // The two structural pins, in the engine's vocabulary: the lead is frozen left while `product`
      // is padlocked, the trail frozen right while `actions` is. There are no Display toggles for
      // them on this page (`showSticky={false}`) — the padlocks ARE the control.
      stickyFirstColumn: lockedColumns.includes('product'),
      stickyLastColumn: lockedColumns.includes('actions'),
      pageSize: BLOCK_SIZE,
      sortBy: 'product',
      sortDir: 'asc',
    }),
    [columns, lockedColumns],
  )
  const [prefsDraft, setPrefsDraft] = useState<PreferencesValue | null>(null)
  /**
   * The operator's locks AS THE GRID HAS THEM, plus the structural padlocks the page holds.
   *
   * The lock contract's rule for callers: never apply a `lockedColumns` that was not read from the
   * grid or confirmed in the dialog moments ago. `columnStateToPrefs` derives the operator's block
   * from `pinned === 'left'`, so a pin made in the header menu or by dragging a column into the
   * pinned area IS a lock, and survives the next view application instead of being overwritten by
   * a stale copy the page was keeping.
   *
   * The structural pair cannot come from there: the engine keeps them out of the operator's set by
   * construction, and a right pin is not a left pin. They come from `lockedRef` — the page's own
   * padlock state, which the dialog and the saved views round-trip.
   */
  const locksFromGrid = useCallback(
    (api: GridApi<ProductRow>, padlocks: readonly string[] = lockedRef.current): string[] => {
      const read = columnStateToPrefs(api.getColumnState(), LOCKS_ONLY_PREVIOUS, bridgeFor(padlocks))
      return composeLocks([...padlocks.filter(isStructuralColumn), ...(read.lockedColumns ?? [])])
    },
    [bridgeFor],
  )
  /** Make the grid's structural pins say what the padlocks say. Pins only — never order or sort. */
  const applyStructuralPins = useCallback((api: GridApi<ProductRow>, locks: readonly string[]) => {
    if (api.isDestroyed()) return
    const state = structuralPinState(locks, AG_AUTO_COL).filter((s) => (api.getColumn(s.colId)?.getPinned() ?? null) !== s.pinned)
    if (state.length > 0) api.applyColumnState({ state })
  }, [])
  /**
   * Reconcile after somebody ELSE applied a whole column state: the mount restore, a saved view.
   *
   * Reads the pins back (the operator's locks are the grid's), re-asserts the two structural ones
   * (they are the page's — `padlocks` names them, defaulting to what the page holds now), and
   * leaves the lock set and the grid's pins saying the same thing. Idempotent, so the effect below
   * and the view application may both run it.
   */
  const reconcileLocks = useCallback(
    (api: GridApi<ProductRow>, padlocks?: readonly string[]) => {
      const locks = locksFromGrid(api, padlocks)
      applyStructuralPins(api, locks)
      setLockedColumns((prev) => (sameLocks(prev, locks) ? prev : locks))
    },
    [locksFromGrid, applyStructuralPins],
  )
  // 🔴 The grid appearing is itself an unreconciled state: whatever `initialState` restored — a
  // last-used blob, a default view — was written before this contract or by another lane, and AG
  // releases every pin its `columnPinning` slice does not name.
  useEffect(() => {
    if (!gridApi || gridApi.isDestroyed()) return
    reconcileLocks(gridApi)
  }, [gridApi, reconcileLocks])
  /** Read live pins and visibility while retaining saved group assignments and hidden-column order. */
  const currentPreferences = useCallback((): PreferencesValue => {
    const api = gridApiRef.current
    const stored = columnLayoutRef.current
    const previous = { ...defaultPrefs, ...(stored ? preferencesFromLayout(stored, preferenceColumns) : {}) }
    if (!api || api.isDestroyed()) return previous
    const locks = locksFromGrid(api)
    const read = withStructuralLocks(columnStateToPrefs(api.getColumnState(), { ...previous, lockedColumns: locks }, bridgeFor(locks)), locks)
    const keys = new Set(preferenceColumns.map((c) => c.key))
    return {
      ...read,
      columnOrder: mergeVisibleColumnOrder(stored?.columnOrder ?? preferenceColumns.map((column) => column.key), read.visibleColumns.filter((key) => !locks.includes(key) && !read.rowGroups?.includes(key))),
      visibleColumns: [...read.visibleColumns, ...(stored?.columns.filter((key) => !keys.has(key)) ?? [])],
    }
  }, [defaultPrefs, preferenceColumns, locksFromGrid, bridgeFor])
  const syncPrefsFromGrid = useCallback(() => {
    const api = gridApiRef.current
    if (!api || api.isDestroyed()) return
    const read = currentPreferences()
    setPrefsDraft(read)
    const locks = read.lockedColumns ?? []
    setLockedColumns((prev) => sameLocks(prev, locks) ? prev : locks)
  }, [currentPreferences])
  const openCustomize = useCallback(() => {
    if (!gridApi) return
    setPrefsDraft(currentPreferences())
    setCustomizeOpen(true)
  }, [gridApi, currentPreferences])
  /** Tree or groups — decided BEFORE the column state applies, so the first request is right. */
  const applyViewMode = useCallback(
    (next: PreferencesValue) => {
      const isGrouped = (next.rowGroups ?? []).length > 0
      gridApi?.setGridOption('treeData', !isGrouped)
      setGrouped(isGrouped)
    },
    [gridApi],
  )
  /**
   * The operator's answer, applied. `next.lockedColumns` is the one thing here that is theirs by
   * construction — they were just looking at the padlocks — so the contract's rule is satisfied and
   * the engine may state a pin for every togglable column.
   *
   * Normalised first, because the dialog's list and the engine's two pin flags have to agree: the
   * set is put back in frozen order, and the structural pins follow the bookends' padlocks (the
   * dialog's own "Reset to default" writes `stickyFirst/LastColumn: true` from the shared defaults,
   * which on a page with no Display toggles would otherwise decide the lead pin by accident).
   */
  const applyPrefs = useCallback(
    (next: PreferencesValue) => {
      const locks = composeLocks(next.lockedColumns ?? DEFAULT_LOCKED_COLUMNS)
      const value: PreferencesValue = {
        ...next,
        lockedColumns: locks,
        stickyFirstColumn: locks.includes('product'),
        stickyLastColumn: locks.includes('actions'),
      }
      applyViewMode(value)
      const api = gridApi
      if (api) {
        api.applyColumnState({ state: prefsToColumnState(value, bridgeFor(locks)), applyOrder: true })
        // The lead pin belongs to the auto column, which the engine states as `AG_AUTO_COL`; the
        // trail pin also lives in the actions definition. Asserted again so an unlock RELEASES.
        applyStructuralPins(api, locks)
      }
      setLockedColumns((prev) => (sameLocks(prev, locks) ? prev : locks))
      setPrefsDraft(value)
    },
    [gridApi, bridgeFor, applyViewMode, applyStructuralPins],
  )
  const applyStoredLayout = useCallback((payload: GridViewPayload<PageViewState>) => {
    const api = gridApiRef.current
    if (!api || api.isDestroyed()) return
    columnLayoutRef.current = readProductsLayout(payload)
    const isGrouped = !!payload.gridState.rowGroup?.groupColIds.length
    api.setGridOption('treeData', !isGrouped)
    setGrouped(isGrouped)
    api.setState(payload.gridState)
    restorePageState(payload.page)
    reconcileLocks(api, composeLocks(payload.page.lockedColumns ?? DEFAULT_LOCKED_COLUMNS))
    gridViews.markDirty()
  }, [restorePageState, reconcileLocks, gridViews])
  const applyNamedView = useCallback((view: SavedGridView<PageViewState>) => {
    if (!isGridStatePayload<PageViewState>(view.payload)) return
    applyStoredLayout(view.payload)
    gridViews.markActive(view.id)
  }, [applyStoredLayout, gridViews])

  const saveLayout = useCallback(async (draft: PreferencesValue, named?: { name: string; view?: SavedGridView<PageViewState> }) => {
    if (layoutSaving.current) throw new Error('A layout save is already in progress')
    const working = workingRef.current
    if (!working.loaded || working.error) throw new Error('Load your saved layout before saving. Use Reload saved layout to retry.')
    const api = gridApiRef.current
    if (!api || api.isDestroyed()) throw new Error('The products grid is not ready to save')
    const payload = buildProductsLayout({ v: 1, gridState: api.getState(), page: pageSnapshot() }, { ...draft, sortBy: '' }, preferenceColumns, bridgeFor(draft.lockedColumns ?? []))
    layoutSaving.current = true
    try {
      let record: StoredSheetLayout<GridViewPayload<PageViewState>>
      let namedId: string | null = null
      if (named) {
        const saved = await gridViews.saveRecord(named.name, {
          id: named.view?.id, isDefault: named.view?.isDefault, expectedUpdatedAt: named.view?.updatedAt, payload,
          workingLayout: { surface: WORKING_LAYOUT_SURFACE, filters: payload, expectedUpdatedAt: working.record?.updatedAt ?? null },
        })
        if (!saved.workingLayout || !isProductsWorkingPayload(saved.workingLayout.filters)) throw new Error('The server did not acknowledge your layout. Reload saved layout before retrying.')
        record = { ...saved.workingLayout, filters: saved.workingLayout.filters }
        namedId = saved.id
      } else record = await saveWorkingLayout(backendUrl, WORKING_LAYOUT_SURFACE, payload, working.record)
      workingRef.current = { loaded: true, error: null, record }
      setWorkingState(workingRef.current)
      columnLayoutRef.current = payload.page.columnLayout
      // Only the column preferences apply here; current product selection and filters stay live.
      applyPrefs({ ...draft, ...preferencesFromLayout(payload.page.columnLayout, preferenceColumns),
        rowGroups: draft.rowGroups, aggregations: draft.aggregations, sortBy: '', sortDir: draft.sortDir })
      gridViews.markActive(namedId)
      return namedId
    } finally { layoutSaving.current = false }
  }, [pageSnapshot, preferenceColumns, bridgeFor, gridViews, backendUrl, applyPrefs])
  const confirmCustomize = useCallback(async (draft: PreferencesValue) => { await saveLayout(draft) }, [saveLayout])
  const reloadSavedPreferences = useCallback(async () => {
    const record = await loadSavedLayout()
    await gridViews.refresh()
    if (record) {
      applyStoredLayout(record.filters)
      gridViews.markActive(null)
      return { ...currentPreferences(), ...preferencesFromLayout(record.filters.page.columnLayout ?? null, preferenceColumns) }
    }
    // No working layout yet: refresh named revisions while preserving the current draft's context.
    return currentPreferences()
  }, [loadSavedLayout, gridViews, applyStoredLayout, currentPreferences, preferenceColumns])
  const activeSavedView = gridViews.views.find((view) => view.id === gridViews.activeId) ?? null

  /**
   * "Reset columns" from a header menu: the page's defaults, in ONE column-state call. Each
   * column's width, flex and pin go back to its definition. `api.resetColumnState()` would do the
   * widths but would also clear the sort first, and under SSRM every sort change is a round-trip.
   */
  const resetColumns = useCallback(() => {
    if (!gridApi) return
    // The default locks, and only them: the identity column frozen left, actions frozen right,
    // every other column released back into the scrolling band.
    columnLayoutRef.current = null
    const locks = composeLocks(DEFAULT_LOCKED_COLUMNS)
    const next: PreferencesValue = { ...defaultPrefs, lockedColumns: locks, stickyFirstColumn: true, stickyLastColumn: true }
    applyViewMode(next)
    const state = prefsToColumnState(next, bridgeFor(locks)).map((s) => {
      const def = gridApi.getColumn(s.colId)?.getColDef()
      return { ...s, width: def?.width, flex: def?.flex ?? null }
    })
    gridApi.applyColumnState({ state, applyOrder: true })
    applyStructuralPins(gridApi, locks)
    setLockedColumns((prev) => (sameLocks(prev, locks) ? prev : locks))
    setPrefsDraft(next)
  }, [gridApi, defaultPrefs, bridgeFor, applyViewMode, applyStructuralPins])

  const onGridReady = useCallback((e: GridReadyEvent<ProductRow>) => {
    // The ref FIRST: `gridViewsBind` applies the last-used state inside this call, and its
    // `applyPageState` reconciles the locks against the grid through it.
    gridApiRef.current = e.api
    setGridApi(e.api)
    setFilterModelState(e.api.getFilterModel() as GridFilterModel)
    gridViewsBind(e.api)
    layoutLanded.current = true
  }, [gridViewsBind])

  const onPage = useCallback((n: number) => gridApi?.paginationGoToPage(n - 1), [gridApi])
  const onPageSize = useCallback((n: number) => { setPageSize(n); gridApi?.paginationGoToPage(0) }, [gridApi])
  const onPaginationChanged = useCallback((e: { api: GridApi<ProductRow> }) => {
    setPager({ page: e.api.paginationGetCurrentPage() + 1, pageCount: Math.max(1, e.api.paginationGetTotalPages()) })
  }, [])

  // ── KPI tiles ──────────────────────────────────────────────────
  // Each tile is a real button with `aria-pressed`, because each one TOGGLES a filter.
  const kpiMetrics = useMemo<Metric[]>(() => {
    const tiles: Array<{ tileKey: KpiTileKey; label: string; value: number | string; hint: string; accent: string }> = [
      { tileKey: null, label: 'Total', value: stats?.total ?? '—', hint: 'all statuses', accent: 'var(--nds-primary)' },
      { tileKey: 'active', label: 'Active', value: stats?.active ?? '—', hint: 'live & selling', accent: 'var(--nds-success)' },
      { tileKey: 'out-of-stock', label: 'Out of stock', value: stats?.outOfStock ?? '—', hint: 'no available units', accent: 'var(--nds-danger)' },
      { tileKey: 'attention', label: 'Needs attention', value: needsAttentionCount ?? '—', hint: 'photos · GTIN · description', accent: 'var(--nds-warning)' },
    ]
    return tiles.map((t) => ({
      label: t.label,
      value: t.value,
      hint: t.hint,
      accent: t.accent,
      active: activeTile === t.tileKey,
      onClick: () => setActiveTile((prev) => (prev === t.tileKey ? null : t.tileKey)),
    }))
  }, [stats, needsAttentionCount, activeTile])

  /**
   * Which warning the operator has already dismissed — the VALUE, not a boolean. Storing what
   * was dismissed means the banner comes back the moment it has something different to say.
   */
  const [dismissedWarning, setDismissedWarning] = useState<string | null>(null)
  useEffect(() => {
    try { setDismissedWarning(localStorage.getItem(WARNING_DISMISS_KEY)) } catch { /* private mode: the banner simply always shows */ }
  }, [])
  const dismissWarning = useCallback((key: string) => {
    setDismissedWarning(key)
    try { localStorage.setItem(WARNING_DISMISS_KEY, key) } catch { /* dismissal just won't survive a reload */ }
  }, [])

  // Fold the per-channel orphan rows into one honest sentence. Null when sales were not
  // requested, or when every line attributed cleanly — there is nothing to say then.
  const unattributed = useMemo(() => {
    const rows = listMeta?.salesUnattributed
    if (!rows || rows.length === 0) return null
    const cents = rows.reduce((sum, r) => sum + r.revenueCents, 0)
    const orders = rows.reduce((sum, r) => sum + r.orders, 0)
    if (cents === 0) return null
    const channels = rows
      .filter((r) => r.revenueCents > 0)
      .sort((a, b) => b.revenueCents - a.revenueCents)
      .map((r) => `${r.channel.toLowerCase()} ${eur0(r.revenueCents)}`)
      .join(' · ')
    return {
      key: `unattributed:${cents}:${orders}`,
      text: `${eur0(cents)} across ${orders} ${orders === 1 ? 'order' : 'orders'}`,
      why: `those order lines carry no product link (${channels})`,
    }
  }, [listMeta])

  // ── Filter bar config ──────────────────────────────────────────
  const setF = useCallback(<K extends keyof ProductFilters>(key: K, value: ProductFilters[K]) => {
    setFilters((prev) => ({ ...prev, [key]: value }))
  }, [])
  /**
   * One column filter, written into AG's model. AG then re-asks the server, fires
   * `filterChanged`, and the mirror above follows — the accordion never holds its own copy.
   */
  const setColumnFilter = useCallback(
    (colId: string, entry: GridFilterModelEntry | null) => {
      if (!gridApi) return
      const next = { ...(gridApi.getFilterModel() as GridFilterModel) }
      if (entry) next[colId] = entry
      else delete next[colId]
      gridApi.setFilterModel(next)
    },
    [gridApi],
  )
  const setValuesOf = useCallback((colId: string): string[] => {
    const m = filterModel[colId]
    return m?.filterType === 'set' ? m.values : []
  }, [filterModel])
  const rangeOf = useCallback((colId: string): { min: string; max: string } => {
    const m = filterModel[colId]
    return m?.filterType === 'number'
      ? { min: m.filter == null ? '' : String(m.filter), max: m.filterTo == null ? '' : String(m.filterTo) }
      : { min: '', max: '' }
  }, [filterModel])
  const setSetFilter = useCallback((colId: string) => (values: string[]) => setColumnFilter(colId, values.length ? { filterType: 'set', values } : null), [setColumnFilter])
  const setRangeFilter = useCallback(
    (colId: string) => (min: string, max: string) => {
      const num = (s: string) => (s.trim() === '' ? null : Number.isFinite(Number(s)) ? Number(s) : null)
      const filter = num(min)
      const filterTo = num(max)
      setColumnFilter(colId, filter == null && filterTo == null ? null : { filterType: 'number', type: 'inRange', filter, filterTo })
    },
    [setColumnFilter],
  )

  // The search box IS the Product column's text filter, debounced so a keystroke is not a
  // request. In the LIVE model AG keys it by its own auto-column id; the wire says `product`.
  const searchModel = filterModel[AG_AUTO_COL]
  const searchApplied = searchModel?.filterType === 'text' ? searchModel.filter : ''
  const [searchDraft, setSearchDraft] = useState('')
  const searchDirty = useRef(false)
  useEffect(() => {
    if (!searchDirty.current) setSearchDraft(searchApplied)
  }, [searchApplied])
  useEffect(() => {
    if (!searchDirty.current) return
    const t = setTimeout(() => {
      searchDirty.current = false
      const v = searchDraft.trim()
      setColumnFilter(AG_AUTO_COL, v ? { filterType: 'text', type: 'contains', filter: v } : null)
    }, 250)
    return () => clearTimeout(t)
  }, [searchDraft, setColumnFilter])

  const activeFilterCount = useMemo(() => {
    const f = filters
    // Every column filter except the Product search, which has its own box, plus the page's own.
    const columnFilters = Object.keys(filterModel).filter((k) => k !== AG_AUTO_COL && k !== 'product').length
    return columnFilters + f.stock.length + f.fulfillment.length + f.families.length + f.workflowStages.length + f.missingChannels.length
  }, [filters, filterModel])

  /**
   * Export the QUERY, not the viewport.
   *
   * The columns are the ones on screen, in the operator's order, read from the grid — so the
   * Customise dialog decides the file too. The VALUES are `pageColumnExportValue`, which is the
   * cell's own `valueGetter` unless the column declares an `exportValue` — a renderer-drawn column
   * (Product, Channels, Tags) has no scalar to write, and said so by exporting blank until it did. The ROWS are re-asked of the server for the whole
   * filtered scope; AG's own exporter would have written only the blocks it had loaded, plus the
   * family-footer sentinels this page injects for layout.
   */
  const [exporting, setExporting] = useState(false)
  const runExport = useCallback(async () => {
    if (!gridApi || gridApi.isDestroyed()) return
    setExporting(true)
    try {
      const byKey = new Map(columns.map((c) => [c.key, c]))
      const csvColumns = gridApi
        .getAllDisplayedColumns()
        .map((col): CsvColumn<ProductRow> | null => {
          // AG names the tree column `ag-Grid-AutoColumn`; the page knows it as `product`.
          const key = col.getColId() === AG_AUTO_COL ? 'product' : col.getColId()
          const c = byKey.get(key)
          // `actions` is a button, and a selection checkbox is not data.
          if (!c || key === 'actions') return null
          return { header: columnLabel(c), value: (row: ProductRow) => pageColumnExportValue(c, row) }
        })
        .filter((c): c is CsvColumn<ProductRow> => c !== null)

      const { rows, total, truncated } = await fetchAllRowsForExport<ProductRow>({
        context: ctxRef.current,
        sortModel: gridApi.getState().sort?.sortModel ?? [],
        filterModel,
      })

      downloadCsv(
        csvFileName('products', { filtered: activeFilterCount > 0 || !!activeTile || !!searchDraft.trim() }),
        toCsv(rows, csvColumns),
      )
      if (truncated) {
        toast(`Exported the first ${rows.length.toLocaleString()} of ${total.toLocaleString()} products — narrow the filters to export the rest.`, 'warning')
      } else {
        toast(`Exported ${rows.length.toLocaleString()} product${rows.length === 1 ? '' : 's'}.`, 'success')
      }
    } catch (err) {
      toast(err instanceof Error ? err.message : 'Export failed.', 'danger')
    } finally {
      setExporting(false)
    }
  }, [gridApi, columns, filterModel, activeFilterCount, activeTile, searchDraft, toast])

  const filterDimensions = useMemo<FilterDimension[]>(() => {
    const dims: FilterDimension[] = [
      { key: 'channels', label: 'Channel', kind: 'multiselect', value: setValuesOf('channels'), onChange: setSetFilter('channels'), options: CHANNEL_OPTS },
      { key: 'status', label: 'Status', kind: 'multiselect', value: setValuesOf('status'), onChange: setSetFilter('status'), options: STATUS_OPTS },
      { key: 'stock', label: 'Stock', kind: 'multiselect', value: filters.stock, onChange: (v) => setF('stock', v), options: [{ value: 'in', label: 'In stock' }, { value: 'low', label: 'Low stock' }, { value: 'out', label: 'Out of stock' }] },
      { key: 'fulfillment', label: 'Fulfilment', kind: 'multiselect', value: filters.fulfillment, onChange: (v) => setF('fulfillment', v), options: [{ value: 'FBA', label: 'FBA' }, { value: 'FBM', label: 'FBM' }] },
    ]
    if (facetOptions.types.length)
      dims.push({ key: 'productTypes', label: 'Product type', kind: 'multiselect', value: setValuesOf('productType'), onChange: setSetFilter('productType'), options: facetOptions.types.map((t) => ({ value: t, label: t })), searchable: true })
    if (facetOptions.brands.length)
      dims.push({ key: 'brands', label: 'Brand', kind: 'multiselect', value: setValuesOf('brand'), onChange: setSetFilter('brand'), options: facetOptions.brands.map((b) => ({ value: b, label: b })), searchable: true })
    // Sourced from every tag that EXISTS, not from the tags found on loaded rows.
    if (allTags.length)
      dims.push({ key: 'tags', label: 'Tags', kind: 'multiselect', value: setValuesOf('tags'), onChange: setSetFilter('tags'), options: allTags.map((t) => ({ value: t.name, label: t.name })), searchable: true })
    if (facetOptions.families.length)
      dims.push({ key: 'families', label: 'Family', kind: 'multiselect', value: filters.families, onChange: (v) => setF('families', v), options: facetOptions.families.map(([code, label]) => ({ value: code, label })), searchable: true })
    if (facetOptions.stages.length)
      dims.push({ key: 'workflowStages', label: 'Workflow stage', kind: 'multiselect', value: filters.workflowStages, onChange: (v) => setF('workflowStages', v), options: facetOptions.stages.map(([code, label]) => ({ value: code, label })), searchable: true })
    dims.push({ key: 'missingChannels', label: 'Missing channel', kind: 'multiselect', value: filters.missingChannels, onChange: (v) => setF('missingChannels', v), options: CHANNEL_OPTS })
    dims.push({ key: 'price', label: 'Price', kind: 'range', unit: '€', ...rangeOf('price'), onChange: setRangeFilter('price') })
    dims.push({ key: 'stockUnits', label: 'Stock units', kind: 'range', ...rangeOf('available'), onChange: setRangeFilter('available') })
    return dims
  }, [filters, facetOptions, setF, allTags, setValuesOf, setSetFilter, rangeOf, setRangeFilter])

  const selectedCount = selection.ids.length

  // ── Grid options with STABLE identities ─────────────────────────
  // AgGridReact shallow-compares every prop and calls `setGridOption` for each one whose identity
  // changed. An object literal in JSX is a new identity on every render — and this page re-renders
  // on every selection change — so `rowSelection`, `selectionColumnDef` and the rest were being
  // "changed" on every tick of a checkbox, and AG re-ran its column model each time (measured:
  // `aria-colindex` rewritten on every Product cell per selection). Declared once, they change
  // only when their inputs do.
  const rowSelection = useMemo<NonNullable<ComponentProps<typeof NexusGrid<ProductRow>>['rowSelection']>>(
    () => ({
      mode: 'multiRow',
      checkboxes: true,
      headerCheckbox: true,
      enableClickSelection: false,
      // Select-all reaches what is LOADED on this page. Under SSRM the alternative — selecting every
      // row the query matches, loaded or not — is a larger promise that the bulk endpoints (capped
      // at 200) could not keep.
      selectAll: 'currentPage',
      // A group row cannot be selected, and the footer is arithmetic, not a product.
      isRowSelectable: (n) => !isGroupRow(n.data) && !isFamilyFooter(n.data),
      hideDisabledCheckboxes: true,
    }),
    [],
  )
  // The DS grid's checkbox column measures 43px; AG's default is 50.
  const selectionColumnDef = useMemo(() => ({ width: gridGeometry.selectColW, maxWidth: gridGeometry.selectColW, resizable: false }), [])
  const columnDialog = useMemo(() => ({ customise: openCustomize, reset: resetColumns }), [openCustomize, resetColumns])
  // AG's own words for the aggregate submenu; the operator sees what it does.
  const localeText = useMemo(() => ({ valueAggregation: 'Total on group rows' }), [])
  const getRowHeight = useCallback((p: { data?: ProductRow }) => (isFamilyFooter(p.data) ? FAMILY_FOOTER_PX : gridDensity[density].rowMedia), [density])
  const isFullWidthRow = useCallback((p: { rowNode: { data?: ProductRow } }) => isFamilyFooter(p.rowNode.data), [])
  // Families are a TREE the server serves lazily: a row that can expand asks for its children by
  // its own id. Tree OR groups: while a grouping is active the auto column is the group column.
  const isServerSideGroup = useCallback((d: ProductRow) => (isGroupRow(d) ? true : !grouped && !isFamilyFooter(d) && isFamilyParent(d)), [grouped])
  const getServerSideGroupKey = useCallback((d: ProductRow) => (isGroupRow(d) ? d.groupKey : d.id), [])
  const getRowId = useCallback((p: { data: ProductRow }) => p.data.id, [])
  const onFilterChanged = useCallback((e: { api: GridApi<ProductRow> }) => setFilterModelState(e.api.getFilterModel() as GridFilterModel), [])
  // A refetch replaces every `node.data`; the selection's rows are re-read so a dialog opened
  // afterwards sees what the grid shows (e.g. the tags just applied).
  const onStoreRefreshed = useCallback((e: { api: GridApi<ProductRow> }) => { if (e.api.getSelectedNodes().length || selectedCount > 0) setSelection(readSelection(e.api)) }, [selectedCount])
  const onColumnRowGroupChanged = useCallback((e: { api: GridApi<ProductRow> }) => { setGrouped(e.api.getRowGroupColumns().length > 0); syncPrefsFromGrid() }, [syncPrefsFromGrid])
  const onColumnMoved = useCallback((e: { finished: boolean }) => { if (e.finished) syncPrefsFromGrid() }, [syncPrefsFromGrid])
  /**
   * The live page opens sorted by Product ↑, with the two by-default-hidden columns hidden. A saved
   * default view or the last-used state overrides the whole thing. Initial-only.
   *
   * 🔴 The `columnVisibility` slice is not decoration (measured 2026-09-05). AG treats a state that
   * names NO column slice as a full reset of the ones it does not mention: with a sort-only state,
   * `defaultState.hide = null` is applied to every column and `initialHide` in the definitions is
   * overridden — Brand and Product type opened VISIBLE on a fresh profile, 1,699px of columns in a
   * 1,552px card. The page's own default has to say what it hides, in the same object AG reads it
   * from, and the list is derived from the registry rather than spelled out again here.
   */
  const initialState = useMemo<GridState>(
    () =>
      initialPayloadRef.current?.gridState ?? gridViews.initialState ?? {
        sort: { sortModel: [{ colId: AG_AUTO_COL, sort: 'asc' }] },
        columnVisibility: { hiddenColIds: columns.filter((c) => c.defaultHidden).map((c) => c.key) },
      },
    [gridViews.initialState, columns, layoutBootstrapped],
  )

  // ── Render ────────────────────────────────────────────────────
  return (
    <div className={styles.wrap}>
      {/* Page header. In family scope it names the FAMILY, not the catalogue — the page is the
          same grid, and the only thing that tells you which of the two you are looking at is
          this. "Import & export"/"New product" are catalogue actions and would be lies here, so the
          scoped view offers the way back instead. */}
      <PageHeader
        title={familyId ? (family?.name ?? 'Variation family') : 'Products'}
        subtitle={
          familyId
            ? `${stats?.total ?? '—'} variations${family?.sku ? ` of ${family.sku}` : ''}`
            : `${stats?.total ?? '—'} products · shared catalog`
        }
        actions={
          <div className={styles.acts}>
            {familyId ? (
              <Button asChild size="sm">
                <Link href="/products">
                  <ArrowLeft size={13} /> All products
                </Link>
              </Button>
            ) : (
              <>
                <Button asChild size="sm">
                  <Link href="/products/listing-readiness">Listing readiness</Link>
                </Button>
                <Button asChild size="sm">
                  <Link href="/products/catalog-transfer">
                    <Upload size={13} /> Import &amp; export
                  </Link>
                </Button>
                <Button size="sm" variant="primary" onClick={() => router.push('/products/new')}>
                  <Plus size={13} /> New product
                </Button>
              </>
            )}
          </div>
        }
      />

      <MetricStrip metrics={kpiMetrics} className={styles.kpis} />

      {/* Revenue the Sales column cannot show. An order line with no productId is a real sale
          that no product row can carry; without this the column silently under-reports. */}
      {unattributed && unattributed.key !== dismissedWarning && (
        <Banner tone="warning" className={styles.unattributed} onDismiss={() => dismissWarning(unattributed.key)}>
          {unattributed.text} not shown in Sales — {unattributed.why}
        </Banner>
      )}

      <div className={styles.filterBar}>
        <FilterBar
          dimensions={filterDimensions}
          activeCount={activeFilterCount}
          onClear={() => {
            setFilters(EMPTY_FILTERS)
            // Column filters clear too; the search box is not an accordion filter and stays.
            const keep = gridApi?.getFilterModel()[AG_AUTO_COL]
            gridApi?.setFilterModel(keep ? { [AG_AUTO_COL]: keep } : null)
          }}
        />
      </div>

      {unsupported.length > 0 && (
        <Banner tone="warning" className={styles.unattributed}>
          Not applied by the server: {unsupported.map((u) => u.replace(':', ' ')).join(', ')} — the rows above
          are wider than the filters you set.
        </Banner>
      )}

      {(workingState.error || gridViews.loadError) && (
        <Banner tone="warning" className={styles.unattributed}>
          {workingState.error || gridViews.loadError}{' '}
          <Button size="sm" variant="link" onClick={() => void reloadSavedPreferences().catch(() => {})}>Reload saved layout</Button>
        </Banner>
      )}

      {/* One card: toolbar + grid + pager share the grid rectangle (Ad-Manager parity). The grid
          is exactly as tall as the page of rows the footer selects — 50, 100, 200 or 500 — and
          the PAGE scrolls, as Seller Central's and Ad Manager's tables do. Expand a family and
          the page gets longer. Owner decision, stated twice (PN.6, PN.9): the grid is never
          bounded to the viewport with a scrollbar of its own. */}
      <div className="nds-gridcard nds-grid-card">
        <GridToolbar
          count={
            selectedCount > 0 ? (
              <>
                Selected <b>{selectedCount}</b> {selectedCount === 1 ? 'product' : 'products'}
                {selectionReach > 0 && (
                  <SelectionNote>
                    {' · '}actions also reach <b>{selectionReach}</b>{' '}
                    {selectionReach === 1 ? 'variation' : 'variations'}
                  </SelectionNote>
                )}
              </>
            ) : familyId ? (
              <><b>{totalCount ?? '—'}</b> variations</>
            ) : grouped ? (
              <><b>{totalCount ?? '—'}</b> {totalCount === 1 ? 'group' : 'groups'} · <b>{stats?.total ?? '—'}</b> products</>
            ) : (
              <><b>{totalCount ?? '—'}</b> products</>
            )
          }
          right={
            <>
              {/* Density steps aside while rows are selected: the bulk actions need the room. */}
              {selectedCount === 0 && (
                <GridDensityToggle value={density} onChange={setDensity} />
              )}
              <Button size="sm" onClick={openCustomize} disabled={!gridApi || !layoutBootstrapped}>
                <SlidersHorizontal size={13} /> Customise
              </Button>
              <GridViewsMenu
                views={{ ...gridViews, apply: applyNamedView }}
                onNewView={openCustomize}
                onSaveCurrent={(name) => saveLayout(currentPreferences(), { name })}
                onUpdateCurrent={(view) => saveLayout(currentPreferences(), { name: view.name, view })}
              />
              <Button size="sm" onClick={() => void runExport()} disabled={!gridApi || !totalCount || exporting} title="Download the filtered product table as CSV. Use Import & export for an editable catalog workbook.">
                <Download size={13} /> {exporting ? 'Exporting…' : 'Export table'}
              </Button>
              <Pill tone={error ? 'danger' : 'success'} dot size="md">
                {error ? 'Not syncing' : loading ? 'Syncing…' : 'Live'}
              </Pill>
            </>
          }
        >
          {selectedCount > 0 ? (
            <GridSelectionActions>
              <Button size="sm" variant="primary" disabled={busy} onClick={() => setBulkEditOpen(true)}>
                <SlidersHorizontal size={13} /> <SelectionLabel>Bulk edit</SelectionLabel>
              </Button>
              <Button size="sm" disabled={busy} onClick={() => setTagDialogOpen(true)} title="Tag">
                <TagIcon size={13} /> <SelectionLabel>Tag</SelectionLabel>
              </Button>
              <Button size="sm" disabled={busy} onClick={() => duplicateBulk(selection.ids)} title="Duplicate">
                <Copy size={13} /> <SelectionLabel>Duplicate</SelectionLabel>
              </Button>
              {confirmDelete ? (
                <Button size="sm" variant="danger" disabled={busy} onClick={() => { setConfirmDelete(false); void softDeleteBulk(selection.ids) }}>
                  Delete {selectedCount + selectionReach}
                </Button>
              ) : (
                <Button size="sm" disabled={busy} onClick={() => setConfirmDelete(true)} title="Delete">
                  <Trash2 size={13} /> <SelectionLabel>Delete</SelectionLabel>
                </Button>
              )}
              <Menu
                label={<MoreHorizontal size={15} />}
                items={moreActionItems}
                align="right"
                triggerProps={{ className: 'nds-btn sm', disabled: busy, 'aria-label': 'More bulk actions' }}
              />
              <Button variant="link" size="sm" onClick={clearSelection}>
                Clear
              </Button>
            </GridSelectionActions>
          ) : (
            <GridSearchSlot>
              <Input
                leadingIcon={<Search size={13} style={{ color: 'var(--nds-text-3)' }} />}
                placeholder="Search products…"
                value={searchDraft}
                onChange={(e) => { searchDirty.current = true; setSearchDraft(e.target.value) }}
                style={{ width: '100%' }}
              />
            </GridSearchSlot>
          )}
        </GridToolbar>

        {/* GridDensityProvider: the grid, the DS Thumbnail and the inventory editor all follow this
            one density (compact 32 / cozy 40 / spacious 56 thumbs; rows 52 / 68 / 85). */}
        <GridDensityProvider value={density}>
          {!layoutBootstrapped ? <div role="status">Loading your saved layout…</div> : error ? (
            // A failed fetch is NOT an empty catalogue and NOT a slow one.
            <EmptyState
              icon={<AlertTriangle size={20} />}
              title="Couldn't load products"
              description={error}
              action={
                <Button size="sm" variant="secondary" onClick={() => void refetch()}>
                  Try again
                </Button>
              }
            />
          ) : (
            <>
              <NexusGrid<ProductRow>
                // The grid sizes itself to its rows (the current page of them, under pagination)
                // and hands scrolling to the page. Rows are rendered per page, not per screen —
                // the cost of a 500-row page is 500 rows, which is the trade the footer offers.
                getContextMenuItems={getContextMenuItems}
                domLayout="autoHeight"
                density={density}
                rows="media"
                getRowHeight={getRowHeight}
                isFullWidthRow={isFullWidthRow}
                fullWidthCellRenderer={FamilyFooter}
                pagination
                paginationPageSize={pageSize}
                // The footer below is the page-size control; AG's own selector is off.
                paginationPageSizeSelector={false}
                suppressPaginationPanel
                onPaginationChanged={onPaginationChanged}
                rowModelType="serverSide"
                serverSideDatasource={datasource}
                cacheBlockSize={BLOCK_SIZE}
                getRowId={getRowId}
                onGridReady={onGridReady}
                treeData={!grouped}
                // The DS tint + rail on child rows; the cell itself decides the indent.
                flatTree={!grouped}
                isServerSideGroup={isServerSideGroup}
                getServerSideGroupKey={getServerSideGroupKey}
                // Header text stays the column's name; the aggregate is chosen in Customise.
                suppressAggFuncInHeader
                onColumnRowGroupChanged={onColumnRowGroupChanged}
                onColumnValueChanged={syncPrefsFromGrid}
                onColumnMoved={onColumnMoved}
                onColumnVisible={syncPrefsFromGrid}
                // A pin IS a lock (the lock contract). Pin a column from the header menu, or drag
                // one into the frozen area, and the padlock is on it in Customise — the same set
                // the saved views carry. Without this the grid and the dialog disagree silently.
                onColumnPinned={syncPrefsFromGrid}
                /**
                 * 🔴 A COLUMN-DEFINITION SWEEP MUST NOT REORDER THE GRID (measured 2026-09-05).
                 *
                 * AG's default is `maintainColumnOrder: false`, which means "when new column
                 * definitions arrive, put the columns back in the definitions' order" — and this
                 * page re-derives `columnDefs` whenever the lock set, the channel roster or the
                 * filter facets move. Measured: unlock Price in Customise and the engine correctly
                 * applied it back to the front of the scrolling band, then the definition sweep in
                 * the very next render dropped it at its declared position instead. Every column
                 * the operator had dragged went with it, and locking anything was enough to do it.
                 *
                 * The order belongs to the operator and to the engine's `applyOrder`, not to the
                 * order this file happens to declare its columns in. "Reset columns" still restores
                 * the default order — it applies it explicitly.
                 */
                maintainColumnOrder
                localeText={localeText}
                autoGroupColumnDef={autoGroupColumnDef}
                columnDefs={colDefs}
                columnDialog={columnDialog}
                selectionColumnDef={selectionColumnDef}
                rowSelection={rowSelection}
                onFilterChanged={onFilterChanged}
                onSelectionChanged={onSelectionChanged}
                onStoreRefreshed={onStoreRefreshed}
                initialState={initialState}
                loadingOverlayComponent={ProductsSkeleton}
                overlayNoRowsTemplate={NO_ROWS_TEMPLATE}
              />
              {/* The footer as Ad Manager's: pages on the left of the control, rows per page on the right. */}
              <GridPager page={pager.page} pageCount={pager.pageCount} pageSize={pageSize} onPage={onPage} onPageSize={onPageSize} />
            </>
          )}
        </GridDensityProvider>
      </div>

      {/* Customise — the DS dialog over AG's column state (see openCustomize). */}
      {prefsDraft && (
        <PreferencesModal
          open={customizeOpen}
          onClose={() => setCustomizeOpen(false)}
          title="Customise columns"
          value={prefsDraft}
          onConfirm={confirmCustomize}
          allColumns={preferenceColumns}
          attributeGroups
          groupToggles
          inViewCount
          onReloadSaved={reloadSavedPreferences}
          listHint="Organise columns into groups and choose their order. Save keeps your personal products layout after a reload."
          viewSave={{
            activeName: activeSavedView?.name ?? null,
            onSaveAs: (name, draft) => saveLayout(draft, { name }),
            onUpdate: activeSavedView ? (draft) => saveLayout(draft, { name: activeSavedView.name, view: activeSavedView }) : undefined,
          }}
          defaultVisible={defaultPrefs.visibleColumns}
          groupByOptions={columns.filter((c) => c.groupable).map((c) => ({ key: c.key, label: columnLabel(c) }))}
          aggregationOptions={columns.filter((c) => c.aggregate).map((c) => ({ key: c.key, label: columnLabel(c), funcs: c.aggregate! }))}
          // Headers sort, the footer sets rows per page, sticky is off: no Display tab here.
          sortFieldOptions={[]}
          pageSizeChoices={[]}
          showSticky={false}
        />
      )}

      <BulkEditModal open={bulkEditOpen} onClose={() => setBulkEditOpen(false)} selection={selection.rows} busy={busy} onSubmit={applyBulkEdit} />

      {/* Tag dialog — the selection's tags, tri-state across the rows it covers. */}
      <TagDialog
        open={tagDialogOpen}
        onClose={() => setTagDialogOpen(false)}
        selection={selection.rows}
        allTags={allTags}
        onTagsChanged={refreshTags}
        onApplied={({ added, removed, products: n }) => {
          const bits = [added ? `+${added}` : '', removed ? `−${removed}` : ''].filter(Boolean).join(' ')
          toast(`${bits} on ${n} ${n === 1 ? 'product' : 'products'}`, 'success')
          emitInvalidation({ type: 'product.updated', meta: { productIds: selection.ids, source: 'bulk-tag' } })
          refreshTags()
        }}
      />

      {/* Inventory editor modal — opened by clicking the Available cell */}
      <InventoryEditorModal row={modalRow} density={density} onClose={() => setModalRow(null)} />
    </div>
  )
}

