'use client'

/**
 * /products/next — the page's column registry, on the GDS cell library.
 *
 * The page owns its column IDS, labels, widths, groups and what each column's VALUE is (including
 * the aggregate a group row carries). The CELL — how a money, a date, a status, a tag list, an
 * actions cluster is drawn, and what a null looks like next to a measured zero — is the design
 * system's (`design-system/grid/renderers`, `columns/presets`). Two cells stay page-specific
 * because they are the page: the product identity cell (expander + family link) and the Available
 * cell (the button that opens the inventory editor).
 */
import type { ReactNode } from 'react'
import { ExternalLink } from 'lucide-react'

import type { ProductRow } from '@/app/products/_types'
import { Tag, type Tone } from '@/design-system/primitives'
import type { CoverageChannel, MenuItemDef } from '@/design-system/components'
import {
  CoverageCell,
  ExpandButton,
  ExpandSlot,
  IdentityCell,
  NumericCell,
  SkuTag,
  TagsCell,
  actionsColumn,
  dateColumn,
  euroColumn,
  integerColumn,
  moneyColumn,
  statusColumn,
  textColumn,
  type ColDef,
  type ICellRendererParams,
} from '@/design-system/grid'
import { NULL_GROUP_KEY, type AggFunc, type ProductGroupRow } from './productsServerContract'
export type { ProductGroupRow }

import styles from './styles.module.css'
import { InventoryCell } from './InventoryCell'
import { TRAIL_COLUMN } from './columnLocks'

export const SALES_WINDOW_DAYS = 7

export const CHANNELS = ['AMAZON', 'EBAY', 'SHOPIFY', 'ETSY'] as const
export type Channel = (typeof CHANNELS)[number]

export const CHANNEL_OPTS = [
  { value: 'AMAZON', label: 'Amazon' },
  { value: 'EBAY', label: 'eBay' },
  { value: 'SHOPIFY', label: 'Shopify' },
  { value: 'ETSY', label: 'Etsy' },
]

export const STATUS_OPTS = [
  { value: 'ACTIVE', label: 'Active' },
  { value: 'DRAFT', label: 'Draft' },
  { value: 'INACTIVE', label: 'Inactive' },
]

const STATUS_TONES: Record<string, { tone: Tone; label: string }> = {
  ACTIVE: { tone: 'success', label: 'Active' },
  DRAFT: { tone: 'neutral', label: 'Draft' },
  INACTIVE: { tone: 'danger', label: 'Inactive' },
}

export interface PageColumn {
  key: string
  label: ReactNode
  prefsLabel?: string
  group?: string
  /** Stable presentation group ID, independent of the displayed label. */
  groupKey?: string
  width?: number
  sortable?: boolean
  defaultHidden?: boolean
  groupable?: boolean
  aggregate?: readonly AggFunc[]
  /** The value AG sorts, aggregates and hands the cell (a data row). Default: the `field`. */
  value?: (row: ProductRow) => unknown
  /** The aggregate a GROUP row carries for this column. */
  groupValue?: (g: ProductGroupRow) => unknown
  /** The DS cell: a preset's renderer + alignment. */
  preset?: Partial<ColDef<ProductRow>>
  /** A page-specific DATA cell; group rows still go through `preset`/`groupValue`. */
  render?: (row: ProductRow) => ReactNode
  /**
   * The CSV value, when the cell's own value is not a scalar.
   *
   * A column drawn by a renderer either carries no `value` at all (Product: the cell IS the
   * renderer) or carries a shape the renderer understands (Channels: `CoverageChannel[]`, Tags:
   * a tag array). Neither has an honest CSV form, and `csvField` writes an object as empty rather
   * than inventing "[object Object]" — measured 2026-08-31: Product, Channels and Tags all
   * exported blank. This is where such a column says what it means in a file.
   */
  exportValue?: (row: ProductRow) => string | number | null
}

export const isGroupRow = (d: unknown): d is ProductGroupRow =>
  !!d && typeof d === 'object' && (d as { __group?: boolean }).__group === true

export { STRUCTURAL_COLUMNS, isStructuralColumn, composeLocks, structuralPinState, withStructuralLocks } from './columnLocks'

/** The server's aggregate field per column — the `valueCols` AG sends under a grouping. */
const GROUP_FIELD: Record<string, string> = { available: 'totalStock', price: 'basePrice', sales: 'sales.revenueCents', units: 'sales.units' }

/**
 * A column's value for a DATA row — the one definition the grid's `valueGetter` and the CSV export
 * both read. Exported because a second implementation is how an export starts disagreeing with the
 * screen: coverage roll-ups, channel states and variation counts live in `c.value`, and nothing
 * else can re-derive them without becoming a copy that drifts.
 */
export const pageColumnField = (c: PageColumn): string => (c.preset?.field as string | undefined) ?? GROUP_FIELD[c.key] ?? c.key

export const readField = (field: string, row: unknown): unknown =>
  field.split('.').reduce<unknown>((o, k) => (o && typeof o === 'object' ? (o as Record<string, unknown>)[k] : undefined), row)

export const pageColumnValue = (c: PageColumn, row: ProductRow): unknown =>
  c.value ? c.value(row) : readField(pageColumnField(c), row)

/** What the CSV writes: a column's own `exportValue` when it has one, else what the grid shows. */
export const pageColumnExportValue = (c: PageColumn, row: ProductRow): unknown =>
  c.exportValue ? c.exportValue(row) : pageColumnValue(c, row)

/** Channels, as the cell reads it — the same counts `CoverageSummary` draws, in the same order. */
export function coverageText(channels: readonly CoverageChannel[]): string {
  const count = (s: CoverageChannel['state']) => channels.filter((c) => c.state === s).length
  const parts: string[] = []
  const live = count('live')
  const issues = count('issues')
  const draft = count('draft')
  if (live > 0) parts.push(`${live} live`)
  if (issues > 0) parts.push(`${issues} ${issues === 1 ? 'issue' : 'issues'}`)
  if (draft > 0) parts.push(`${draft} draft`)
  return parts.length ? parts.join(' \u00b7 ') : 'Not listed'
}

export function groupRowLabel(g: ProductGroupRow, columns: readonly PageColumn[]): string {
  const col = columns.find((c) => c.key === g.groupColId)
  if (g.groupKey === NULL_GROUP_KEY) return `No ${(col?.prefsLabel ?? g.groupColId).toLowerCase()}`
  if (g.groupColId === 'status') return STATUS_OPTS.find((o) => o.value === g.groupKey)?.label ?? g.groupKey
  return g.groupKey
}

function channelsOf(row: ProductRow, activeChannels: readonly string[]): CoverageChannel[] {
  return activeChannels.map((ch) => {
    const cov = row.coverage?.[ch as Channel] ?? null
    if (!cov || cov.total === 0) return { channel: ch, state: 'missing' as const, detail: 'not listed' }
    if (cov.error > 0) return { channel: ch, state: 'issues' as const, detail: `${cov.error} error${cov.error > 1 ? 's' : ''}` }
    if (cov.live > 0) return { channel: ch, state: 'live' as const, detail: `${cov.live} live` }
    if (cov.draft > 0) return { channel: ch, state: 'draft' as const, detail: `${cov.draft} draft` }
    return { channel: ch, state: 'missing' as const, detail: 'not listed' }
  })
}

export function variationCount(row: ProductRow): number {
  return row.childCount ?? 0
}

export const familyHref = (parentId: string) => `/products?parent=${encodeURIComponent(parentId)}`
const editHref = (row: ProductRow) => `/products/${row.id}/edit/studio`

/**
 * What you can do to one product — the ONE list.
 *
 * The `⋯` column and the right-click context menu offer the same actions, so they read the same
 * list rather than each declaring its own. Two menus that agree today and drift tomorrow is the
 * shape of defect this file has already been bitten by: `MultiSelect` and `GridSetFilter` shared a
 * stylesheet and diverged in behaviour, and no guard could see it.
 *
 * Labels are plain strings on purpose. AG's context menu takes `name: string`, so a ReactNode label
 * would render as nothing there while looking correct in the DS menu.
 */
export function rowActions(row: ProductRow, deps: Pick<ColumnDeps, 'onDuplicate' | 'navigate'>): MenuItemDef[] {
  return [
    { id: 'edit', label: 'Edit', onSelect: () => deps.navigate(editHref(row)) },
    { id: 'duplicate', label: 'Duplicate', onSelect: () => deps.onDuplicate(row.id) },
    { id: 'open-new', label: 'Open in new tab', onSelect: () => window.open(editHref(row), '_blank') },
  ]
}

export interface ProductCellProps {
  row: ProductRow
  isChild?: boolean
  hasChildren?: boolean
  isExpanded?: boolean
  onExpand?: () => void
}

/** The identity cell: expander · photo · title (same-tab link, hover "Open" pill) · SKU · type · family link. */
export function ProductCell({ row, isChild, hasChildren, isExpanded, onExpand }: ProductCellProps) {
  const n = variationCount(row)
  return (
    <IdentityCell
      leading={
        hasChildren ? (
          <ExpandButton expanded={!!isExpanded} onToggle={() => onExpand?.()} labels={['Expand variations', 'Collapse variations']} />
        ) : (
          <ExpandSlot />
        )
      }
      image={row.imageUrl}
      photoCount={row.photoCount}
      title={row.name}
      titleAttr={row.name}
      href={editHref(row)}
      openPill
      sub={
        <>
          <SkuTag>{row.sku}</SkuTag>
          {row.productType && <Tag>{row.productType}</Tag>}
          {/* The count is the way to the family page — the same grid scoped to this family, paged
              and sorted like the catalogue. It opens in a new tab so the place in this list is kept. */}
          {!isChild && n > 0 && (
            <a
              className={styles.varCount}
              href={familyHref(row.id)}
              target="_blank"
              rel="noopener noreferrer"
              title="Open this family as its own page (new tab)"
              onClick={(e) => e.stopPropagation()}
            >
              {n} {n === 1 ? 'variation' : 'variations'} <ExternalLink size={10} aria-hidden />
            </a>
          )}
        </>
      }
    />
  )
}

export interface ColumnDeps {
  activeChannels: readonly string[]
  onDuplicate: (id: string) => void
  onOpenInventory: (row: ProductRow) => void
  /** Same-tab navigation for the row menu's Edit. */
  navigate: (href: string) => void
}

export function buildPageColumns({ activeChannels, onDuplicate, onOpenInventory, navigate }: ColumnDeps): PageColumn[] {
  const productCol: PageColumn = {
    key: 'product',
    groupKey: 'products-next:identity', group: 'Identity',
    label: 'Product',
    sortable: true,
    render: (row) => <ProductCell row={row} isChild={row.parentId !== null} />,
    exportValue: (row) => row.name,
  }
  const brandCol: PageColumn = { key: 'brand', groupKey: 'products-next:identity', group: 'Identity', label: 'Brand', width: 140, sortable: true, defaultHidden: true, groupable: true, preset: textColumn('brand') }
  const productTypeCol: PageColumn = { key: 'productType', groupKey: 'products-next:identity', group: 'Identity', label: 'Product type', width: 150, sortable: true, defaultHidden: true, groupable: true, preset: textColumn('productType') }
  const actionsCol: PageColumn = {
    key: 'actions',
    groupKey: 'products-next:meta', group: 'Meta',
    label: '',
    prefsLabel: 'Actions',
    width: 120,
    preset: actionsColumn<ProductRow>({
      primary: { label: 'Edit', href: editHref },
      items: (row) => rowActions(row, { onDuplicate, navigate }),
      menuLabel: (row) => `More actions for ${row.name}`,
    }),
  }
  const noSalesTitle = (data: unknown) => `No sales in the last ${(data as ProductRow | undefined)?.sales?.days ?? SALES_WINDOW_DAYS} days`
  const noUnitsTitle = (data: unknown) => `No units sold in the last ${(data as ProductRow | undefined)?.sales?.days ?? SALES_WINDOW_DAYS} days`
  const movable: PageColumn[] = [
    {
      key: 'channels',
      groupKey: 'products-next:identity', group: 'Identity',
      label: 'Channels',
      width: 130,
      value: (row) => channelsOf(row, activeChannels),
      exportValue: (row) => coverageText(channelsOf(row, activeChannels)),
      preset: { cellClass: 'nds-ag-cell', cellRenderer: CoverageCell },
    },
    { key: 'status', groupable: true, groupKey: 'products-next:identity', group: 'Identity', label: 'Status', width: 96, sortable: true, preset: statusColumn('status', { tones: STATUS_TONES }) },
    { key: 'tags', groupKey: 'products-next:identity', group: 'Identity', label: 'Tags', width: 150, value: (row) => row.tags ?? [], exportValue: (row) => (row.tags ?? []).map((t) => t.name).join(', '), preset: { cellClass: 'nds-ag-cell', cellRenderer: TagsCell } },
    {
      key: 'available',
      aggregate: ['sum', 'avg', 'min', 'max'],
      groupKey: 'products-next:inventory', group: 'Inventory',
      label: 'Available',
      width: 120,
      sortable: true,
      groupValue: (g) => g.totalStock ?? null,
      /**
       * Mirror the CELL, which is the only thing the operator saw: FBA + FBM when the row carries a
       * split, else the units total.
       *
       * `totalStock` is the same number now — the API row carries the stock-level roll-up (self plus
       * EVERY variation, not the ten previewed) rather than the stale `Product.totalStock` column,
       * which read 0 on prod rows holding 105 and 16 FBM units. This still mirrors the cell rather
       * than reading the field, because the cell is what the file promises to reproduce.
       */
      exportValue: (row) =>
        row.fbaStock != null || row.fbmStock != null ? (row.fbaStock ?? 0) + (row.fbmStock ?? 0) : row.totalStock,
      preset: { cellClass: 'nds-ag-cell' },
      render: (row) => <InventoryCell row={row} onOpen={onOpenInventory} />,
    },
    {
      key: 'sales',
      aggregate: ['sum', 'avg', 'min', 'max'],
      groupKey: 'products-next:commerce', group: 'Commerce',
      label: `Sales (${SALES_WINDOW_DAYS}d)`,
      prefsLabel: 'Sales',
      width: 110,
      sortable: true,
      value: (row) => row.sales?.revenueCents ?? null,
      // CENTS on the wire, euros on screen (`moneyColumn`). Without this the file says 15900 where
      // the grid says €159.00 — the unit trap this codebase has been bitten by before.
      exportValue: (row) => (row.sales?.revenueCents == null ? null : row.sales.revenueCents / 100),
      groupValue: (g) => g.sales?.revenueCents ?? null,
      preset: moneyColumn<ProductRow>('sales.revenueCents', { zero: 'dash', zeroTitle: noSalesTitle }),
    },
    {
      key: 'units',
      aggregate: ['sum', 'avg', 'min', 'max'],
      groupKey: 'products-next:commerce', group: 'Commerce',
      label: `Units (${SALES_WINDOW_DAYS}d)`,
      prefsLabel: 'Units',
      width: 92,
      sortable: true,
      value: (row) => row.sales?.units ?? null,
      groupValue: (g) => g.units ?? null,
      preset: integerColumn<ProductRow>('sales.units', { zero: 'dash', zeroTitle: noUnitsTitle }),
    },
    {
      key: 'price',
      aggregate: ['avg', 'min', 'max', 'sum'],
      groupKey: 'products-next:commerce', group: 'Commerce',
      label: 'Price',
      width: 96,
      sortable: true,
      groupValue: (g) => g.basePrice ?? null,
      preset: euroColumn<ProductRow>('basePrice'),
    },
    { key: 'updated', groupKey: 'products-next:meta', group: 'Meta', label: 'Last updated', width: 132, sortable: true, preset: dateColumn<ProductRow>('updatedAt') },
  ]
  return [productCol, ...movable, brandCol, productTypeCol, actionsCol]
}

export const columnLabel = (c: PageColumn): string => c.prefsLabel ?? (typeof c.label === 'string' ? c.label : c.key)

/** A group row's aggregate, drawn as the column's number. */
function GroupAggregate(p: ICellRendererParams<ProductRow>) {
  return <NumericCell {...p} kind="integer" />
}

export function projectColDefs(
  columns: readonly PageColumn[],
  opts: { lockedColumns: readonly string[]; filterDefFor: (key: string) => Partial<ColDef<ProductRow>> },
): ColDef<ProductRow>[] {
  const locked = (key: string) => opts.lockedColumns.includes(key)
  return columns
    .filter((c) => c.key !== 'product')
    .map((c) => {
      // Resolved once per column, not per cell: this runs inside a valueGetter on every render.
      const field = pageColumnField(c)
      const byField = (row: ProductRow): unknown => readField(field, row)
      const def: ColDef<ProductRow> = {
        ...c.preset,
        colId: c.key,
        headerName: columnLabel(c),
        width: c.width,
        sortable: !!c.sortable,
        // The operator's padlock, not the preset's: a locked column cannot move or hide.
        lockVisible: locked(c.key),
        suppressMovable: locked(c.key),
        /**
         * 🔴 The PIN is the ENGINE's, with ONE exception: this column.
         *
         * `prefsToColumnState` states `pinned` for every togglable column, so nothing here may
         * state a pin that would contradict it — a colDef `pinned` is re-applied out of the
         * definition on every `columnDefs` update (AG `reapplyColDef` → `updateSomeColumnState`),
         * which beats any column state applied before it. `actions` is the exception because its
         * `pinned: 'right'` and `lockPinned: true` come from the DS `actionsColumn` preset as
         * CONSTANTS: left alone they re-pin and re-freeze the column the operator has just
         * unlocked. Stated from the lock instead, the definition and the engine say the same thing.
         *
         * `lockPinned` follows the lock and only on the structural pair: it is what removes "Pin
         * column" from a structural column's header menu (AG hides the item when every column in
         * it is `lockPinned`), and leaving it on an unlocked column would refuse the operator a pin
         * the dialog had just released. It does NOT protect a pin from `applyColumnState` — AG
         * checks it for drags and the menu only — which is why the page re-asserts the structural
         * pins itself (`structuralPinState`).
         */
        ...(c.key === TRAIL_COLUMN
          ? {
              pinned: locked(c.key) ? ('right' as const) : null,
              lockPinned: locked(c.key),
              lockPosition: locked(c.key) ? ('right' as const) : undefined,
            }
          : {}),
        /**
         * 🔴 `initialHide`, not `hide` — measured 2026-09-05, and it is a defect on its own.
         *
         * `hide` is a STATE property, and AG re-applies the state properties of a definition on
         * every `columnDefs` update (`reapplyColDef` → `updateSomeColumnState`, whenever the array
         * came from the caller). This page re-derives `columnDefs` whenever the lock set, the
         * channel roster or the filter facets move — the facets land one to three seconds after
         * load — so `hide: true` re-hid Brand and Product type behind the operator's back: ticking
         * either in Customise put its row in "In view", applied a column state that showed it, and
         * the very next definition sweep hid it again. Measured on the live page: after Save the
         * header held 11 columns and neither was among them.
         *
         * `initialHide` says the same thing at column CREATION and never again, which is what
         * "hidden by default" means. Nothing else depended on the re-application: "Reset columns"
         * hides them explicitly through the engine (`prefsToColumnState`).
         */
        initialHide: c.defaultHidden || undefined,
        field: field as ColDef<ProductRow>['field'],
        enableRowGroup: !!c.groupable,
        enableValue: !!c.aggregate,
        allowedAggFuncs: c.aggregate ? [...c.aggregate] : undefined,
        valueGetter: (p) => (!p.data ? null : isGroupRow(p.data) ? (c.groupValue ? c.groupValue(p.data) : null) : c.value ? c.value(p.data) : byField(p.data)),
        ...opts.filterDefFor(c.key),
      }
      if (c.render) {
        const render = c.render
        def.cellRenderer = (p: ICellRendererParams<ProductRow>) => (!p.data ? null : isGroupRow(p.data) ? <GroupAggregate {...p} /> : render(p.data))
      }
      return def
    })
}

// apps/web/src/app/products/next/inventoryEditor.logic.ts
//
// The inventory editor's pure model: what a row is, which locations may be edited, how a set of
// PENDING edits sits over the server's numbers, and what the totals row says. Everything the
// grid and the modal compute is here, so it is tested rather than trusted.

/** Location types whose stock we never let the operator edit from the grid. */
export const READONLY_LOCATION_TYPES = new Set(['AMAZON_FBA', 'SHOPIFY_LOCATION'])

export function isLocationEditable(type: string): boolean {
  return !READONLY_LOCATION_TYPES.has(type)
}

export const REASON_OPTIONS = [
  { value: 'MANUAL_ADJUSTMENT', label: 'Manual adjustment' },
  { value: 'INVENTORY_COUNT', label: 'Inventory count' },
  { value: 'WRITE_OFF', label: 'Write-off / damage' },
] as const

export const DEFAULT_REASON = 'MANUAL_ADJUSTMENT'

/** The products grid's own threshold when a row does not carry one. */
export const DEFAULT_LOW_STOCK_THRESHOLD = 10

/** Low-stock → status color token; mirrors the grid cell coloring. */
export function getStockColor(qty: number, threshold: number): string {
  if (qty === 0) return 'var(--nds-danger)'
  if (qty <= threshold) return 'var(--nds-warning)'
  return 'var(--nds-success)'
}

/** Low-stock as a WORD, for a class name rather than a colour. */
export function stockLevelOf(qty: number, threshold: number): 'out' | 'low' | 'ok' {
  if (qty === 0) return 'out'
  if (qty <= threshold) return 'low'
  return 'ok'
}

export type SyncStatus = 'SYNCED' | 'PENDING' | 'FAILED'

export interface LevelCell {
  quantity: number
  reserved: number
  available: number
  syncStatus?: SyncStatus | null
}

export interface RawLocation {
  id: string
  code: string
  name: string
  type: string
}

export interface RawListLevel {
  location: { id: string; code: string; name: string; type: string }
  quantity: number
  reserved: number
  available: number
  syncStatus?: string | null
}

export interface RawFamilyChildLevel {
  locationId: string
  locationCode: string
  locationType: string
  quantity: number
  reserved: number
  available: number
  syncStatus?: string | null
}
export interface RawFamilyChild {
  id: string
  sku: string
  name: string
  thumbnailUrl: string | null
  lowStockThreshold?: number | null
  stockLevels: RawFamilyChildLevel[]
}

export interface MatrixColumn {
  locationId: string
  locationCode: string
  locationName: string
  locationType: string
  editable: boolean
}
export interface MatrixRow {
  productId: string
  sku: string
  name: string
  thumbnailUrl: string | null
  lowStockThreshold: number
  cells: Record<string, LevelCell>
}
/** ONE shape for both cases: a family's variations, or a single product as a one-row family. */
export interface MatrixModel {
  columns: MatrixColumn[]
  rows: MatrixRow[]
}

const asSync = (s: string | null | undefined): SyncStatus | null =>
  s === 'SYNCED' || s === 'PENDING' || s === 'FAILED' ? s : null

const column = (loc: RawLocation): MatrixColumn => ({
  locationId: loc.id,
  locationCode: loc.code,
  locationName: loc.name,
  locationType: loc.type,
  editable: isLocationEditable(loc.type),
})

/** A family: child products (variations) as rows × active locations as columns. */
export function buildMatrixModel(locations: RawLocation[], children: RawFamilyChild[]): MatrixModel {
  const columns = locations.map(column)
  const rows = children.map((c) => {
    const cells: MatrixRow['cells'] = {}
    for (const sl of c.stockLevels) {
      cells[sl.locationId] = { quantity: sl.quantity, reserved: sl.reserved, available: sl.available, syncStatus: asSync(sl.syncStatus) }
    }
    return { productId: c.id, sku: c.sku, name: c.name, thumbnailUrl: c.thumbnailUrl, lowStockThreshold: c.lowStockThreshold ?? DEFAULT_LOW_STOCK_THRESHOLD, cells }
  })
  return { columns, rows }
}

/**
 * A single product: the same shape with one row, so the editor has one behaviour. Locations
 * without a level appear as 0 (the "add at location" affordance the list mode used to carry).
 */
export function buildSingleModel(
  product: { id: string; sku: string; name: string; thumbnailUrl: string | null; lowStockThreshold?: number | null },
  levels: RawListLevel[],
  activeLocations: RawLocation[],
): MatrixModel {
  const columns = activeLocations.map(column)
  const cells: MatrixRow['cells'] = {}
  for (const lv of levels) {
    cells[lv.location.id] = { quantity: lv.quantity, reserved: lv.reserved, available: lv.available, syncStatus: asSync(lv.syncStatus) }
  }
  return {
    columns,
    rows: [{ productId: product.id, sku: product.sku, name: product.name, thumbnailUrl: product.thumbnailUrl, lowStockThreshold: product.lowStockThreshold ?? DEFAULT_LOW_STOCK_THRESHOLD, cells }],
  }
}

export function editorModeForRow(row: { isParent: boolean }): 'matrix' | 'list' {
  return row.isParent ? 'matrix' : 'list'
}

// ── pending edits: what the operator has typed and not yet applied ─────────────────────────

/** One key per (product, location) cell. */
export const pendingKey = (productId: string, locationId: string) => `${productId}:${locationId}`

export type PendingEdits = ReadonlyMap<string, number>

/** The on-hand the grid shows: the pending value if there is one, else the server's. */
export function onHandOf(row: MatrixRow, locationId: string, pending: PendingEdits): number {
  return pending.get(pendingKey(row.productId, locationId)) ?? row.cells[locationId]?.quantity ?? 0
}

/** Available follows on-hand live: on-hand − reserved, never below zero. */
export function availableOf(row: MatrixRow, locationId: string, pending: PendingEdits): number {
  const reserved = row.cells[locationId]?.reserved ?? 0
  return Math.max(0, onHandOf(row, locationId, pending) - reserved)
}

/** The change a pending value represents against the server's number; 0 when none. */
export function deltaOf(row: MatrixRow, locationId: string, pending: PendingEdits): number {
  const v = pending.get(pendingKey(row.productId, locationId))
  if (v === undefined) return 0
  return v - (row.cells[locationId]?.quantity ?? 0)
}

/**
 * Record a typed value. A value equal to the server's is NOT a change — it clears any pending
 * edit for that cell, so "change and change back" leaves nothing to apply. Invalid values
 * (negative, fractional, NaN) are refused: the map is returned untouched.
 */
export function withEdit(pending: PendingEdits, row: MatrixRow, locationId: string, value: unknown): Map<string, number> {
  const next = new Map(pending)
  const n = typeof value === 'number' ? value : Number(String(value ?? '').trim())
  if (!Number.isFinite(n) || !Number.isInteger(n) || n < 0) return next
  const key = pendingKey(row.productId, locationId)
  if (n === (row.cells[locationId]?.quantity ?? 0)) next.delete(key)
  else next.set(key, n)
  return next
}

/** The batch the server receives: one absolute on-hand per changed cell. */
export function changesOf(pending: PendingEdits): Array<{ productId: string; locationId: string; value: number }> {
  return [...pending.entries()].map(([key, value]) => {
    const i = key.indexOf(':')
    return { productId: key.slice(0, i), locationId: key.slice(i + 1), value }
  })
}

/** Totals per location and overall, over the numbers the grid is SHOWING (pending included). */
export function totalsOf(model: MatrixModel, pending: PendingEdits): { cells: Record<string, LevelCell>; totalAvailable: number } {
  const cells: Record<string, LevelCell> = {}
  let totalAvailable = 0
  for (const col of model.columns) {
    let quantity = 0, reserved = 0, available = 0
    for (const row of model.rows) {
      quantity += onHandOf(row, col.locationId, pending)
      reserved += row.cells[col.locationId]?.reserved ?? 0
      available += availableOf(row, col.locationId, pending)
    }
    cells[col.locationId] = { quantity, reserved, available }
    totalAvailable += available
  }
  return { cells, totalAvailable }
}

/** A row's total available across locations, as the products grid shows it. */
export function rowTotalAvailable(row: MatrixRow, columns: readonly MatrixColumn[], pending: PendingEdits): number {
  return columns.reduce((sum, c) => sum + availableOf(row, c.locationId, pending), 0)
}

/** The worst sync state among a row's levels — what the badge shows. */
export function rowSyncStatus(row: MatrixRow): SyncStatus | null {
  const states = Object.values(row.cells).map((c) => c.syncStatus).filter((s): s is SyncStatus => !!s)
  if (states.includes('FAILED')) return 'FAILED'
  if (states.includes('PENDING')) return 'PENDING'
  return states.length ? 'SYNCED' : null
}

import { describe, expect, it } from 'vitest'

import {
  availableOf, buildMatrixModel, buildSingleModel, changesOf, deltaOf, onHandOf, rowSyncStatus, rowTotalAvailable, stockLevelOf, totalsOf, withEdit,
  type MatrixModel,
} from './inventoryEditor.logic'

const LOCS = [
  { id: 'fba', code: 'AMAZON-EU-FBA', name: 'Amazon FBA', type: 'AMAZON_FBA' },
  { id: 'it', code: 'IT-MAIN', name: 'Italy', type: 'WAREHOUSE' },
]
const model = (): MatrixModel => buildMatrixModel(LOCS, [
  { id: 'p1', sku: 'A-S', name: 'A small', thumbnailUrl: null, stockLevels: [{ locationId: 'it', locationCode: 'IT-MAIN', locationType: 'WAREHOUSE', quantity: 10, reserved: 2, available: 8, syncStatus: 'SYNCED' }] },
  { id: 'p2', sku: 'A-M', name: 'A medium', thumbnailUrl: null, stockLevels: [{ locationId: 'it', locationCode: 'IT-MAIN', locationType: 'WAREHOUSE', quantity: 3, reserved: 0, available: 3, syncStatus: 'FAILED' }, { locationId: 'fba', locationCode: 'AMAZON-EU-FBA', locationType: 'AMAZON_FBA', quantity: 7, reserved: 0, available: 7 }] },
])

describe('the model — one shape for a family and for a single product', () => {
  it('marks FBA and Shopify columns read-only and fills missing levels with zeros', () => {
    const m = model()
    expect(m.columns.map((c) => c.editable)).toEqual([false, true])
    expect(m.rows[0].cells.fba).toBeUndefined()
    expect(onHandOf(m.rows[0], 'fba', new Map())).toBe(0)
  })
  it('a single product is a one-row family with every active location present', () => {
    const m = buildSingleModel({ id: 'p9', sku: 'KNEE', name: 'Knee slider', thumbnailUrl: null, lowStockThreshold: 4 }, [{ location: LOCS[1], quantity: 20, reserved: 1, available: 19 }], LOCS)
    expect(m.rows).toHaveLength(1)
    expect(m.rows[0].lowStockThreshold).toBe(4)
    expect(availableOf(m.rows[0], 'it', new Map())).toBe(19)
    expect(availableOf(m.rows[0], 'fba', new Map())).toBe(0)
  })
})

describe('pending edits sit over the server numbers', () => {
  it('a typed value shows, moves Available live, and reports its delta', () => {
    const m = model()
    const p = withEdit(new Map(), m.rows[0], 'it', '15')
    expect(onHandOf(m.rows[0], 'it', p)).toBe(15)
    expect(availableOf(m.rows[0], 'it', p)).toBe(13)
    expect(deltaOf(m.rows[0], 'it', p)).toBe(5)
    expect(changesOf(p)).toEqual([{ productId: 'p1', locationId: 'it', value: 15 }])
  })
  it('typing the server value back clears the edit; invalid input is refused', () => {
    const m = model()
    let p = withEdit(new Map(), m.rows[0], 'it', 15)
    p = withEdit(p, m.rows[0], 'it', 10)
    expect(p.size).toBe(0)
    expect(withEdit(p, m.rows[0], 'it', -1).size).toBe(0)
    expect(withEdit(p, m.rows[0], 'it', 2.5).size).toBe(0)
    expect(withEdit(p, m.rows[0], 'it', 'abc').size).toBe(0)
  })
  it('available never goes below zero when on-hand is set under the reserved figure', () => {
    const m = model()
    const p = withEdit(new Map(), m.rows[0], 'it', 1)
    expect(availableOf(m.rows[0], 'it', p)).toBe(0)
  })
})

describe('totals and badges', () => {
  it('totals follow what the grid shows, pending included', () => {
    const m = model()
    const before = totalsOf(m, new Map())
    expect(before.cells.it).toEqual({ quantity: 13, reserved: 2, available: 11 })
    expect(before.totalAvailable).toBe(18)
    const p = withEdit(new Map(), m.rows[1], 'it', 13)
    expect(totalsOf(m, p).cells.it.quantity).toBe(23)
    expect(rowTotalAvailable(m.rows[1], m.columns, p)).toBe(20)
  })
  it('a row shows its worst sync state; a level with no state shows none', () => {
    const m = model()
    expect(rowSyncStatus(m.rows[0])).toBe('SYNCED')
    expect(rowSyncStatus(m.rows[1])).toBe('FAILED')
    expect(stockLevelOf(0, 10)).toBe('out'); expect(stockLevelOf(10, 10)).toBe('low'); expect(stockLevelOf(11, 10)).toBe('ok')
  })
})

// Legacy entry point. next.config.js redirects bookmarks to /products, including
// query parameters and workspace-prefixed URLs, before this page renders.

import { ProductsNextClient } from './ProductsNextClient'

export const dynamic = 'force-dynamic'
export const revalidate = 0
export const fetchCache = 'force-no-store'

export default function ProductsNextPage() {
  return <ProductsNextClient />
}

/**
 * The products grid's Server-Side Row Model datasource. A thin caller of the contract.
 *
 * AG asks for a block — `[startRow, endRow)` plus its sort model and, for a tree, the group
 * keys of the parent being expanded — and this POSTS that request, verbatim, with the page's
 * context to `/api/products/grid`. The server owns what it means; this file only knows how to
 * fetch and how to hand the answer back.
 *
 * TREE DATA UNDER SSRM
 * A product family is a parent with lazily loaded variations. AG expresses that as
 * `isServerSideGroup` (can this row expand?) + `getServerSideGroupKey` (what key names it) +
 * `request.groupKeys` (the path being expanded). When `groupKeys` is non-empty the request is for
 * one family's children, and the server answers with its capped preview (ten, in the grid's sort).
 * The footer sentinel closes that block and tells AG it is complete, so AG never asks for a second
 * page of variations the page has chosen not to show inline; the family page shows the rest.
 *
 * REFRESH
 * The datasource is stateless. The page calls `api.refreshServerSide(...)` on an invalidation
 * event and AG re-asks for whatever is on screen.
 */
import type { IServerSideDatasource, IServerSideGetRowsParams } from '@/design-system/grid'

import { getBackendUrl } from '@/lib/backend-url'
import { buildGridRequest, type ProductsGridContext, type ProductsGridResponse, type ProductsListStats } from './productsServerContract'

export type { ProductsGridContext, ProductsGridResponse, ProductsListStats } from './productsServerContract'

/**
 * The full-width row beneath an expanded family — "Showing 10 of 40 variations" and
 * the button that opens the family as a page. Appended to the preview block as a SENTINEL row,
 * so AG lays it out as a row (`isFullWidthRow`) and the page renders it. `total` is the SERVER's
 * own `rowCount` for the very query that produced the rows, so it cannot drift from them.
 */
export interface FamilyFooterRow {
  __familyFooter: true
  id: string
  parentId: string
  shown: number
  total: number
}
export const isFamilyFooter = (d: unknown): d is FamilyFooterRow =>
  !!d && typeof d === 'object' && (d as { __familyFooter?: boolean }).__familyFooter === true
export const familyFooterId = (parentId: string) => `__family_footer__${parentId}`

export interface ProductsDatasourceOptions<TRow> {
  /** Read at request time, so a filter change followed by a refresh sends the new filters. */
  getContext: () => ProductsGridContext
  /** Top-level metadata from the response — the KPI strip and the "of N" count read these. */
  onTopLevel?: (info: { total: number; stats?: ProductsListStats; response: ProductsGridResponse<TRow> }) => void
  /** The SERVER could not express something (an unmapped tag, a column it cannot order by). */
  onUnsupported?: (items: string[]) => void
  /**
   * A block failed to load. AG shows its own failed-block state, but that is a cell-level
   * signal; the PAGE has to know too, or it sits on its loading skeleton forever — which reads as
   * "still loading" on a 401 and sends the next person looking for a bug in the grid.
   */
  onError?: (message: string) => void
}

export function createProductsDatasource<TRow>({
  getContext,
  onTopLevel,
  onUnsupported,
  onError,
}: ProductsDatasourceOptions<TRow>): IServerSideDatasource<TRow> {
  return {
    getRows: async (params: IServerSideGetRowsParams<TRow>) => {
      const { request } = params
      // Under row grouping `groupKeys` is a group path, not a family; only the tree gets a footer.
      const grouped = (request.rowGroupCols?.length ?? 0) > 0
      const parentId = !grouped && request.groupKeys.length ? String(request.groupKeys[request.groupKeys.length - 1]) : null
      const body = buildGridRequest(getContext(), { startRow: request.startRow, endRow: request.endRow, sortModel: request.sortModel, groupKeys: request.groupKeys, filterModel: request.filterModel, rowGroupCols: request.rowGroupCols, valueCols: request.valueCols })

      try {
        const res = await fetch(`${getBackendUrl()}/api/products/grid`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
          cache: 'no-store',
        })
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        const data = (await res.json()) as ProductsGridResponse<TRow>
        const rowData = data.rows ?? []
        const rowCount = data.rowCount ?? rowData.length
        // Reported on every answer, an empty list included, so a note about a filter that no
        // longer applies clears the moment the request stops carrying it.
        onUnsupported?.(data.unsupported ?? [])
        // The KPI tiles read only the ROOT request: a level inside a grouping or a family
        // reports its own stats, and opening "Xavia › Active" must not show 11 of 14 products.
        if (request.groupKeys.length === 0) onTopLevel?.({ total: rowCount, stats: data.stats, response: data })
        if (parentId && rowCount > 0) {
          // The preview is capped on purpose; the footer sentinel closes the block and reports the
          // block as complete, so AG never asks for a second page of variations.
          const footer: FamilyFooterRow = { __familyFooter: true, id: familyFooterId(parentId), parentId, shown: rowData.length, total: rowCount }
          const withFooter = [...rowData, footer as unknown as TRow]
          params.success({ rowData: withFooter, rowCount: withFooter.length })
          return
        }
        params.success({ rowData, rowCount })
      } catch (err) {
        // A thrown error here would be swallowed by AG, so it is reported twice on purpose: to
        // AG (failed-block state, retried on the next scroll into range) and to the page.
        onError?.(err instanceof Error ? err.message : String(err))
        params.fail()
      }
    },
  }
}

/**
 * The products export — the QUERY, not the viewport.
 *
 * `api.exportDataAsCsv()` walks the rows AG is holding. Under the Server-Side Row Model that is
 * the loaded blocks: on any catalogue bigger than one page the file was a silent subset of what
 * the operator had filtered to, and it also carried the `FamilyFooterRow` sentinels this page
 * injects under an expanded family, because those are rows to AG.
 *
 * So the export re-asks the SERVER for the same scope the grid is showing — the same
 * `POST /api/products/grid`, the same context, filters and sort — in chunks, with the tree and any
 * row grouping flattened away (`groupKeys: []`, no `rowGroupCols`). What comes back is the
 * operator's filtered result set, whole, and the sentinels never existed on that side of the wire.
 *
 * The CAP is not a guess about the catalogue: it is the point past which holding rows in the tab
 * to build one string stops being reasonable, and the caller is told it truncated rather than
 * being handed a short file that looks complete — the very failure this replaces.
 */
import { getBackendUrl } from '@/lib/backend-url'

import { buildGridRequest, type ProductsGridContext, type ProductsGridResponse } from './productsServerContract'
import type { SortModelItem } from '@/design-system/grid'

/** Rows per request. The grid itself pages at 100; a export asks for more per round-trip. */
const CHUNK = 500

export const EXPORT_ROW_CAP = 50_000

export interface ExportFetchResult<TRow> {
  rows: TRow[]
  /** The server's own count for the query — what the file WOULD hold with no cap. */
  total: number
  /** The cap was reached: `rows` is short of `total`, and the caller must say so. */
  truncated: boolean
}

export interface ExportFetchOptions {
  context: ProductsGridContext
  sortModel: readonly SortModelItem[]
  filterModel: unknown
  /** Loaded so far / the server's total, after each chunk. */
  onProgress?: (loaded: number, total: number) => void
  signal?: AbortSignal
}

export async function fetchAllRowsForExport<TRow>({
  context,
  sortModel,
  filterModel,
  onProgress,
  signal,
}: ExportFetchOptions): Promise<ExportFetchResult<TRow>> {
  const rows: TRow[] = []
  let total = 0
  let startRow = 0

  for (;;) {
    const body = buildGridRequest(context, {
      startRow,
      endRow: startRow + CHUNK,
      sortModel,
      // Flat: a family's inline preview and a grouped level are both VIEWS of this scope, and
      // neither is what "export what I filtered to" means.
      groupKeys: [],
      filterModel,
      rowGroupCols: [],
      valueCols: [],
    })

    const res = await fetch(`${getBackendUrl()}/api/products/grid`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
      cache: 'no-store',
      signal,
    })
    if (!res.ok) throw new Error(`Export failed: HTTP ${res.status}`)
    const data = (await res.json()) as ProductsGridResponse<TRow>

    const batch = data.rows ?? []
    total = data.rowCount ?? batch.length
    rows.push(...batch)
    onProgress?.(rows.length, total)

    // Three ways to be done, and the short block is the authoritative one: a server that answers
    // fewer rows than asked has no more to give, whatever its count said.
    if (batch.length < CHUNK) break
    if (rows.length >= total) break
    if (rows.length >= EXPORT_ROW_CAP) return { rows: rows.slice(0, EXPORT_ROW_CAP), total, truncated: true }

    startRow += CHUNK
  }

  return { rows, total, truncated: false }
}

import type { ColumnState, GridState } from '@/design-system/grid'

import type { PreferencesColumnSpec, PreferencesValue } from '@/design-system/patterns/PreferencesModal'
import { AG_AUTO_COL, prefsToColumnState, type PrefsBridgeOptions } from '@/design-system/grid/columns/columnPrefs'
import type { GridViewPayload } from '@/design-system/grid/hooks/useGridViews'
import { layoutFromPreferences } from '@/design-system/grid/views/columnLayout'
import { isColumnsViewPayload, type SheetLayoutPayload } from '@/design-system/grid/views/viewPayload'
import { composeLocks, isStructuralColumn, withStructuralLocks } from './columnLocks'

/** Stage the modal's confirmed layout for persistence before changing the running grid. */
export function buildProductsLayout<TPage extends { lockedColumns: string[] }>(
  snapshot: GridViewPayload<TPage>,
  draft: PreferencesValue,
  specs: readonly PreferencesColumnSpec[],
  bridge: PrefsBridgeOptions,
): GridViewPayload<TPage & { columnLayout: SheetLayoutPayload }> {
  const locks = composeLocks(draft.lockedColumns ?? snapshot.page.lockedColumns)
  const preferences = withStructuralLocks({
    ...draft,
    stickyFirstColumn: locks.includes('product'),
    stickyLastColumn: locks.includes('actions'),
  }, locks)
  // These bookends are operator-lockable on /products/next, so retain them in the layout even
  // when the current bridge treats their confirmed pins as structural.
  const layoutSpecs = specs.map((column) => isStructuralColumn(column.key) ? { ...column, locked: false } : column)
  const columnLayout = layoutFromPreferences(layoutSpecs, preferences)
  const known = new Set(bridge.columns.map((column) => column.key))
  const staged = prefsToColumnState({
    ...preferences,
    visibleColumns: columnLayout.columns.filter((key) => known.has(key)),
    rowGroups: preferences.rowGroups ?? snapshot.gridState.rowGroup?.groupColIds.map((id) => id === AG_AUTO_COL && bridge.treeColumnKey ? bridge.treeColumnKey : id),
  }, {
    ...bridge,
    columns: bridge.columns.map((column) => isStructuralColumn(column.key)
      ? { ...column, locked: locks.includes(column.key) }
      : column),
  })
  const ids = new Set(staged.map((column) => column.colId))
  const order = [...staged.map((column) => column.colId), ...(snapshot.gridState.columnOrder?.orderedColIds ?? []).filter((id) => !ids.has(id))]
  const gridState: GridState = {
    ...snapshot.gridState,
    columnOrder: { orderedColIds: order },
    columnVisibility: { hiddenColIds: [
      ...staged.filter((column) => column.hide).map((column) => column.colId),
      ...(snapshot.gridState.columnVisibility?.hiddenColIds ?? []).filter((id) => !ids.has(id)),
    ] },
  }
  // Row selection belongs to the current bulk operation, not to a reusable saved layout.
  delete gridState.rowSelection

  // The bridge leaves the selection column's pin to the grid. Preserve any pin it did not state.
  const pinDecisions = new Map(staged.filter((column) => column.pinned !== undefined).map((column) => [column.colId, column.pinned]))
  const pinned = (side: 'left' | 'right') => {
    const previous = new Set(snapshot.gridState.columnPinning?.[side === 'left' ? 'leftColIds' : 'rightColIds'] ?? [])
    const wanted = new Set([
      ...staged.filter((column) => column.pinned === side).map((column) => column.colId),
      ...[...previous].filter((id) => !pinDecisions.has(id)),
    ])
    return [...new Set([...order, ...wanted])].filter((id) => wanted.has(id))
  }
  gridState.columnPinning = { leftColIds: pinned('left'), rightColIds: pinned('right') }

  if (draft.rowGroups !== undefined) {
    gridState.rowGroup = { groupColIds: [
      ...staged.filter((column) => column.rowGroup).sort((a, b) => (a.rowGroupIndex ?? 0) - (b.rowGroupIndex ?? 0)).map((column) => column.colId),
      ...(snapshot.gridState.rowGroup?.groupColIds ?? []).filter((id) => !ids.has(id)),
    ] }
  }
  if (draft.aggregations !== undefined) {
    gridState.aggregation = { aggregationModel: [
      ...staged.filter((column): column is ColumnState & { aggFunc: string } => typeof column.aggFunc === 'string')
        .map((column) => ({ colId: column.colId, aggFunc: column.aggFunc })),
      ...(snapshot.gridState.aggregation?.aggregationModel ?? []).filter((column) => !ids.has(column.colId)),
    ] }
  }
  if (draft.sortBy) {
    gridState.sort = { sortModel: [
      ...staged.filter((column): column is ColumnState & { sort: 'asc' | 'desc' } => column.sort === 'asc' || column.sort === 'desc')
        .sort((a, b) => (a.sortIndex ?? 0) - (b.sortIndex ?? 0))
        .map((column) => ({ colId: column.colId, sort: column.sort })),
      ...(snapshot.gridState.sort?.sortModel ?? []).filter((column) => !ids.has(column.colId)),
    ] }
  }
  return { ...snapshot, gridState, page: { ...snapshot.page, lockedColumns: locks, columnLayout } }
}

/** Older product views have no group layout; malformed and unrelated payloads stay unsupported. */
export function readProductsLayout(payload: unknown): SheetLayoutPayload | null {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return null
  const value = payload as { v?: unknown; gridState?: unknown; page?: unknown }
  if (value.v !== 1 || !value.gridState || typeof value.gridState !== 'object' || Array.isArray(value.gridState) ||
    !value.page || typeof value.page !== 'object' || Array.isArray(value.page)) return null
  const columnLayout = (value.page as { columnLayout?: unknown }).columnLayout
  return isColumnsViewPayload(columnLayout) && columnLayout.v === 3 ? columnLayout : null
}

import { describe, expect, it } from 'vitest'

import type { PreferencesColumnSpec, PreferencesValue } from '@/design-system/patterns/PreferencesModal'
