'use client'

/**
 * The bulk mutations behind the selection toolbar — real backend calls, mirroring the live
 * /products page. Each one broadcasts on the invalidation channel so the grid (and every other
 * open tab) refetches, and reports the SERVER's count, never the selection's.
 */
import { useCallback, useState } from 'react'

import { getBackendUrl } from '@/lib/backend-url'
import { emitInvalidation } from '@/lib/sync/invalidation-channel'

/** Every bulk endpoint rejects more than this with a 400. Mirrored here so the page can say so
 *  before the round trip rather than relaying the server's raw message after it. */
export const BULK_MAX = 200

/** What a bulk endpoint actually reports back. Every one of them returns HTTP 200 for a
 *  PARTIAL failure, so the body is the only place the truth lives. */
interface BulkResult {
  ok?: boolean
  /** bulk-status */ updated?: number
  /** bulk-duplicate */ created?: number
  /** bulk-soft-delete */ changed?: number
  skipped?: number
  errors?: Array<{ id: string; error: string }>
}

export type Toast = (message: string, tone: 'success' | 'danger' | 'neutral') => void

export interface UseBulkActionsOptions {
  toast: Toast
  /** Called after an action that consumed the selection — the grid clears it. */
  onConsumed: () => void
}

export function useBulkActions({ toast, onConsumed }: UseBulkActionsOptions) {
  const [busy, setBusy] = useState(false)

  const runBulk = useCallback(
    async (
      /** Given the SERVER's count, produce the sentence. Never the selection size — see below. */
      label: (n: number) => string,
      path: string,
      body: Record<string, unknown>,
      ids: string[],
      source: string,
      opts?: { clearSelection?: boolean },
    ) => {
      if (!ids.length || busy) return
      // Every one of these endpoints rejects more than 200 ids with a 400. Saying so before the
      // round trip beats relaying a raw server string after it.
      if (ids.length > BULK_MAX) {
        toast(`Select ${BULK_MAX} or fewer — that action can't take ${ids.length} at once.`, 'danger')
        return
      }
      setBusy(true)
      try {
        const res = await fetch(`${getBackendUrl()}${path}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        })
        const payload = (await res.json().catch(() => ({}))) as BulkResult & { error?: string }
        if (!res.ok) throw new Error(payload.error ?? `HTTP ${res.status}`)

        emitInvalidation({ type: 'product.updated', meta: { productIds: ids, source } })

        // 🔴 The count comes from the SERVER, not from the selection. These endpoints skip rows
        // that are already in the target state and collect per-row failures, so "Marked 5
        // active" was a claim about what was asked for, not what happened.
        const n = payload.updated ?? payload.created ?? payload.changed ?? ids.length
        const failed = payload.errors?.length ?? 0
        if (failed > 0) {
          // A partial failure arrives as HTTP 200 with `ok: false`.
          toast(`${label(n)} · ${failed} failed`, 'danger')
        } else if (n === 0) {
          toast('Nothing changed — already in that state', 'neutral')
        } else {
          toast(label(n), 'success')
        }
        if (opts?.clearSelection !== false) onConsumed()
      } catch (e) {
        toast(e instanceof Error ? e.message : 'Action failed', 'danger')
      } finally {
        setBusy(false)
      }
    },
    [busy, toast, onConsumed],
  )

  const setStatusBulk = useCallback(
    (ids: string[], status: 'ACTIVE' | 'DRAFT' | 'INACTIVE', includeChildren = true) =>
      runBulk((n) => `Marked ${n} ${status.toLowerCase()}`, '/api/products/bulk-status', { productIds: ids, status, includeChildren }, ids, 'bulk-status'),
    [runBulk],
  )

  const duplicateBulk = useCallback(
    (ids: string[]) =>
      runBulk((n) => `Duplicated ${n} ${n === 1 ? 'product' : 'products'}`, '/api/products/bulk-duplicate', { productIds: ids, includeChildren: true }, ids, 'bulk-duplicate'),
    [runBulk],
  )

  const softDeleteBulk = useCallback(
    (ids: string[]) =>
      runBulk((n) => `Moved ${n} to recycle bin`, '/api/products/bulk-soft-delete', { productIds: ids, includeChildren: true }, ids, 'bulk-soft-delete'),
    [runBulk],
  )

  return { busy, setStatusBulk, duplicateBulk, softDeleteBulk }
}

'use client'

/**
 * The inventory editor's data: ONE model (variations × locations, or a single product as a
 * one-row family) and ONE write — the batch. The server derives every delta from a fresh read
 * and refuses FBA / Shopify / invalid values per change; the result comes back per change so the
 * grid can keep a refused cell pending and clear the confirmed ones.
 */
import { useCallback, useEffect, useRef, useState } from 'react'

import { getBackendUrl } from '@/lib/backend-url'
import { emitInvalidation } from '@/lib/sync/invalidation-channel'
import type { ProductRow } from '@/app/products/_types'

import { buildMatrixModel, buildSingleModel, editorModeForRow, type MatrixModel, type RawLocation } from './inventoryEditor.logic'

interface State {
  loading: boolean
  error: string | null
  model: MatrixModel | null
}
const EMPTY: State = { loading: false, error: null, model: null }

export interface BatchChange { productId: string; locationId: string; value: number }
export interface BatchResult {
  productId: string
  locationId: string
  ok: boolean
  noop?: boolean
  error?: string
  code?: string
}

export function useInventoryEditor(row: ProductRow | null) {
  const [state, setState] = useState<State>(EMPTY)
  const reqId = useRef(0)
  const productId = row?.id ?? null
  const mode = row ? editorModeForRow(row) : 'list'

  const load = useCallback(async () => {
    if (!productId || !row) { setState(EMPTY); return }
    const my = ++reqId.current
    setState((s) => ({ ...s, loading: true, error: null }))
    try {
      const base = getBackendUrl()
      if (mode === 'matrix') {
        const res = await fetch(`${base}/api/stock/product/${productId}?family=true`, { cache: 'no-store' })
        if (!res.ok) throw new Error(`Failed to load (${res.status})`)
        const data = await res.json()
        if (!data.family) throw new Error('No variation data for this product.')
        const model = buildMatrixModel(data.family.locations as RawLocation[], data.family.children)
        if (my === reqId.current) setState({ loading: false, error: null, model })
      } else {
        const [pRes, lRes] = await Promise.all([
          fetch(`${base}/api/stock/product/${productId}`, { cache: 'no-store' }),
          fetch(`${base}/api/stock/locations`, { cache: 'no-store' }),
        ])
        if (!pRes.ok) throw new Error(`Failed to load product (${pRes.status})`)
        if (!lRes.ok) throw new Error(`Failed to load locations (${lRes.status})`)
        const pData = await pRes.json()
        const lData = await lRes.json()
        const active = (lData.locations as Array<RawLocation & { isActive: boolean }>).filter((l) => l.isActive)
        const model = buildSingleModel(
          { id: row.id, sku: row.sku, name: row.name, thumbnailUrl: row.imageUrl ?? null, lowStockThreshold: row.lowStockThreshold },
          pData.stockLevels,
          active,
        )
        if (my === reqId.current) setState({ loading: false, error: null, model })
      }
    } catch (e: unknown) {
      if (my === reqId.current) setState({ loading: false, error: e instanceof Error ? e.message : 'Failed to load', model: null })
    }
    // `row` is read for its identity fields only; the id is the dependency that matters.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [productId, mode])

  useEffect(() => { void load() }, [load])

  /** Apply every pending change as one audited batch. Resolves per change; never throws. */
  const applyBatch = useCallback(
    async (args: { reason: string; notes?: string; changes: BatchChange[] }): Promise<{ ok: true; results: BatchResult[] } | { ok: false; error: string }> => {
      try {
        const res = await fetch(`${getBackendUrl()}/api/stock/adjust-locations`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(args),
        })
        const data = await res.json().catch(() => ({}))
        if (!res.ok) return { ok: false, error: data?.error ?? `Apply failed (${res.status})` }
        const results = (data.results ?? []) as BatchResult[]
        if (results.some((r) => r.ok && !r.noop)) {
          emitInvalidation({ type: 'stock.adjusted', meta: { productId: productId ?? undefined, source: 'products-next-inventory-editor' } })
        }
        await load()
        return { ok: true, results }
      } catch (e: unknown) {
        return { ok: false, error: e instanceof Error ? e.message : 'Apply failed' }
      }
    },
    [load, productId],
  )

  return { ...state, reload: load, applyBatch }
}

