      for (let r = 2; r <= last; r++) {
        sheet.getCell(r, col.number).fill = fill(f.editable === false ? workbookColors.reference : workbookColors.input)
        sheet.getCell(r, actionCol.number).fill = fill(workbookColors.reference)
