    }
    sheet.autoFilter = { from: { row: 1, column: 1 }, to: { row: Math.max(2, sheet.rowCount), column: headers.length } }
  }
  const formulas = table(book, 'Formula examples', ['Brand', 'Model', 'Color', 'Title helper', 'Title length'], [24, 24, 24, 60, 18])
  formulas.addRow(['Example brand', 'Example model', 'Example color', { formula: 'A2&" "&B2&" - "&C2', result: 'Example brand Example model - Example color' }, { formula: 'LEN(D2)', result: 'Example brand Example model - Example color'.length }])
  formulas.addRow(['Replace these illustrative inputs. Paste verified results as values into the appropriate language or listing sheet.'])
  formulas.getRow(3).height = 32; formulas.mergeCells('A3:E3'); formulas.getCell('A3').alignment = { wrapText: true, vertical: 'middle' }
  formatReferenceSheet(dictionary)
  formatReferenceSheet(values)
  if (values.rowCount === 1) { values.addRow(['No fixed choices', 'See Dictionary for types and units.']); formatReferenceSheet(values, false) }
  formatReferenceSheet(instructions, false)
  instructions.getColumn(1).font = { name: 'Arial', size: 10, bold: true, color: { argb: workbookColors.text } }
  // Reapply the header after the label-column font so its white text stays legible.
  instructions.getCell('A1').font = { name: 'Arial', size: 10, bold: true, color: { argb: workbookColors.white } }
  instructions.views = [{ state: 'normal', showGridLines: false }]
  for (const cell of ['A2', 'B2', 'C2']) formulas.getCell(cell).fill = fill(workbookColors.input)
  for (const cell of ['D2', 'E2']) formulas.getCell(cell).fill = fill(workbookColors.reference)
  fitWorkbookRow(formulas.getRow(2))
  formulas.getRow(3).height = 36
  // Named dropdown ranges use fixed reference rows. Prevent accidental sorting or
  // edits there while preserving filtering, copying and resizing; no password needed.
  for (const sheet of [dictionary, values, manifest]) await sheet.protect('', { autoFilter: true, sort: false, formatColumns: true, formatRows: true })
  const buffer = Buffer.from(await book.xlsx.writeBuffer())
  if (buffer.length > TRANSFER_MAX_FILE_BYTES) throw new TransferWorkbookLimitError('bytes')
  return buffer
}

/** Parse the wide workbook into the same reviewed, transactional attribute contract as v1. */
export function readCatalogWorkbook(book: ExcelJS.Workbook, editing?: EditingWorkbookBaseline): { rows: TransferRow[]; issues: TransferIssue[] } | null {
  const manifest = book.getWorksheet('Nexus workbook')
  if (!manifest) return null
  const version = manifest.getCell('B2').text
  const escapedHeaders = manifest.getCell('D2').text === 'escaped-field-headers-v1'
  const headerField = (header: string) => escapedHeaders && header.startsWith('value:') ? header.slice(6) : header
  if (manifest.getCell('A2').text !== 'nexus-catalog-wide' || !['2', '3'].includes(version)) throw new Error('Unsupported Nexus workbook version')
  if (version === '3' && (!editing || manifest.getCell('C2').text !== editing.id)) throw new Error('Return this editing workbook to its product editor. Its saved export baseline is required.')
  if (version !== '3' && editing) throw new Error('The editing workbook version was changed. Download a new workbook.')
  const logicalConstant = (cell: ExcelJS.Cell) => cell.type === ExcelJS.ValueType.Formula && /^(TRUE|FALSE)\(\)$/i.test(cell.formula) ? cell.formula.toUpperCase() === 'TRUE()' : undefined
  const literal = (cell: ExcelJS.Cell, valueCell = false) => {
    // LibreOffice writes native logical cells as TRUE()/FALSE(). These constants
    // need no calculation and we never trust their cached result. Keep formulas
    // forbidden in identities and metadata. Normal value type validation still
    // applies, including legacy booleans stored under a text field definition.
    const logical = valueCell ? logicalConstant(cell) : undefined
    if (logical !== undefined) return String(logical)
    if ([ExcelJS.ValueType.Formula, ExcelJS.ValueType.Error].includes(cell.type)) throw new Error(`${cell.fullAddress.sheetName}!${cell.address}: paste verified formula results as values before importing`)
    return cell.text
  }
  for (let c = 1; c <= manifestColumns.length; c++) if (literal(manifest.getCell(4, c)) !== manifestColumns[c - 1]) throw new Error('Nexus workbook scope headers were changed')
  const dictionary = book.getWorksheet('Dictionary')
  if (!dictionary || !['sheet', 'Sheet'].includes(dictionary.getCell('A1').text) || !['field', 'Field key'].includes(dictionary.getCell('B1').text) || !['type', 'Type'].includes(dictionary.getCell('D1').text)) throw new Error('Keep the workbook Dictionary intact')
  const types = new Map<string, string>()
  const encodings = new Map<string, string>()
  dictionary.eachRow((r, i) => { if (i > 1) {
    const key = JSON.stringify([literal(r.getCell(1)), literal(r.getCell(2))]), type = literal(r.getCell(4))
    if (types.has(key)) throw new Error('Duplicate dictionary field')
    types.set(key, type)
    const encoding = literal(r.getCell(11)) || 'cell'
    if (!['cell', 'json'].includes(encoding)) throw new Error('Dictionary encoding must be cell or json')
    encodings.set(key, encoding)
  } })
  const rows: TransferRow[] = [], issues: TransferIssue[] = [], consumed = new Set<string>()
  let scannedCells = 0
  for (let n = 5; n <= manifest.rowCount; n++) {
    const scope = Object.fromEntries(manifestColumns.map((k, i) => [k, literal(manifest.getCell(n, i + 1))])) as unknown as WorkbookScope
    if (!scope.sheet) { if (manifest.getRow(n).hasValues) throw new Error('A workbook scope is missing its sheet name'); continue }
    if (consumed.has(scope.sheet) || supporting.has(scope.sheet)) throw new Error('Duplicate or invalid workbook scope')
    consumed.add(scope.sheet)
    if (consumed.size > 100) throw new Error('Choose at most 100 workbook scopes per file')
    const sheet = book.getWorksheet(scope.sheet)
    if (!sheet) throw new Error(`Missing worksheet ${scope.sheet}`)
    const originalScope = editing?.scopes.find(s => s.sheet === scope.sheet)
    if (editing && (!originalScope || manifestColumns.some(k => originalScope[k] !== scope[k]))) throw new Error(`${scope.sheet}: the exported destination was changed. Download a new workbook for this destination.`)
    const originalRows = new Map(originalScope?.rows.map(r => [JSON.stringify([r.sku, r.aliasKey, r.field]), r]))
    const originalEncodings = originalScope ? jsonEncodedFields(originalScope) : null
    if (sheet.rowCount > TRANSFER_MAX_ROWS + 1 || sheet.columnCount > 2000) throw new Error('Worksheet exceeds the import limits')
    scannedCells += sheet.rowCount * sheet.columnCount
    if (scannedCells > 2_000_000) throw new Error('Workbook contains too many sparse cells; remove unused rows and columns or split the workbook')
    const headers = Array.from({ length: sheet.columnCount }, (_, i) => literal(sheet.getCell(1, i + 1)))
    const coordinateKeys = ['sku', 'version', ...(scope.entity === 'Products' ? [] : editing ? ['listing', 'aliasKey'] : ['aliasKey'])]
    if (!headers.includes('sku') || new Set(headers).size !== headers.length || headers.some(h => !h)) throw new Error(`${scope.sheet}: use distinct, non-empty headers including sku`)
    const fieldHeaders = headers.filter(h => !coordinateKeys.includes(h) && !h.startsWith(actionPrefix))
    if (new Set(fieldHeaders.map(headerField)).size !== fieldHeaders.length) throw new Error(`${scope.sheet}: duplicate attribute headers`)
    if (originalScope) for (const header of fieldHeaders) {
      const field = headerField(header)
      const key = JSON.stringify([scope.sheet, field])
      if (types.get(key) !== originalScope.fields.find(f => f.field === field)?.type || encodings.get(key) !== (originalEncodings!.has(field) ? 'json' : 'cell')) throw new Error(`${scope.sheet}: keep the field Dictionary intact`)
    }
    const fieldColumns = new Map(headers.map((h, i) => [h, i + 1]))
    const valueFields = new Set(fieldHeaders)
    for (const h of headers) if (!coordinateKeys.includes(h) && !types.has(JSON.stringify([scope.sheet, headerField(h.replace(/^action:/, ''))]))) throw new Error(`${scope.sheet}: unknown column ${h}; update the template or map this source explicitly`)
    for (const h of headers.filter(h => h.startsWith(actionPrefix))) if (!fieldHeaders.includes(h.slice(actionPrefix.length))) throw new Error(`${scope.sheet}: action column has no value column`)
    for (let r = 2; r <= sheet.rowCount; r++) {
      if (rows.length + issues.length > TRANSFER_MAX_ROWS) throw new TransferWorkbookLimitError('rows')
      const record = Object.fromEntries(headers.map((h, c) => [h, literal(sheet.getCell(r, c + 1), valueFields.has(h))]))
      if (Object.values(record).every(v => v === '')) continue
      if (!record.sku?.trim()) { issues.push({ row: r, sku: '', field: '', message: `${scope.sheet}: SKU is required` }); continue }
      if (editing && !/^\d+$/.test(record.version ?? '')) { issues.push({ row: r, sku: record.sku, field: 'version', message: `${scope.sheet}: keep the exported record version intact` }); continue }
      if (!editing && scope.entity !== 'Products' && scope.category) {
        const categoryKey = transferCategoryField(scope.channel)
        if (record[categoryKey] && record[categoryKey] !== scope.category) { issues.push({ row: r, sku: record.sku, field: categoryKey, message: `${scope.sheet}: this sheet is bound to category ${scope.category}. Download a template for the new category.` }); continue }
        if (!record[categoryKey] && !record[`${actionPrefix}${categoryKey}`]) {
          const category = parseTransferRecords([{ entity: 'Listings', sku: record.sku, version: record.version, channel: scope.channel, accountId: scope.accountId, marketplace: scope.marketplace, aliasKey: record.aliasKey ?? '', locale: scope.locale, field: categoryKey, action: 'SET', format: 'text', value: scope.category }])
          rows.push(...category.rows.map(row => ({ ...row, row: r }))); issues.push(...category.issues.map(issue => ({ ...issue, row: r })))
        }
      }
      for (const header of fieldHeaders) {
        const field = headerField(header)
        const cell = sheet.getCell(r, fieldColumns.get(header)!), raw = record[header]
        const original = originalRows.get(JSON.stringify([record.sku, record.aliasKey ?? '', field]))
        const source = { sheet: scope.sheet, column: cell.address.replace(/\d+$/, '') }
        if (editing && (!original || String(original.version) !== record.version)) { issues.push({ row: r, sku: record.sku, field, source, message: 'Keep the exported SKU, alias and version intact. Download a new workbook for a different record.' }); continue }
        const requested = record[`${actionPrefix}${header}`]
        if (editing && !requested && blank(raw)) { rows.push({ ...original!, row: r, source }); continue }
        const action = requested || (blank(raw) ? '' : 'SET')
        if (!action && blank(raw)) continue
        const type = types.get(JSON.stringify([scope.sheet, field]))!
        if (editing && type !== originalScope?.fields.find(f => f.field === field)?.type) throw new Error(`${scope.sheet}: keep the field Dictionary intact`)
        const json = encodings.get(JSON.stringify([scope.sheet, field])) === 'json' || ['list', 'measure', 'number', 'boolean', 'json'].includes(type) || typeof cell.value === 'number' || typeof cell.value === 'boolean' || logicalConstant(cell) !== undefined
        const parsed = parseTransferRecords([{ entity: scope.entity !== 'Products' && field === transferCategoryField(scope.channel) ? 'Listings' : scope.entity, sku: record.sku, version: record.version, channel: scope.channel, accountId: scope.accountId,
          marketplace: scope.marketplace, locale: scope.locale, aliasKey: record.aliasKey ?? '', field, action, format: json ? 'json' : 'text', value: raw }])
        rows.push(...parsed.rows.map(row => ({ ...(editing && !requested && original?.action === 'SET' && transferCanonical(row.value) === transferCanonical(original.value) ? original : row), row: r, source })))
        issues.push(...parsed.issues.map(issue => ({ ...issue, row: r, source, message: `${scope.sheet}: ${issue.message}` })))
        if (rows.length + issues.length > TRANSFER_MAX_ROWS) throw new TransferWorkbookLimitError('rows')
      }
    }
  }
  if (rows.length + issues.length > TRANSFER_MAX_ROWS) throw new TransferWorkbookLimitError('rows')
  for (const sheet of book.worksheets) if (!consumed.has(sheet.name) && !supporting.has(sheet.name)) throw new Error(`Worksheet ${sheet.name} has no declared destination`)
  const targets = new Map<string, unknown>()
  for (const row of rows) {
    const key = JSON.stringify([row.entity, row.sku, row.channel, row.accountId, row.marketplace, row.aliasKey, row.locale, row.field])
    if (targets.has(key)) throw new Error(`Multiple sheets write the same attribute: ${row.sku} / ${row.field}`)
    targets.set(key, transferCanonical(row.value))
  }
  return { rows, issues }
}

import { normalizeLanguage } from './content-language.js'
import { TRANSFER_CHANNELS, transferCategoryField, transferIsStore, type TransferRow } from '@nexus/shared/catalog-transfer'
import type { SheetColumn } from './sheet-columns.service.js'
import type { CatalogueField } from './mapping/field-catalogue.service.js'
import { MANAGED_FIELDS, managedChannelField, transferContracts } from './catalog-transfer-plan.js'
import { writeCatalogWorkbook, type WorkbookField, type WorkbookScope } from './catalog-workbook.js'
import prisma from '../../db.js'
import { marketLanguages } from './market-languages.js'

export const masterWorkbookField = (c: SheetColumn): WorkbookField => ({ field: c.key, label: c.label, type: c.shape && c.shape !== 'scalar' ? c.shape : c.kind,
  editable: c.editable && !MANAGED_FIELDS.has(c.key), required: c.requiredBy.length ? 'required' : 'optional', options: c.options ?? [], selectionOnly: c.mode === undefined ? undefined : c.mode === 'strict',
  maxLength: c.maxLength, unitOptions: c.unitOptions, help: c.helpText ?? '' })
export const channelWorkbookField = (f: CatalogueField): WorkbookField => ({ field: f.fieldKey, label: f.label, type: f.shape && f.shape !== 'scalar' ? f.shape : f.kind ?? 'text',
  editable: f.editable && !managedChannelField(f), required: f.priority, options: f.options ?? [], help: `${f.helpText ?? ''}${managedChannelField(f) ? ' Managed in the dedicated commercial workflow.' : !f.editable ? ' Authorable on creation; the channel marks this read-only on existing listings.' : ''}`,
  maxLength: f.maxLength, unitOptions: f.unitOptions, selectionOnly: f.selectionOnly })
const content = new Set(['name', 'title', 'description', 'bulletPoints', 'keywords'])
export const relationshipFields: WorkbookField[] = [
  { field: 'family', label: 'Family code', type: 'text', required: 'required for new products' },
  { field: 'parentSku', label: 'Parent SKU', type: 'text', help: 'SET the parent SKU on a child. CLEAR unlinks. Leave blank to preserve. Never derive size from SKU.' },
  { field: 'categoryIds', label: 'Internal category IDs', type: 'list' },
  { field: 'primaryCategoryId', label: 'Primary internal category', type: 'text' },
]
export type WorkbookDestination = { channel: string; accountId: string; marketplace: string; category: string }
const emptyScope = { channel: '', accountId: '', marketplace: '', locale: '', category: '' }
export async function catalogWorkbookTemplate(input: { market: string; familyId: string; locales?: string[]; channels?: WorkbookDestination[] }) {
  if (input.locales !== undefined && (!Array.isArray(input.locales) || input.locales.some(l => typeof l !== 'string')) || input.channels !== undefined && !Array.isArray(input.channels)) throw new Error('Languages and channel destinations must be lists')
  const locales = [...new Set((input.locales ?? []).map(l => normalizeLanguage(l.trim())))]
  if (input.channels?.some(c => !c || typeof c !== 'object' || ['channel', 'accountId', 'marketplace', 'category'].some(k => typeof c[k as keyof WorkbookDestination] !== 'string'))) throw new Error('Each destination needs a channel, account, marketplace and category')
  const channels = (input.channels ?? []).map(c => ({ channel: c.channel.trim().toUpperCase(), accountId: c.accountId.trim(), marketplace: c.marketplace.trim().toUpperCase(), category: c.category.trim() }))
  if (locales.length > 30 || locales.some(l => !/^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/.test(l))) throw new Error('Choose at most 30 valid language codes, such as it, de or en-gb')
  if (channels.length > 30 || channels.some(c => !TRANSFER_CHANNELS.includes(c.channel) || !c.accountId || !/^(?:[A-Z]{2}|GLOBAL)$/.test(c.marketplace) || !transferIsStore(c.channel) && !c.category?.trim())) throw new Error('Each destination needs a supported channel, account, marketplace and category (at most 30)')
  if (new Set(channels.map(c => JSON.stringify([c.channel, c.accountId, c.marketplace, c.category]))).size !== channels.length) throw new Error('This account, marketplace and category is selected more than once. Remove the duplicate destination.')
  const family = await prisma.productFamily.findUnique({ where: { id: input.familyId }, select: { code: true } })
  if (!family) throw new Error('Select a product family')
  const contracts = transferContracts(input.market), cols = await contracts.master(input.familyId)
  const scopes: WorkbookScope[] = [{ ...emptyScope, sheet: 'Products', entity: 'Products', fields: [...relationshipFields, ...cols.filter(c => !c.slot && (c.storage !== 'localizedContent' || content.has(c.key))).map(masterWorkbookField)],
    rows: [{ ...emptyScope, row: 2, entity: 'Products', sku: '', aliasKey: '', field: 'family', action: 'SET', value: family.code }] }]
  const includedLocales = new Set(locales)
  for (const [i, c] of channels.entries()) {
    const [account, market] = await Promise.all([
      prisma.channelConnection.findUnique({ where: { id: c.accountId }, select: { channelType: true, marketplace: true, isActive: true } }),
      prisma.marketplace.findFirst({ where: { channel: c.channel, code: c.marketplace, isActive: true }, select: { language: true } }),
    ])
    if (!account?.isActive || account.channelType !== c.channel || account.marketplace && !['GLOBAL', c.marketplace].includes(account.marketplace) || !market?.language) throw new Error('Choose an active account and configured marketplace that match this destination')
    for (const language of await marketLanguages(c.channel, c.marketplace)) includedLocales.add(language)
    const contract = await contracts.channel(c.channel, c.marketplace, c.category)
    const categoryKey = transferCategoryField(c.channel)
    scopes.push({ ...c, locale: '', sheet: `${c.channel} ${c.marketplace} ${i + 1}`, entity: 'Overrides',
      fields: [{ field: categoryKey, label: 'Channel category', type: c.channel === 'ETSY' ? 'number' : 'text', required: c.channel === 'SHOPIFY' ? 'optional' : 'required' }, ...contract.fields.filter(f => f.fieldKey !== categoryKey).map(f => ({ ...channelWorkbookField(f), schemaVersion: contract.schemaVersion, help: `${channelWorkbookField(f).help} ${contract.fetchedAt ? `Schema retrieved ${contract.fetchedAt}.` : `Field definition ${contract.schemaVersion ?? 'unversioned'}.`}` }))],
      rows: [{ ...c, locale: '', row: 2, entity: 'Listings', sku: '', aliasKey: '', field: categoryKey, action: c.category ? 'SET' : '' as TransferRow['action'], value: c.category ? c.channel === 'ETSY' ? Number(c.category) : c.category : undefined }] })
  }
  if (includedLocales.size > 30) throw new Error('Choose at most 30 languages, including the languages of your listing marketplaces')
  scopes.splice(1, 0, ...[...includedLocales].map(locale => ({ ...emptyScope, sheet: `Content ${locale}`, entity: 'Products' as const, locale,
    fields: cols.filter(c => !c.slot && (content.has(c.key) || c.storage === 'localizedContent')).map(masterWorkbookField), rows: [] })))
  return writeCatalogWorkbook(scopes)
}

/** Export grouping includes every account, marketplace, category and language; never merges those axes. */
export function workbookScopesForRows(rows: TransferRow[], fieldsForRow: (row: TransferRow) => WorkbookField[], categoryForRow: (row: TransferRow) => string): WorkbookScope[] {
  const scopes = new Map<string, WorkbookScope>()
  const seenFields = new Map<string, Set<WorkbookField[]>>()
  for (const row of rows) {
    const category = row.entity === 'Products' ? '' : categoryForRow(row)
    const key = JSON.stringify([row.entity === 'Products' ? 'Products' : 'Overrides', row.channel, row.accountId, row.marketplace, row.locale, category])
    let scope = scopes.get(key)
    if (!scope) {
      scope = { ...emptyScope, sheet: row.entity === 'Products' ? row.locale ? `Content ${row.locale}` : 'Products' : `${row.channel} ${row.marketplace} ${scopes.size + 1}`,
        entity: row.entity === 'Products' ? 'Products' : 'Overrides', channel: row.channel, accountId: row.accountId, marketplace: row.marketplace, locale: row.locale, category, fields: [], rows: [] }
      scopes.set(key, scope)
      seenFields.set(key, new Set())
    }
    scope.rows.push(row)
    const fields = fieldsForRow(row)
    if (!seenFields.get(key)!.has(fields)) {
      const known = new Set(scope.fields.map(f => f.field))
      for (const field of fields) if (!known.has(field.field)) { scope.fields.push(field); known.add(field.field) }
      seenFields.get(key)!.add(fields)
    }
  }
  return [...scopes.values()]
}

import { normalizeLanguage } from './content-language.js'
import { PRIMARY_CONTENT_LOCALE } from './content-locale.js'
import { listActiveConnections } from '../connection-resolver.service.js'
import type { Prisma } from '@prisma/client'
import { TRANSFER_CHANNELS, type ProductTransferBoundary, ProductTransferOptions, ProductTransferSelection, TransferRow } from '@nexus/shared/catalog-transfer'
import prisma from '../../db.js'
import { marketLanguages } from './market-languages.js'
import { TransferConflict } from './catalog-transfer.service.js'

const productIdentity = { id: true, sku: true, parentId: true } as const
const listingIdentity = { id: true, productId: true, channel: true, channelConnectionId: true, marketplace: true, aliasKey: true } as const
const listingKey = (row: Pick<TransferRow, 'sku' | 'channel' | 'accountId' | 'marketplace' | 'aliasKey'>) => JSON.stringify([row.sku, row.channel, row.accountId, row.marketplace, row.aliasKey])
const indexes = new WeakMap<ProductTransferBoundary, { products: Map<string, ProductTransferBoundary['products'][number]>; listings: Map<string, ProductTransferBoundary['listings'][number]> }>()
function boundaryIndex(boundary: ProductTransferBoundary) {
  let index = indexes.get(boundary)
  if (!index) {
    const skuById = new Map(boundary.products.map(p => [p.id, p.sku]))
    index = { products: new Map(boundary.products.map(p => [p.sku, p])), listings: new Map(boundary.listings.map(l => [listingKey({ ...l, sku: skuById.get(l.productId)! }), l])) }
    indexes.set(boundary, index)
  }
  return index
}
const validLocale = (s: string) => /^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/.test(s)

export async function productTransferOptions(productId: string): Promise<ProductTransferOptions> {
  const product = await prisma.product.findFirst({ where: { id: productId, deletedAt: null }, select: productIdentity })
  if (!product) throw new Error('This product is unavailable')
  const rootId = product.parentId ?? product.id
  const products = await prisma.product.findMany({ where: { deletedAt: null, OR: [{ id: rootId }, { parentId: rootId }] }, select: productIdentity, orderBy: { sku: 'asc' }, take: 501 })
  if (!products.some(p => p.id === rootId)) throw new Error('The parent product is unavailable')
  if (products.length > 500) throw new Error('Use Catalog import & export for groups larger than 500 products')
  const [listings, accounts, markets, content, aliases, root] = await Promise.all([
    prisma.channelListing.findMany({ where: { productId: { in: products.map(p => p.id) }, channel: { in: TRANSFER_CHANNELS } }, select: listingIdentity, orderBy: { id: 'asc' }, take: 5001 }),
    Promise.all(TRANSFER_CHANNELS.map(channel => listActiveConnections(channel))).then(accounts => accounts.flat()),
    prisma.marketplace.findMany({ where: { isActive: true }, select: { channel: true, code: true, name: true, language: true, languages: true }, orderBy: { code: 'asc' } }),
    prisma.product.findMany({ where: { id: { in: products.map(p => p.id) } }, select: { translations: { select: { language: true } } } }),
    prisma.productListingAlias.findMany({ where: { productId: rootId }, select: { id: true, label: true, status: true } }),
    prisma.product.findUnique({ where: { id: rootId }, select: { familyId: true } }),
  ])
  if (listings.length > 5000) throw new Error('Use Catalog import & export for groups larger than 5,000 listings')
  const locales = [...new Set([PRIMARY_CONTENT_LOCALE, ...content.flatMap(p => p.translations.map(row => normalizeLanguage(row.language))), ...markets.flatMap(m => marketLanguages(m.channel, m.code, [m]))])].filter(validLocale).sort()
  const aliasById = new Map(aliases.map(a => [a.id, a]))
  return { productId, rootId, products, locales, familyId: root?.familyId ?? null,
    listings: listings.filter(l => !l.aliasKey || aliasById.get(l.aliasKey)?.status === 'ACTIVE').map(l => ({ id: l.id, productId: l.productId, channel: l.channel, accountId: l.channelConnectionId ?? '', marketplace: l.marketplace, aliasKey: l.aliasKey,
      aliasLabel: l.aliasKey ? aliasById.get(l.aliasKey)?.label || `Listing ${l.aliasKey.slice(-6)}` : 'Primary listing' })),
    accounts: accounts.map(a => ({ id: a.id, channelType: a.channelType, marketplace: a.marketplace, accountLabel: a.accountLabel, displayName: `${a.accountLabel || a.displayName || a.channelType} · ${a.id.slice(-6)}` })),
    markets: markets.map(m => ({ ...m, language: marketLanguages(m.channel, m.code, [m])[0] })),
  }
}

function ids(value: unknown, name: string, max: number) {
  if (!Array.isArray(value) || value.length > max || value.some(v => typeof v !== 'string' || !v.trim()) || new Set(value).size !== value.length) throw new Error(`Select valid ${name}`)
  return value as string[]
}

export async function resolveProductTransferBoundary(productId: string, input: ProductTransferSelection): Promise<ProductTransferBoundary> {
  if (!input || typeof input.includeShared !== 'boolean') throw new Error('Select shared details or existing listings')
  const productIds = ids(input.productIds, 'products', 500), listingIds = ids(input.listingIds, 'listings', 5000), locales = [...new Set(ids(input.locales, 'languages', 100).map(normalizeLanguage))]
  if (!productIds.length || !input.includeShared && !listingIds.length) throw new Error('Select at least one product and a data destination')
  if (!input.includeShared && locales.length) throw new Error('Shared languages require shared product details')
  const options = await productTransferOptions(productId)
  const products = options.products.filter(p => productIds.includes(p.id))
  if (products.length !== productIds.length) throw new Error('Every selected SKU must belong to this product and its variants')
  const listings = options.listings.filter(l => listingIds.includes(l.id) && productIds.includes(l.productId))
  if (listings.length !== listingIds.length) throw new Error('Every selected listing must belong to a selected SKU')
  for (const listing of listings) {
    const account = options.accounts.find(a => a.id === listing.accountId && a.channelType === listing.channel)
    if (!account || account.marketplace && !['GLOBAL', listing.marketplace].includes(account.marketplace)) throw new Error('A selected listing needs an active, matching seller account')
    if (!options.markets.some(m => m.channel === listing.channel && m.code === listing.marketplace)) throw new Error('A selected listing marketplace is unavailable')
  }
  if (locales.some(l => !options.locales.includes(l))) throw new Error('Select an available content language')
  return { productId, rootId: options.rootId, products, listings, locales, includeShared: input.includeShared }
}

/** Check every action, including unchanged cells. Uploads never expand the saved selection. */
export function assertProductTransferRows(boundary: ProductTransferBoundary, rows: TransferRow[]) {
  const { products, listings } = boundaryIndex(boundary)
  for (const row of rows) {
    if (!products.has(row.sku)) throw new TransferConflict(`${row.sku}: this SKU is outside the selected products`)
    if (row.entity === 'Products') {
      if (!boundary.includeShared || row.channel || row.accountId || row.marketplace || row.aliasKey || row.locale && !boundary.locales.includes(row.locale)) throw new TransferConflict(`${row.sku}: shared details or this language are outside the selected scope`)
    } else if (row.locale || !listings.has(listingKey(row))) throw new TransferConflict(`${row.sku}: this account, marketplace or listing is outside the selected scope`)
  }
}

/** Called again inside each serializable write transaction, including recovered/retried jobs. */
export async function checkProductTransferBoundary(boundary: ProductTransferBoundary, rows?: TransferRow[], db: Prisma.TransactionClient = prisma) {
  if (rows) assertProductTransferRows(boundary, rows)
  const anchor = await db.product.findFirst({ where: { id: boundary.productId, deletedAt: null }, select: productIdentity })
  if (!anchor || (anchor.parentId ?? anchor.id) !== boundary.rootId) throw new TransferConflict('The product group changed. Open a new product import review.')
  if (anchor.parentId && !await db.product.findFirst({ where: { id: boundary.rootId, deletedAt: null, parentId: null }, select: { id: true } })) throw new TransferConflict('The parent product is unavailable. Open a new product import review.')
  const index = boundaryIndex(boundary)
  const expected = rows ? [...new Set(rows.map(r => r.sku))].flatMap(sku => index.products.get(sku) ?? []) : boundary.products
  const products = await db.product.findMany({ where: { id: { in: expected.map(p => p.id) }, deletedAt: null }, select: productIdentity })
  if (expected.some(p => !products.some(c => c.id === p.id && c.sku === p.sku && c.parentId === p.parentId))) throw new TransferConflict('A selected SKU or its parent changed. Export and review the selection again.')
  const selected = rows ? [...new Set(rows.filter(r => r.entity !== 'Products').map(listingKey))].flatMap(key => index.listings.get(key) ?? []) : boundary.listings
  if (!selected.length) return
  const listings = await db.channelListing.findMany({ where: { id: { in: selected.map(l => l.id) } }, select: listingIdentity })
  if (selected.some(l => !listings.some(c => c.id === l.id && c.productId === l.productId && c.channel === l.channel && c.channelConnectionId === l.accountId && c.marketplace === l.marketplace && c.aliasKey === l.aliasKey))) throw new TransferConflict('A selected listing moved or was replaced. Export and review the selection again.')
}
